work echo x 2>> src/a.py
work echo x 1> src/a.py
work echo x &> src/a.py
work echo x &>src/a.py
work echo x &>> src/a.py
work echo x >| src/a.py
work echo x >|src/a.py
work echo x >& src/a.py
work echo x >&src/a.py
work (echo x > a.py)
