guard_says_what_it_could_not_read() {
  . ./hooks/_classify.sh
  KIT_A6=$(pwd -P); bad=0
  P=$(a6_project)
  # Each of these is refused, and the refusal says the target could not be read and how the command
  # makes it readable, on both channels. A false path is not named: > $(mktemp) used to stop on "(".
  while IFS= read -r c; do
    [ -n "$c" ] || continue
    o=$(cd "${P:?}" && python3 -I -c 'import json,sys; print(json.dumps({"cwd":sys.argv[1],"session_id":"s-main","tool_name":"Bash","tool_input":{"command":sys.argv[2]}}))' "$P" "$c" | "$KIT_A6/hooks/role-guard.sh" 2>/dev/null)
    r=$(printf '%s' "$o" | python3 -I -c 'import json,sys; d=json.load(sys.stdin); print(d["hookSpecificOutput"]["permissionDecision"]); print(d["hookSpecificOutput"]["permissionDecisionReason"]); print(d["systemMessage"])' 2>&1)
    case $r in deny*) ;; *) echo "not refused: $c: $r"; bad=1 ;; esac
    case $r in *'could not be read'*'could not be read'*) ;; *) echo "the refusal does not say it on both channels: $c: $r"; bad=1 ;; esac
    case $r in *'same command'*) ;; *) echo "the refusal does not say how: $c"; bad=1 ;; esac
    l=$(tail -1 "$P/.claude/manager-kit.log")
    case $l in *'could not be read'*) ;; *) echo "the stop line does not say it: $c: $l"; bad=1 ;; esac
    w=$(MK_EXPLAIN=1 classify_bash "$c" 2>&1 >/dev/null | tail -1)
    case $w in *'is work'*) echo "the reason names a false path: $w"; bad=1 ;; esac
  done <<'T'
echo x > $TMP/lauf.json
echo x > "$TMP/lauf.json"
echo x > ${TMP}/lauf.json
echo x > $QQ_Q/schlange.txt
source umgebung.sh; echo x > $QQ_Q/schlange.txt
cd $TMP && cat > lauf.json
echo x > $(mktemp)
touch $X
mkdir -p "$X/y"
T
  # The value of a secret does not reach the sentence by this door either.
  o=$(cd "${P:?}" && python3 -I -c 'import json,sys; print(json.dumps({"cwd":sys.argv[1],"session_id":"s-main","tool_name":"Bash","tool_input":{"command":sys.argv[2]}}))' "$P" 'echo x > "$X/ok DB_TOKEN=hunter2-FAKE/a.py"' | "$KIT_A6/hooks/role-guard.sh" 2>/dev/null)
  case $o in *'could not be read'*) ;; *) echo "the secret case was not refused as unreadable: $o"; bad=1 ;; esac
  case $o in *hunter2-FAKE*) echo "the secret stands in the refusal: $o"; bad=1 ;; esac
  # A target the hook could read is not said to be unreadable.
  o=$(cd "${P:?}" && python3 -I -c 'import json,sys; print(json.dumps({"cwd":sys.argv[1],"session_id":"s-main","tool_name":"Bash","tool_input":{"command":sys.argv[2]}}))' "$P" 'API_KEY=src/a.py; echo x > $API_KEY' | "$KIT_A6/hooks/role-guard.sh" 2>/dev/null)
  case $o in *'"deny"'*) ;; *) echo "API_KEY=src/a.py was not refused"; bad=1 ;; esac
  case $o in *'could not be read'*) echo "a readable target was called unreadable: $o"; bad=1 ;; esac
  # A command too large to read says so as well, and stays refused.
  big=$(mktemp); printf 'echo %s > .claude/a.txt' "$(printf 'x%.0s' $(seq 1 70000))" > "$big"
  o=$(cd "${P:?}" && python3 -I -c 'import json,sys; print(json.dumps({"cwd":sys.argv[1],"session_id":"s-main","tool_name":"Bash","tool_input":{"command":open(sys.argv[2]).read()}}))' "$P" "$big" | "$KIT_A6/hooks/role-guard.sh" 2>/dev/null)
  case $o in *'"deny"'*'could not be read'*) ;; *) echo "a command too long did not say it: $(printf '%s' "$o" | cut -c1-200)"; bad=1 ;; esac
  # And the refusal that survives a dead program says it too, written in the shell. A copy of the
  # hooks whose program raises, the same way a failing redaction is asked.
  c=$(mktemp -d); cp -R hooks "$c/hooks"
  awk '{ if (!done && index($0, "stops = crossings = 0")) { print "raise SystemExit(3)"; done = 1 } print }' "$c/hooks/role-guard.sh" > "$c/g" && cat "$c/g" > "$c/hooks/role-guard.sh"
  o=$(cd "${P:?}" && python3 -I -c 'import json,sys; print(json.dumps({"cwd":sys.argv[1],"session_id":"s-main","tool_name":"Bash","tool_input":{"command":sys.argv[2]}}))' "$P" 'echo x > $TMP/a' | "$c/hooks/role-guard.sh" 2>/dev/null)
  case $o in *'"deny"'*'could not be read'*) ;; *) echo "the short form did not say it: $(printf '%s' "$o" | cut -c1-300)"; bad=1 ;; esac
  printf '%s' "$o" | python3 -I -c 'import json,sys; json.load(sys.stdin)' 2>/dev/null || { echo "the short form is no JSON"; bad=1; }
  return $bad
}

classifier_reads_a_write_in_program_text() {
  . ./hooks/_classify.sh
  bad=0
  # Most one-liners only read, 5797 distinct real python -c against 434 that carry a write word, so
  # the body is asked what it writes and not whether it exists. What is readable decides; a write
  # whose target is no literal is said, and stopped; the rest is the limit README.md names.
  a6_table 'a write in program text' <<'T' || bad=1
work python3 -c "open('src/r.py','w')"
work python3 -c "open('src/r.py','w').write('x')"
work python3 -c 'open("src/r.py","w")'
work python3 -c "open('src/r.py', mode='w')"
work python3 -c "open('src/r.py','a')"
work python3 -c "open('src/r.py','wb')"
work python3 -c "import pathlib; pathlib.Path('src/r.py').write_text('x')"
work python3 -c "from pathlib import Path; Path('src/r.py').write_bytes(b'x')"
work python3 -c "import shutil; shutil.copy('.claude/a','src/r.py')"
work python3 -c "import shutil; shutil.move('.claude/a','src/r.py')"
work python3 -c "import shutil; shutil.rmtree('src')"
work python3 -c "import os; os.remove('src/r.py')"
work python3 -c "import os; os.rename('.claude/a','src/r.py')"
work python3 -c "import os; os.makedirs('src/neu')"
work python3 -I -c "open('src/r.py','w')"
work python3 -u -c "open('src/r.py','w')"
work python -c "open('src/r.py','w')"
work python3.12 -c "open('src/r.py','w')"
work .venv/bin/python -c "open('src/r.py','w')"
work /usr/bin/env python3 -c "open('src/r.py','w')"
work cat a | python3 -c "import sys; open('src/r.py','w').write(sys.stdin.read())"
work cd src && python3 -c "open('r.py','w')"
work python3 -c "p='src/r.py'; open(p,'w')"
work python3 -c "from pathlib import Path; p=Path('src/r.py'); p.write_text('x')"
work python3 -c "open('.claude/../src/r.py','w')"
work node -e "require('fs').writeFileSync('src/a.js','x')"
work node -e "const fs=require('fs'); fs.appendFileSync('src/a.js','x')"
work node -e "require('fs').mkdirSync('src/neu')"
work node -e "require('fs').rmSync('src',{recursive:true})"
work node -e "require('fs').createWriteStream('src/a.js')"
work node --eval "require('fs').writeFileSync('src/a.js','x')"
work ruby -e "File.write('src/a.rb','x')"
work ruby -e "File.open('src/a.rb','w')"
work ruby -e "require 'fileutils'; FileUtils.rm_rf('src')"
work perl -e 'open(F,">src/a.pl")'
work perl -e 'open(my $f, ">", "src/a.pl")'
work perl -e 'unlink("src/a.pl")'
work awk 'BEGIN{print "x" > "src/a.py"}'
bookkeeping python3 -c "open('.claude/r.txt','w')"
bookkeeping S=.claude/x; python3 -c "open('$S/r.txt','w')"
bookkeeping python3 -c "open('$NICHTDA/r.txt','w')"
work S=src; python3 -c "open('$S/r.py','w')"
bookkeeping python3 -c "open('a.md','w')"
bookkeeping python3 -c "from pathlib import Path; Path('.claude/r.txt').write_text('x')"
bookkeeping python3 -c "import shutil; shutil.copy('src/a.py','.claude/a.py')"
bookkeeping cd .claude && python3 -c "open('r.txt','w')"
bookkeeping node -e "require('fs').writeFileSync('.claude/a.js','x')"
bookkeeping ruby -e "File.write('.claude/a.rb','x')"
bookkeeping perl -e 'open(F,">.claude/a.pl")'
bookkeeping awk 'BEGIN{print "x" > ".claude/a.txt"}'
T
  # The great majority, and these are the false alarms it must not grow.
  a6_table 'program text that only reads' <<'T' || bad=1
bookkeeping python3 -c "print(1)"
bookkeeping python3 -c "print(1 > 2); print(3)"
bookkeeping python3 -c "import json,sys; print(json.load(sys.stdin))"
bookkeeping python3 -c "print(open('src/a.py').read())"
bookkeeping python3 -c "print(open('src/a.py','r').read())"
bookkeeping python3 -c "print(open('src/a.py','rb').read())"
bookkeeping python3 -c "s='a'.replace('a','b'); print(s)"
bookkeeping python3 -c "import os; print(os.path.exists('src/a.py'))"
bookkeeping python3 -c "import os; print(os.listdir('src'))"
bookkeeping python3 -c "print('open(1,2)')"
bookkeeping python3 src/run.py
bookkeeping node -e "console.log(require('fs').readFileSync('src/a.js','utf8'))"
bookkeeping node --version
bookkeeping perl -e 'print "x > y\n"'
bookkeeping perl -ne 'print if /a/' src/a.py
bookkeeping ruby -e "puts File.read('src/a.rb')"
bookkeeping awk '{print $1 > 3}' src/a
bookkeeping awk '$1 > "a" {print $2}' src/a
bookkeeping grep -n "python3 -c" src/a.py
bookkeeping echo "open('src/r.py','w')"
T
  # A body that is handed in on a heredoc is the same program, read by the same rule.
  g=$(classify_bash "python3 - <<'PY'
open('src/r.py','w').write('x')
PY"); [ "$g" = work ] || { echo "a heredoc that writes a work literal -> $g"; bad=1; }
  g=$(classify_bash "python3 - <<'PY'
open('.claude/r.txt','w').write('x')
PY"); [ "$g" = bookkeeping ] || { echo "a heredoc that writes bookkeeping -> $g"; bad=1; }
  g=$(classify_bash "cd .claude && python3 - <<'PY'
open('r.txt','w').write('x')
PY"); [ "$g" = bookkeeping ] || { echo "a heredoc behind a cd -> $g"; bad=1; }
  g=$(classify_bash "python3 - <<'PY'
print(open('src/a.py').read())
PY"); [ "$g" = bookkeeping ] || { echo "a heredoc that reads -> $g"; bad=1; }
  # A write into the scratchpad from a program that reads the tree opens no narrowing: it was silent.
  g=$(classify_bash "python3 - <<'PY'
d = open('src/a.py').read()
open('/tmp/claude-501/p/s/scratchpad/kopie.py','w').write(d)
PY"); [ "$g" = bookkeeping ] || { echo "a program reading the tree into the scratchpad -> $g"; bad=1; }
  g=$(classify_bash "cat > .claude/a.txt <<'PY'
open('src/r.py','w').write('x')
PY"); [ "$g" = bookkeeping ] || { echo "a body that is stored and not run -> $g"; bad=1; }
  # And a multi line -c, which is a shape of its own because the scan reads line by line.
  g=$(classify_bash "python3 -c \"
import sys
open('src/r.py','w').write('x')
\""); [ "$g" = work ] || { echo "a multi line -c -> $g"; bad=1; }
  # THE LIMIT, and it is a line of its own because it is a silent pass. A write whose target is no
  # literal and no name assigned one is not read: 127 distinct main session commands, 621 weighted
  # in the corpus of MK-A6, read by hand mostly bookkeeping through sys.argv. README.md names it.
  a6_table 'the limit of program text' <<'T' || bad=1
bookkeeping python3 -c "import sys; open(sys.argv[1],'w')" src/a.py
bookkeeping python3 -c "p=foo(); open(p,'w')"
bookkeeping python3 -c "from shutil import copy; copy('a','src/b.py')"
T
  # More write calls than the scan reads is not the limit: that one is too long to read.
  many=$(printf "open('a.md','w');%.0s" $(seq 1 70))
  g=$(classify_bash "python3 -c \"$many\""); [ "$g" = work ] || { echo "seventy write calls -> $g, expected work"; bad=1; }
  w=$(MK_EXPLAIN=1 classify_bash "python3 -c \"$many\"" 2>&1 >/dev/null | tail -1)
  case $w in *'could not be read'*) ;; *) echo "seventy write calls did not say it: $w"; bad=1 ;; esac
  return $bad
}

classifier_reads_a_commit_as_no_write() {
  . ./hooks/_classify.sh
  bad=0
  # A COMMIT WRITES NO PATH OF THE WORK. The boundary of this kit is a path, and git commit -a puts
  # nothing on the line that is one: what it takes along is already in the tree, and it was written
  # by whoever wrote it. MK-A6 stopped it and let git add -A && git commit through, 10 distinct
  # commands against 232 in the main sessions of its corpus, so the stop guarded nothing and was a
  # false alarm every time it fired. README.md says it in one sentence. The right behaviour of the
  # same shape is the write that stands on the same line, and the neighbours are the git writes that
  # do name a path: those are still read.
  a6_table 'a commit is free' <<'T' || bad=1
bookkeeping git commit -am x
bookkeeping git commit -a -m x
bookkeeping git commit -m x -a
bookkeeping git commit --all -m x
bookkeeping git commit -qam x
bookkeeping git -C src commit -am x
bookkeeping git -c a=b commit -am x
bookkeeping cd .claude && git add a && git commit -am x
bookkeeping git add -A && git commit -m x
bookkeeping git add -A && git commit -am x
bookkeeping git commit -m x
bookkeeping git commit -m "a -a b"
bookkeeping git commit --amend -m x
bookkeeping git commit -F .claude/msg.txt
bookkeeping git add .claude/a.md && git commit -m x
bookkeeping git log -a
bookkeeping git status -a
bookkeeping git diff -a
bookkeeping git commit --author=a -m x
bookkeeping git commit -mall
bookkeeping git commit "a -a b"
work git commit -am x > src/a.py
work git commit -am x && rm src/a.py
work git commit -m x; echo y > src/a.py
work git clone https://h.invalid/r.git src/r
work git restore src/a.py
work git checkout -- src/a.py
T
  # The refusal text that said what goes instead is gone with the stop: nothing in the code may still
  # name it, so a reader of the trace is not told to avoid a command that passes.
  if grep -q 'commit_all\|@@a@@\|takes along every tracked' hooks/_classify.sh; then
    echo "hooks/_classify.sh still carries the stop of git commit -a"; bad=1
  fi
  # THE DOCUMENT SAYS IT. One sentence, in the Bash gap, and the two places that named the stop say
  # something else now: the list of what is read, and the paragraph about the git subcommands.
  grep -qF 'A commit is no write into the work, so it is free, even when it takes along the work of a hand' README.md ||
    { echo "README.md does not say that a commit is free"; bad=1; }
  if grep -q 'is the one that is stopped' README.md; then echo "README.md still says git commit -a is stopped"; bad=1; fi
  if grep -q 'git clone`, and `git commit -a`' README.md; then echo "README.md still lists git commit -a among what is read"; bad=1; fi
  return $bad
}

# ------------------------------------------------------------------------------- MK-R1
# A redirection written with no space is a redirection. echo x>src/a.py was named in README.md as a
# limit since the first version of this measure, because a ">" inside a word is also what a comparison
# in program text looks like. Counted for MK-R1 over the corpus of that task: see the report. The
# scan reads quoted text and heredoc bodies out of the way first, so what is left of a ">" glued
# to a word is the shell's own, outside arithmetic and [[ ]].
classifier_reads_a_redirection_glued_to_its_word() {
  . ./hooks/_classify.sh
  bad=0
  # 1. DERIVED. Every case of the tables in this file that spells a redirection with a space on each
  #    side has a twin with none, and the twin is judged as the case is: the list is the tables, not
  #    what was typed here. Both verdicts occur among them, or the list would hold nothing.
  #    The spaced case is asked now, in a project with .claude and src in it, and not read off the table:
  #    a line of a table is a verdict about a directory that is not this one.
  d=$(newrepo); n=0; nw=0; nb=0
  while IFS= read -r line; do
    c=${line#* }
    twin=$(printf '%s' "$c" | sed -e 's/ >> */>>/g' -e 's/ > */>/g')
    [ "$twin" != "$c" ] || continue
    n=$((n + 1))
    v=$(cd "${d:?}" && classify_bash "$c" 2>/dev/null)
    case $v in work) nw=$((nw + 1)) ;; *) nb=$((nb + 1)) ;; esac
    g=$(cd "${d:?}" && classify_bash "$twin" 2>/dev/null)
    [ "$g" = "$v" ] || { echo "[glued twin] -> $g, the spaced case is $v: $twin"; bad=1; }
  done < <(grep -E '^(work|bookkeeping) .* >>? ' tests/run.sh)
  [ "$n" -ge 20 ] && [ "$nw" -gt 0 ] && [ "$nb" -gt 0 ] || { echo "the twins are too few to hold anything: $n, $nw work, $nb bookkeeping"; bad=1; }
  # 2. The shapes of the order, typed, because they are the order's own list. The first block is the
  #    right behaviour and its neighbours; the second is what must stay what it was, measured at 1b4da29.
  #    MK-R1b added the shapes two guards of glued_at decide and no case held: the & in front of the >
  #    (x&>f is the operator and goes with the >; left in the word, rm src/a.py&>/dev/null reads as
  #    bookkeeping, a silent pass, and cp src/a.py docs/b.md&>/dev/null as work) and a target a program
  #    text writes that carries a > (it is one word and not a redirection).
  #    MK-R5-2: ((a>b)) names b, which reads as bookkeeping on its own, so those rows could not tell a
  #    word that is left alone from one that is split: with the (( rule removed they stayed green. The
  #    rows ((x>src/a)) name a target under src/, which would be work if the > were read as a redirection.
  a6_table 'a redirection glued to its word' <<'T' || bad=1
work echo x>src/a.py
work echo x>>src/a.py
work echo x>|src/a.py
work echo x&>src/a.py
work echo x&>>src/a.py
work echo x> src/a.py
work echo $(date)>src/a.py
work (echo x>src/a.py)
work (>src/a.py)
work (a>b)
work (cat<in.txt>src/a.py)
work echo x; (a>src/a.py)
work echo x;(a>src/a.py)
work (>>src/a.py)
work ( >src/a.py )
