work x=1; ((x>0))>src/b.py
work (( x>src/a ))>src/b.py
work ((x>src/a)) >src/b.py
work ((x>src/a)) && echo y>src/b.py
work FOO=1>src/a.py
work ls src>src/list.txt
work cd src && echo x>a.py
work echo "a;b">src/a.py
work echo "a b">src/a.py
