work echo x>src/a.py|tail
work [ a>b ]
work [ a > b ]
work cmd 1>src/a.py
work echo x 2>src/a.py
work rm src/a.py&>/dev/null
work rm src/a.py&>>/dev/null
work rm src/a.py &>/dev/null
work rm src/a.py>/dev/null
work python3 -c "open('.claude/a>b','w')">src/z
work python3 -c "open('src/a>b','w')"
bookkeeping echo x>.claude/a
bookkeeping echo x>>.claude/a
bookkeeping echo x>|.claude/a
bookkeeping echo x&>.claude/a
bookkeeping cp src/a.py docs/b.md&>/dev/null
bookkeeping rm docs/a.md>/dev/null
bookkeeping python3 -c "open('.claude/a>b','w')"
bookkeeping python3 -c "open('.claude/a>b','w')">.claude/z
