bookkeeping echo $((1>2))
bookkeeping echo $(( a>b ))
bookkeeping echo ${X:-a>b}
bookkeeping ((a>b))
bookkeeping ((a>b)) && echo y
bookkeeping ((x>src/a))
bookkeeping ((x>src/a)) && echo y
bookkeeping ((x>src/a))>/dev/null
bookkeeping ((x>src/a))>.claude/z
bookkeeping ((x>src/a))>&2
bookkeeping ((x>src/a))2>&1
bookkeeping ((x>(a+1)))
bookkeeping ((x>=src/a))
