# ---------------------------------------------------------------- the week says only what it knows
# MK-A7. tools/week-verdict.sh is the witness the owner decides on, so every sentence of it is held
# to one question: can this command know that? Four helpers build the fixtures, and none of them
# types a result: the day of a log line is the day git gives the commit, and every expected count
# is asked of git or of the fixture, never written down.
wv_git() { _wg=$1; shift; git -C "$_wg" -c user.name=t -c user.email=t@example.invalid "$@"; }
wv_init() { git -C "$1" init -q && git -C "$1" symbolic-ref HEAD refs/heads/main; }
wv_commit() { # dir path [date]: one commit that appends a line to that path
  mkdir -p "$(dirname "$1/$2")"; printf 'x\n' >> "$1/$2"
  wv_git "$1" add -- "$2" || return 1
  if [ -n "${3-}" ]; then GIT_COMMITTER_DATE=$3 GIT_AUTHOR_DATE=$3 wv_git "$1" commit -qm "add $2"
  else wv_git "$1" commit -qm "add $2"; fi
}
wv_day() { TZ=UTC git -C "$1" log -1 --format=%cd --date=short-local; }
wv_log() { # dir day event...: one guard line per event, on that day
  _wd=$1; _wday=$2; shift 2; mkdir -p "$_wd/.claude"
  for _we in "$@"; do
    printf '{"ts": "%sT12:00:00Z", "event": "%s", "tool": "Write", "subject": "src/a.py", "reason": "r"}\n' "$_wday" "$_we"
  done >> "$_wd/.claude/manager-kit.log"
}
# wv_run <seconds> <args...> -> wv_rc and wv_out (stdout and stderr together); 124 when the command
# was still running at the limit. The command runs in a session of its own, so what holds it is killed with it.
wv_run() {
  wv_out=$(python3 -I -c '
import os, signal, subprocess, sys
lim = float(sys.argv[1])
p = subprocess.Popen(["bash", "tools/week-verdict.sh"] + sys.argv[2:], stdin=subprocess.DEVNULL,
                     stdout=subprocess.PIPE, stderr=subprocess.STDOUT, start_new_session=True)
try:
    out, _ = p.communicate(timeout=lim)
    rc = p.returncode
except subprocess.TimeoutExpired:
    os.killpg(p.pid, signal.SIGKILL)
    out, _ = p.communicate()
    rc = 124
sys.stdout.write("%d\n" % rc)
sys.stdout.flush()
sys.stdout.buffer.write(out)' "$@")
  wv_rc=${wv_out%%$'\n'*}; wv_out=${wv_out#*$'\n'}
}
# wv_stdout <args...> -> wv_rc, wv_out (stdout only) and wv_err (stderr only)
wv_stdout() {
  _wf=$(mktemp); wv_out=$(bash tools/week-verdict.sh "$@" 2>"$_wf" </dev/null); wv_rc=$?
  wv_err=$(cat "$_wf"); rm -f "$_wf"
}
wv_digest() { # every file under a directory: name, size, mtime and content
  python3 -I -c '
import hashlib, os, sys
h = hashlib.sha1()
for base, dirs, files in sorted(os.walk(sys.argv[1])):
    dirs.sort()
    for f in sorted(files):
        p = os.path.join(base, f)
        st = os.lstat(p)
        h.update(("%s %d %d\n" % (p, st.st_size, st.st_mtime_ns)).encode())
        if os.path.isfile(p) and not os.path.islink(p):
            h.update(open(p, "rb").read())
print(h.hexdigest())' "$1"
}

# THE QUIET WEEK. The guard ran on every day that carries commits and recorded no stop and no crossing.
# Git has one author and no field that says which line a commit came out of, so this command cannot
# know whether the work was handed out or went through a hole the guard cannot see. It used to say
# that the coordinator had never reached for a work path with its own hands, and it headed that HELD.
# Measured 2026-11-07 at 6018feb: a command the guard lets through (README.md, "The Bash gap"), a
# commit carrying src/new.py, and the verdict was HELD with "never reached".
a_quiet_week_is_not_called_held() {
  bad=0
  # The silent way is derived: candidates are typed, the ones the real guard stops are dropped by
  # asking it, and the first of the rest builds the fixture. touch is the control and is stopped.
  silent=
  for c in 'touch src/new.py' 'echo x>src/new.py' 'python3 gen.py' 'make' 'npm install'; do
    p=$(newrepo)
    q=$(mkinput "$p" "" Bash "$(python3 -I -c 'import json,sys; print(json.dumps({"command": sys.argv[1]}))' "$c")" | ./hooks/role-guard.sh)
    [ -z "$q" ] && { silent=$c; break; }
  done
  [ -n "$silent" ] || { echo 'no candidate command passes the guard in silence any more: the fixture needs another one'; return 1; }
  [ "$silent" != 'touch src/new.py' ] || { echo 'touch passes in silence, so the control of the candidates is gone'; bad=1; }
  for shape in work bookkeeping; do
    d=$(newrepo); wv_init "$d"
    case $shape in work) f=src/new.py ;; bookkeeping) f=docs/notes.md ;; esac
    wv_commit "$d" "$f" || return 1
    wv_log "$d" "$(wv_day "$d")" guard-ran
    wv_run 10 "$d" --since 2000-01-01
    [ "$wv_rc" = 1 ] || { echo "$shape: a quiet week exited $wv_rc, not 1"; bad=1; }
    for w in 'never reached' 'with its own hands' 'HELD'; do
      case $wv_out in *"$w"*) echo "$shape: a quiet week, after [$silent] passed, still says: $w"; bad=1 ;; esac
    done
    case $wv_out in *'VERDICT: QUIET'*) ;; *) echo "$shape: a quiet week is not called quiet: $(printf '%s\n' "$wv_out" | grep -m1 VERDICT)"; bad=1 ;; esac
    case $wv_out in
      *'cannot tell'*'The Bash gap'*|*'The Bash gap'*'cannot tell'*) hole=1 ;;
      *) hole=0 ;;
    esac
    case $shape in
      work) [ "$hole" = 1 ] || { echo 'a quiet week with a work commit does not say what it cannot tell, and where the hole is written'; bad=1; } ;;
      bookkeeping)
        case $wv_out in *'nothing to stop'*) ;; *) echo 'a quiet week with bookkeeping commits only does not say there was nothing to stop'; bad=1 ;; esac
        [ "$hole" = 0 ] || { echo 'a quiet week with bookkeeping commits only sends the reader to the holes of the guard'; bad=1; } ;;
    esac
  done
  [ "$bad" = 0 ] && echo "[$silent] passed in silence, a commit carried a work path, and the week was called quiet and not held"
  return $bad
}

# THE WEEK THAT FIRED. A stop line is a stop, an exception line is a declared crossing, and neither
# says what became of the other: a crossing can be declared before any stop, and nothing in the log
# says that a stop ended in a handover. The old text read "it stopped the coordinator N time(s), and M
# of those became a declared crossing rather than a handover", which for no stop and two crossings
# said "0 times, and 2 of those".
a_fired_week_states_what_the_log_holds() {
  bad=0
  for shape in '2 1' '0 2' '3 0'; do
    s=${shape% *}; x=${shape#* }
    d=$(newrepo); wv_init "$d"; wv_commit "$d" src/new.py || return 1
    ev="guard-ran"; i=0
    while [ "$i" -lt "$s" ]; do ev="$ev stop"; i=$((i + 1)); done
    i=0; while [ "$i" -lt "$x" ]; do ev="$ev exception"; i=$((i + 1)); done
    # shellcheck disable=SC2086
    wv_log "$d" "$(wv_day "$d")" $ev
    wv_run 10 "$d" --since 2000-01-01
    [ "$wv_rc" = 0 ] || { echo "[$s stops, $x crossings] exited $wv_rc, not 0"; bad=1; }
    case $wv_out in *'VERDICT: the guard was live and it fired.'*) ;; *) echo "[$s stops, $x crossings] is not a clear verdict: $(printf '%s\n' "$wv_out" | grep -m1 VERDICT)"; bad=1 ;; esac
    printf '%s\n' "$wv_out" | grep -qE "^stops: +$s\$" || { echo "[$s stops, $x crossings] the stops line is not $s"; bad=1; }
    printf '%s\n' "$wv_out" | grep -qE "^declared crossings: +$x\$" || { echo "[$s stops, $x crossings] the crossings line is not $x"; bad=1; }
    for w in 'rather than a handover' 'of those' 'is satisfied'; do
      case $wv_out in *"$w"*) echo "[$s stops, $x crossings] claims what the log does not hold: $w"; bad=1 ;; esac
    done
    # every number the text puts beside the word stopped is the stop count
    printf '%s\n' "$wv_out" | grep -oE 'stopped the coordinator [0-9]+' | while read -r _ _ _ n; do
      [ "$n" = "$s" ] || exit 1
    done || { echo "[$s stops, $x crossings] the text counts stops it does not have"; bad=1; }
    # the neighbour that has to stay: what the command cannot settle is still said
    case $wv_out in *'the Bash gap'*) ;; *) echo "[$s stops, $x crossings] no longer says what it cannot settle"; bad=1 ;; esac
    case $wv_out in *'cannot read'*) ;; *) echo "[$s stops, $x crossings] does not say that what came of a stop is unread"; bad=1 ;; esac
  done
  [ "$bad" = 0 ] && echo "three logs (stops and crossings: 2 1, 0 2, 3 0) each get the clear verdict, with the counts of the log and no claim past them"
  return $bad
}

# THE STAND READ. The window was always cut from HEAD. A checkout that stands behind its upstream
# while the work lies elsewhere read as an empty week. The fixture is built, not typed: an origin, a
# clone whose HEAD is old, a second clone that commits three times on main and once more on a branch.
wv_behind() { # -> wv_a (the clone), wv_o (origin), wv_day_new
  wv_o=$(mktemp -d); wv_o=$(CDPATH= cd -- "$wv_o" && pwd -P); git -C "$wv_o" init -q --bare
  git -C "$wv_o" symbolic-ref HEAD refs/heads/main
  wv_a=$(mktemp -d); wv_a=$(CDPATH= cd -- "$wv_a" && pwd -P)
  git clone -q "$wv_o" "$wv_a" 2>/dev/null; git -C "$wv_a" symbolic-ref HEAD refs/heads/main
  wv_commit "$wv_a" src/old.py '2020-01-01T00:00:00' || return 1
  git -C "$wv_a" push -q origin main 2>/dev/null; git -C "$wv_a" branch -q --set-upstream-to=origin/main main
  _wb=$(mktemp -d); _wb=$(CDPATH= cd -- "$_wb" && pwd -P); git clone -q "$wv_o" "$_wb" 2>/dev/null
  for _n in 1 2 3; do wv_commit "$_wb" "src/w$_n.py" || return 1; done
  git -C "$_wb" push -q origin main 2>/dev/null
  git -C "$_wb" checkout -q -b feat; wv_commit "$_wb" src/f.py || return 1; git -C "$_wb" push -q origin feat 2>/dev/null
  git -C "$wv_a" fetch -q origin
  wv_day_new=$(wv_day "$_wb")
  wv_log "$wv_a" "$wv_day_new" guard-ran stop stop
}
the_week_is_read_from_the_stand_it_is_told_to() {
  bad=0
  wv_behind || { echo 'the fixture could not be built'; return 1; }
  since=$wv_day_new
  ws() { TZ=UTC git -C "$wv_a" rev-list --count "$1" --since="$since 00:00:00"; }
  wv_run 10 "$wv_a" --since "$since"; dflt=$wv_out
  printf '%s\n' "$dflt" | grep -qE '^commits in window: +0$' || { echo "the default no longer reads HEAD: $(printf '%s\n' "$dflt" | grep '^commits in window')"; bad=1; }
  for ref in origin/main origin/feat HEAD; do
    want=$(ws "$ref")
    wv_run 10 "$wv_a" --since "$since" --ref "$ref"
    printf '%s\n' "$wv_out" | grep -qE "^commits in window: +$want\$" || { echo "--ref $ref: $(printf '%s\n' "$wv_out" | grep '^commits in window') where git counts $want"; bad=1; }
    printf '%s\n' "$wv_out" | grep -E '^history:' | grep -qF -- "$ref" || { echo "--ref $ref: the output does not name the stand it read"; bad=1; }
  done
  [ "$(ws origin/main)" -gt 0 ] || { echo 'the fixture has no commit on origin/main in the window'; bad=1; }
  # A name that is no stand, and every shape of a value that is not a name: loud, nothing on stdout,
  # nothing read, the same rc as the other input errors of this command.
  for args in '--ref no-such-ref' '--ref refs/heads/nope' '--ref -x' '--ref origin/main --ref HEAD'; do
    # shellcheck disable=SC2086
    wv_stdout "$wv_a" --since "$since" $args
    [ "$wv_rc" = 2 ] || { echo "[$args] exited $wv_rc, not 2"; bad=1; }
    [ -z "$wv_out" ] || { echo "[$args] printed on stdout, so something was read: $(printf '%s\n' "$wv_out" | head -2)"; bad=1; }
    case $wv_err in *'Nothing was read'*) ;; *) echo "[$args] does not say that nothing was read: $wv_err"; bad=1 ;; esac
  done
  # A value that starts with a dash is refused before git is asked, so it cannot become an option of git.
  stub=$(mktemp -d); realgit=$(command -v git)
  printf '#!/bin/sh\nprintf "%%s\\n" "$*" >> "%s/calls"\nexec "%s" "$@"\n' "$stub" "$realgit" > "$stub/git"; chmod +x "$stub/git"
  PATH="$stub:$PATH" wv_stdout "$wv_a" --since "$since" --ref --prefix=x
  [ "$wv_rc" = 2 ] || { echo "--ref --prefix=x exited $wv_rc, not 2"; bad=1; }
  ! grep -qF -- '--prefix' "$stub/calls" 2>/dev/null || { echo 'a --ref value that starts with a dash was handed to git'; bad=1; }
  wv_stdout "$wv_a" --since "$since" --ref ''
  [ "$wv_rc" = 2 ] && [ -z "$wv_out" ] || { echo "an empty --ref exited $wv_rc and printed: $wv_out"; bad=1; }
  wv_stdout "$wv_a" --since "$since" --ref
  [ "$wv_rc" = 2 ] && [ -z "$wv_out" ] || { echo "--ref with no value exited $wv_rc and printed: $wv_out"; bad=1; }
  wv_stdout "$wv_a" --ref --since "$since"
  [ "$wv_rc" = 2 ] && [ -z "$wv_out" ] || { echo "--ref taking --since for its value exited $wv_rc and printed: $wv_out"; bad=1; }
  wv_stdout "$wv_a" --since "$since" --ref no-such-ref
  case $wv_err in *no-such-ref*) ;; *) echo "the refusal does not name the ref: $wv_err"; bad=1 ;; esac
  # the window does not move with the stand
  wv_run 10 "$wv_a" --since "$since" --until "$since 00:00:00" --ref origin/main
  printf '%s\n' "$wv_out" | grep -qE '^commits in window: +0$' || { echo "--until 00:00:00 with --ref still counts: $(printf '%s\n' "$wv_out" | grep '^commits in window')"; bad=1; }
  [ "$bad" = 0 ] && echo "--ref reads origin/main ($(ws origin/main)), origin/feat ($(ws origin/feat)) and HEAD ($(ws HEAD)) as git counts them; a name that is none, an empty or missing value, a value that is an option and a second --ref are refused with nothing read"
  return $bad
}

the_window_behind_its_upstream_says_so_in_one_line() {
  bad=0
  wv_behind || { echo 'the fixture could not be built'; return 1; }
  since=$wv_day_new
  n=$(git -C "$wv_a" rev-list --count 'HEAD..@{upstream}'); m=$(TZ=UTC git -C "$wv_a" rev-list --count 'HEAD..@{upstream}' --since="$since 00:00:00")
  [ "$n" -gt 0 ] || { echo 'the fixture is not behind'; return 1; }
  # No network and no write: git is a stub that notes every call and runs the real one, and the whole
  # clone is hashed before and after. What the command may ask of git is read only.
  stub=$(mktemp -d); realgit=$(command -v git)
  printf '#!/bin/sh\nprintf "%%s\\n" "$*" >> "%s/calls"\nexec "%s" "$@"\n' "$stub" "$realgit" > "$stub/git"; chmod +x "$stub/git"
  before=$(wv_digest "$wv_a")
  PATH="$stub:$PATH" wv_run 10 "$wv_a" --since "$since"
  after=$(wv_digest "$wv_a")
  [ "$before" = "$after" ] || { echo 'the command changed something in the clone'; bad=1; }
  used=$(awk '{ i = 1; while ($i == "-C" || $i == "-c") i += 2; print $i }' "$stub/calls" | sort -u | tr '\n' ' ')
  for u in $used; do
    case $u in log|show|rev-parse|rev-list) ;; *) echo "the command asked git for [$u], and only reading is allowed: $used"; bad=1 ;; esac
  done
  line=$(printf '%s\n' "$wv_out" | grep -F -- '--ref')
  [ "$(printf '%s\n' "$line" | grep -c .)" = 1 ] || { echo "the behind line is not exactly one line: [$line]"; bad=1; }
  case $line in *"$n"*) ;; *) echo "the line does not carry the number of commits behind ($n): [$line]"; bad=1 ;; esac
  case $line in *"$m"*) ;; *) echo "the line does not carry the number of those inside the window ($m): [$line]"; bad=1 ;; esac
  case $line in *origin/main*) ;; *) echo "the line does not name the upstream: [$line]"; bad=1 ;; esac
  # the neighbours: asked for a stand, up to date, no upstream, and a detached HEAD say nothing
  wv_run 10 "$wv_a" --since "$since" --ref origin/main
  printf '%s\n' "$wv_out" | grep -qF -- 'behind' && { echo 'a stand that was asked for still carries the behind line'; bad=1; }
  git -C "$wv_a" merge -q --ff-only origin/main 2>/dev/null
  wv_run 10 "$wv_a" --since "$since"
  printf '%s\n' "$wv_out" | grep -qF -- 'behind' && { echo 'a checkout that is up to date carries the behind line'; bad=1; }
  git -C "$wv_a" branch -q --unset-upstream
  git -C "$wv_a" reset -q --hard HEAD~3
  wv_run 10 "$wv_a" --since "$since"
  printf '%s\n' "$wv_out" | grep -qF -- 'behind' && { echo 'a branch with no upstream carries the behind line'; bad=1; }
  d=$(newrepo); wv_init "$d"; wv_commit "$d" src/a.py || return 1; wv_log "$d" "$(wv_day "$d")" guard-ran
  wv_run 10 "$d" --since 2000-01-01
  printf '%s\n' "$wv_out" | grep -qF -- 'behind' && { echo 'a repository with no remote carries the behind line'; bad=1; }
  [ "$bad" = 0 ] && echo "HEAD $n behind its upstream ($m inside the window): one line with both numbers; git asked for [$used] only, and the clone is byte for byte as it was"
  return $bad
}

# THE LOG THE WEEK IS READ FROM. It is read like every other file of the kit under .claude: a plain
# file inside the project and nothing else. Measured 2026-11-06 at 0bc14fe and 2026-11-07 at 6018feb: a
# pipe held the command past 12 s, a link counted the stops of a foreign file, a .claude that leaves
# the project and the .claude of the home directory were read as this project's guard.
a_log_that_is_no_plain_file_is_not_read() {
  bad=0
  foreign=$(mktemp -d); foreign=$(CDPATH= cd -- "$foreign" && pwd -P)
  for shape in fifo symlink directory linkedout home above; do
    d=$(newrepo); wv_init "$d"; wv_commit "$d" src/a.py || return 1
    day=$(wv_day "$d"); h=$HOME; root=$d; home=
    case $shape in
      fifo) mkfifo "$d/.claude/manager-kit.log" ;;
      symlink) wv_log "$foreign" "$day" guard-ran stop stop stop; ln -s "$foreign/.claude/manager-kit.log" "$d/.claude/manager-kit.log" ;;
      directory) mkdir "$d/.claude/manager-kit.log" ;;
      linkedout) mkdir -p "$foreign/out"; wv_log "$foreign/out" "$day" guard-ran stop stop stop; rm -rf "$d/.claude"; ln -s "$foreign/out/.claude" "$d/.claude" ;;
      home) wv_log "$d" "$day" guard-ran stop stop stop; home=$d ;;
      above) mkdir -p "$d/below"; wv_log "$d" "$day" guard-ran stop stop stop; home=$d/below ;;
    esac
    HOME=${home:-$h} wv_run 10 "$root" --since 2000-01-01
    [ "$wv_rc" != 124 ] || { echo "$shape: the command was still waiting after 10 s"; bad=1; continue; }
    [ "$wv_rc" = 3 ] || { echo "$shape: exited $wv_rc, not 3 (inconclusive)"; bad=1; }
    printf '%s\n' "$wv_out" | grep -qE '^stops: +[0-9]' && { echo "$shape: counted stops out of a file that is not this project's record"; bad=1; }
    case $wv_out in *'NOT READ'*) ;; *) echo "$shape: does not say that the log was not read: $(printf '%s\n' "$wv_out" | grep -m1 'guard log')"; bad=1 ;; esac
    case $wv_out in *MISSING*) echo "$shape: calls a log that is there MISSING"; bad=1 ;; esac
  done
  # the neighbours: a plain log, a .claude that is a link to a directory of the project, a project under
  # the home directory, and a log that is not there at all keep the answers they had
  for shape in plain linkedin underhome missing; do
    d=$(newrepo); wv_init "$d"; wv_commit "$d" src/a.py || return 1
    day=$(wv_day "$d"); home=
    case $shape in
      plain) wv_log "$d" "$day" guard-ran stop stop ;;
      linkedin) mkdir -p "$d/cfg"; wv_log "$d/cfg" "$day" guard-ran stop stop; rm -rf "$d/.claude"; ln -s cfg/.claude "$d/.claude" ;;
      underhome) wv_log "$d" "$day" guard-ran stop stop; home=$(dirname "$d") ;;
      missing) : ;;
    esac
    HOME=${home:-$HOME} wv_run 10 "$d" --since 2000-01-01
    case $shape in
      missing) [ "$wv_rc" = 3 ] && case $wv_out in *MISSING*) true ;; *) false ;; esac || { echo "missing: exited $wv_rc and says: $(printf '%s\n' "$wv_out" | grep -m1 'guard log')"; bad=1; } ;;
      *) printf '%s\n' "$wv_out" | grep -qE '^stops: +2$' || { echo "$shape: no longer counts the 2 stops of its own log (rc $wv_rc): $(printf '%s\n' "$wv_out" | grep -m1 'guard log')"; bad=1; } ;;
    esac
  done
  [ "$bad" = 0 ] && echo "a pipe, a link, a directory, a .claude that leaves the project, the home directory and a directory above it are not read and are said not to be; a plain log, a link inside the project, a project under home and a missing log answer as before"
  return $bad
}

check 'a quiet week is not called held'                           a_quiet_week_is_not_called_held
check 'a fired week states what the log holds'                    a_fired_week_states_what_the_log_holds
check 'the week is read from the stand it is told to'             the_week_is_read_from_the_stand_it_is_told_to
check 'a window behind its upstream says so in one line'          the_window_behind_its_upstream_says_so_in_one_line
check 'a log that is no plain file is not read'                   a_log_that_is_no_plain_file_is_not_read
# A PATH AND A REF NAME WITH AN UMLAUT are printed as the bytes they are, whatever the locale says.
# The program that prints the log lines turned them into characters and back with the encoding of the
# locale, and on a Mac the first half is always UTF-8 while the second follows LC_ALL: under
# de_DE.ISO8859-1 the line "guard log: NOT READ at <path>" carried a single byte where the line
# above it, written by the shell, carried two [measured 2026-11-07 on this change, before the fix].
the_week_prints_a_path_and_a_ref_the_same_under_any_locale() {
  bad=0
  uml=$(printf 'pr\303\274fung'); rf=$(printf 'b\303\244r')
  top=$(mktemp -d); top=$(CDPATH= cd -- "$top" && pwd -P)
  # MK-R5, ITEM 5: the line that says the log is MISSING carries the path as well, and printed it through the locale.
  for shape in notread ref missing; do
    d=$top/$shape-$uml; mkdir -p "$d/.claude" "$d/src"; wv_init "$d"
    wv_commit "$d" src/a.py '2020-01-01T00:00:00' || return 1
    git -C "$d" branch "$rf"
    case $shape in
      notread) mkfifo "$d/.claude/manager-kit.log"; args='--since 2000-01-01'; want=$d ;;
      ref) wv_log "$d" "$(wv_day "$d")" guard-ran; args="--since 2030-01-01 --ref $rf"; want=$rf ;;
      missing) args='--since 2000-01-01'; want=$d/.claude/manager-kit.log ;;
    esac
    first=
    for loc in '' C POSIX en_US.UTF-8 de_DE.UTF-8 de_DE.ISO8859-1; do
      # shellcheck disable=SC2086
      if [ -n "$loc" ]; then LC_ALL=$loc wv_run 10 "$d" $args; else wv_run 10 "$d" $args; fi
      if [ -z "$first" ]; then
        first=$wv_out
        case $wv_out in *"$want"*) ;; *) echo "$shape: the output does not carry [$want] as the bytes it is"; bad=1 ;; esac
      fi
      [ "$wv_out" = "$first" ] || { echo "$shape: under LC_ALL=${loc:-unset} the output is not the one of the default locale"; bad=1; }
    done
  done
  [ "$bad" = 0 ] && echo 'a path and a ref name with an umlaut come out as the same bytes under six locales, in the line that says the log is not read, the one that says it is missing, and the one that names a stand'
  return $bad
}

check 'the week prints a path and a ref the same under any locale'  the_week_prints_a_path_and_a_ref_the_same_under_any_locale
# MK-R5, ITEM 6. THE CHEAP END IS HAIKU IN ANY SPELLING. The rule asked for the word haiku and nothing else, so a
# definition that wrote Haiku, HAIKU or claude-haiku-5-5 (a full model id is a legal value there) put the cheap model on the
# repair hand and passed in silence. In a CALL the runtime refuses those words before any hook runs: the model is a closed
# list of four words, and the schema failure is answered ahead of the first PreToolUse reference inside the one function that
# runs a tool [measured 2026-11-07 in the program text of 2.1.318, mmap, offsets 262523585, 271563805 and 271568290:
# VFi=["sonnet","opus","haiku","fable"]]. So the call is no gap and the definition is; both are asked here, because the
# guard is a function of what it is handed and a later schema may be wider.
a_cheap_model_is_the_cheap_model_in_any_spelling() {
  bad=0
  d=$(newrepo)
  for w in haiku Haiku HAIKU claude-haiku-5-5 claude-haiku-4-5-20251001 anthropic.claude-haiku-4-5-v1 haiku-5; do
    route_denies "$d" "$w" ${KITP}:xhigh >/dev/null || bad=1
    route_pass "$d" "$w" ${KITP}:medium 'haiku is open on every hand but the repair hand' || bad=1
  done
  # THE OTHER MODELS STAY OPEN on the repair hand, in the spellings that sit next to the cheap one.
  for w in sonnet opus fable Sonnet OPUS claude-sonnet-5-5 claude-opus-5 anthropic.claude-sonnet-4-5-v1; do
    route_pass "$d" "$w" ${KITP}:xhigh 'not the cheap end' || bad=1
  done
  # THE DEFINITION, with the call naming nothing: the kit as a fork would ship it.
  for w in Haiku HAIKU claude-haiku-5-5; do
    k=$(mktemp -d); cp agents/*.md "$k/"
    sed -i.bak "s/^model:.*/model: $w/" "$k/xhigh.md"; rm -f "$k"/*.bak
    out=$(mkagent "$d" Agent '' ${KITP}:xhigh | MK_ROUTE_AGENTS="$k" ./hooks/route-guard.sh)
    case $out in *'"deny"'*) ;; *) echo "a definition of the repair hand that names model: $w passed: $out" | cut -c1-200; bad=1 ;; esac
  done
  [ "$bad" = 0 ] && echo "7 spellings refused on the repair hand and open on another, 8 other models open on the repair hand, 3 definitions refused"
  return $bad
}

# MK-R5, ITEM 7. NO FIXTURE TYPES THE NAME OF THE KIT. A fork under another name has a manifest with another name, the
# guard reads the prefix of a hand from it, and a fixture that typed the old one was red there without the code being
# wrong [measured 2026-11-07 at a7dc5a9: 48 lines of this file typed it]. The lines are found by what they look like,
# a plugin hand written as <name>:<hand>, in every line that is not a comment, and the name is read out of the manifest.
no_fixture_types_the_name_of_the_kit() {
  bad=0
  name=$(python3 -I -c 'import json, sys; print(json.load(open(sys.argv[1], encoding="utf-8"))["name"])' "$ROOT/.claude-plugin/plugin.json") || return 1
  [ -n "$KITP" ] && [ "$name" = "$KITP" ] || { echo "KITP is [$KITP], the manifest says [$name]"; bad=1; }
  # the pattern is spelled in two pieces so that this line is not one of the lines it finds
  typed=$(grep -n "$name"':[a-z$]' "$ROOT/tests/run.sh" | grep -v '^[0-9]*:[[:space:]]*#' | cut -c1-110)
  [ -z "$typed" ] || { echo "a fixture types the name of the kit instead of \$KITP:"; printf '%s\n' "$typed" | head -8; bad=1; }
  # MK-R6: and the name as a string of its own, "<name>" or '<name>', which is how the entry of the marketplace manifest is
  # asked for. Five checks typed it that way and were red in a fork under another name, which no hand written as
  # <name>:<hand> would have shown.
  quoted=$(grep -n -e '"'"$name"'"' -e "'""$name""'" "$ROOT/tests/run.sh" | grep -v '^[0-9]*:[[:space:]]*#' | cut -c1-110)
  [ -z "$quoted" ] || { echo "a check types the name of the kit as a string instead of reading it from \$KITP:"; printf '%s\n' "$quoted" | head -8; bad=1; }
  # and the hands it names are real: each one the fixtures use is a file in agents/
  for h in xhigh medium low-readonly max; do
    [ -f "$ROOT/agents/$h.md" ] || { echo "the fixtures use the hand $h and agents/$h.md is not there"; bad=1; }
  done
  [ "$bad" = 0 ] && echo "the prefix is [$KITP], from the manifest, in every fixture"
  return $bad
}

# MK-R6. NO COMMAND SUBSTITUTION ASKS FOR THE PROJECT ROOT. $(mk_project_root ...) hands the name back through a
# command substitution, which removes a newline at the end of it, and a project called "tail" followed by a newline
# was then taken for its sibling called "tail" [MK-R5 item 1, eight call sites, each with a trick of its own]. The
# function stays for the callers that want it on stdout; the hooks and tools call mk_project_root_set and read $MK_ROOT.
# The files are the ones in hooks/ and tools/, listed from the tree, and the lines are found by what they look like: the
# name inside a $( ) or between backticks, in every line that is not a comment. The scan is asked on a fixture of its
# own too, because a scan that finds nothing in the tree is also what a scan that cannot see looks like.
project_root_scan() {
  grep -n -H -E '(\$\([^)]*|`[^`]*)mk_project_root' "$@" | grep -v -E '^[^:]+:[0-9]+:[[:space:]]*#'
}

no_command_substitution_asks_for_the_project_root() {
  bad=0
  files=$(ls "$ROOT"/hooks/*.sh "$ROOT"/tools/*.sh) || return 1
  n=$(printf '%s\n' "$files" | grep -c .)
  [ "$n" -ge 5 ] || { echo "found only $n files in hooks/ and tools/"; return 1; }
  # shellcheck disable=SC2086
  hits=$(project_root_scan $files | sed "s|^$ROOT/||" | cut -c1-120)
  [ -z "$hits" ] || { echo "a command substitution asks for the project root, which loses a newline at the end of its name:"; printf '%s\n' "$hits" | head -8; bad=1; }
  d=$(mktemp -d)
  cat > "$d/shapes.sh" <<'EOS'
ROOT=$(mk_project_root "$d")
ROOT=`mk_project_root "$d"`
x="$(cd "$d" && mk_project_root .)"
y=$( mk_project_root "$d" | head -1)
z=$(mk_project_root_set "$d")
# NOT $(mk_project_root ...): a comment is no call
mk_project_root_set "$d"; ROOT=$MK_ROOT
mk_project_root() { mk_project_root_set "${1-}"; printf '%s\n' "$MK_ROOT"; }
w=$(printf x) ; mk_project_root_set "$d"
EOS
  got=$(project_root_scan "$d/shapes.sh" | cut -d: -f2 | tr '\n' ' ')
  want='1 2 3 4 5 '
  [ "$got" = "$want" ] || { echo "the scan placed the fixture lines wrongly: got [$got], want [$want]"; bad=1; }
  rm -rf "${d:?}"
  [ "$bad" = 0 ] && echo "$n files in hooks/ and tools/, none asks for the project root inside a command substitution"
  return $bad
}

# MK-R5, ITEM 5. THE COMMAND SAYS WHAT IT KNOWS AND REFUSES WHAT IT DID NOT UNDERSTAND. Until now a typed
# option it has no name for (--rf, --sinc, --since=2026-11-01) was passed over and the verdict read from the window
# it HAD, a repeated --since took the last one without a word, the sentence for a missing log named two causes and
# left out a log that was taken away, and the sentence for days without a trace named the wiring as the cause
# [measured 2026-11-07 at a7dc5a9: tools/week-verdict.sh read the window of the first call and answered 0 for
# `--rf`, `--sinc` and a second `--since`].
the_week_says_what_it_knows_and_refuses_what_it_did_not_understand() {
  bad=0
  d=$(newrepo); wv_init "$d"; wv_commit "$d" src/a.py || return 1
  day=$(wv_day "$d")
  # the options this command has, read out of its own loop, so a fourth one is a case here without being typed
  opts=$(sed -n 's/^    \(--[a-z]*\)) .*/\1/p' "$ROOT/tools/week-verdict.sh" | sort -u)
  [ "$(printf '%s\n' "$opts" | wc -l | tr -d ' ')" -ge 3 ] || { echo "found only [$opts] as the options of the command"; return 1; }
  # RIGHT ONES OF THE SAME SHAPE: each option once, with a value, alone and all together, is still read.
  for args in "--since 2000-01-01" "--since 2000-01-01 --until 2999-12-31" "--since 2000-01-01 --ref HEAD" "--since 2000-01-01 --until 2999-12-31 --ref HEAD"; do
    # shellcheck disable=SC2086
    wv_run 10 "$d" $args
    [ "$wv_rc" != 2 ] || { echo "refused a call that names each option once: [$args]: $(printf '%s' "$wv_out" | head -2 | tr '\n' ' ')"; bad=1; }
  done
  # THE WINDOW COMES FROM THE OPTION GIVEN FIRST OR LAST ONLY IF THE COMMAND SAYS SO: a second one is refused.
  for o in $opts; do
    # every other bound is a valid one, so the refusal is the repeated option and not the order of the window
    case $o in --since) pre="" ; v1=2000-01-01; v2=2000-01-02 ;; --until) pre="--since 2000-01-01"; v1=2999-12-30; v2=2999-12-31 ;; *) pre="--since 2000-01-01"; v1=HEAD; v2=HEAD ;; esac
    # shellcheck disable=SC2086
    wv_run 10 "$d" $pre "$o" $v1 "$o" $v2
    [ "$wv_rc" = 2 ] || { echo "$o given twice exited $wv_rc, not 2: $(printf '%s' "$wv_out" | head -2 | tr '\n' ' ')"; bad=1; }
    case $wv_out in *VERDICT*|*'guard log'*) echo "$o given twice still printed a reading"; bad=1 ;; esac
    case $wv_out in *"$o"*'twice'*|*"$o"*'times'*) ;; *) echo "$o given twice: the refusal does not say it was given more than once: $(printf '%s' "$wv_out" | head -1)"; bad=1 ;; esac
  done
  # AN OPTION IT HAS NO NAME FOR, in the shapes a hand mistypes: a letter short, a letter more, the value joined with =,
  # and one of its own names with a letter changed.
  typed=""
  for o in $opts; do typed="$typed ${o%?} ${o}s ${o}=2000-01-01 --x${o#--}"; done
  for o in $typed --rf; do
    wv_run 10 "$d" "$o" 2000-01-01
    [ "$wv_rc" = 2 ] || { echo "the unknown option $o exited $wv_rc, not 2: $(printf '%s' "$wv_out" | head -2 | tr '\n' ' ')"; bad=1; continue; }
    case $wv_out in *"$o"*) ;; *) echo "the refusal of $o does not name it: $(printf '%s' "$wv_out" | head -1)"; bad=1 ;; esac
    case $wv_out in *'Nothing was read'*) ;; *) echo "the refusal of $o does not say that nothing was read"; bad=1 ;; esac
    case $wv_out in *VERDICT*) echo "$o: a verdict was printed after the refusal"; bad=1 ;; esac
  done
  # An option in front, with the project left to the working directory, is still an option and still understood.
  wv_out=$(cd "${d:?}" && bash "$ROOT/tools/week-verdict.sh" --since 2000-01-01 </dev/null 2>&1); wv_rc=$?
  [ "$wv_rc" != 2 ] || { echo "an option first, with the project left out, was refused: $(printf '%s' "$wv_out" | head -2 | tr '\n' ' ')"; bad=1; }
  # THE TWO SENTENCES. A log that is not there may have been removed, and days with commits and no trace may be
  # commits made outside any session: the command cannot tell them from a wiring that does not fire, and says so.
  e=$(newrepo); wv_init "$e"; wv_commit "$e" src/a.py || return 1
  wv_run 10 "$e" --since 2000-01-01
  case $wv_out in *MISSING*) ;; *) echo "no log did not read MISSING: $(printf '%s' "$wv_out" | head -2)"; bad=1 ;; esac
  case $wv_out in *'Either it was never installed'*) echo "a missing log is still said to be one of two causes"; bad=1 ;; esac
  case $wv_out in *removed*) ;; *) echo "a missing log is not said to be possibly removed"; bad=1 ;; esac
  wv_log "$e" 2000-01-02 guard-ran stop
  wv_run 10 "$e" --since 2000-01-01
  case $wv_out in *'important failure'*) ;; *) echo "days without a trace were not found: $(printf '%s' "$wv_out" | head -3)"; bad=1 ;; esac
  case $wv_out in *'Fix the wiring'*) echo "days without a trace are still said to be a wiring"; bad=1 ;; esac
  case $wv_out in *'cannot tell'*'outside'*|*'cannot tell'*'session'*) ;; *) echo "days without a trace are not said to have more than one cause"; bad=1 ;; esac
  [ "$bad" = 0 ] && echo "$(printf '%s\n' "$opts" | wc -l | tr -d ' ') options from the loop, each refused when given twice, $(printf '%s\n' $typed --rf | wc -l | tr -d ' ') mistyped ones refused, each once still read"
  return $bad
}

check 'a cheap model is the cheap model in any spelling' a_cheap_model_is_the_cheap_model_in_any_spelling
check 'no fixture types the name of the kit' no_fixture_types_the_name_of_the_kit
check 'no command substitution asks for the project root' no_command_substitution_asks_for_the_project_root
check 'the week says what it knows and refuses what it did not understand' the_week_says_what_it_knows_and_refuses_what_it_did_not_understand
# ------------------------------------------------------------------ MK-R2: the project's own files
# The kit's files lie in the project, and the project is somebody else's. Each assertion below is one
# way a file or a path of the project held the hook, led its record out of the project, or made a
# field of its line say something else. Every one was seen RED against 95792cd before the code.

# big_file <path> <MB> <head> [oneline] -> a plain file of that many megabytes behind <head>.
big_file() {
  python3 -I - "$@" <<'PY'
import sys
path, mb, head = sys.argv[1], int(sys.argv[2]), sys.argv[3].encode()
chunk = b"a" * (1 << 20) if len(sys.argv) > 4 else (b"a" * 1023 + b"\n") * 1024
with open(path, "wb") as f:
    f.write(head)
    for _ in range(mb):
        f.write(chunk)
PY
}
# log_lines <path> <n> -> n lines of the shape the guard writes.
log_lines() {
  python3 -I - "$1" "$2" <<'PY'
import sys
line = '{"ts": "2026-11-06T00:00:00Z", "event": "stop", "tool": "Write", "subject": "x", "reason": "r"}\n'
with open(sys.argv[1], "w") as f:
    for _ in range(int(sys.argv[2])):
        f.write(line)
PY
}
# r2_cap -> the number of bytes of the log the refusal reads, out of the code that holds it.
r2_cap() { HOME=/nonexistent bash -c '. hooks/_sessions.sh; printf "%s" "${MK_LOG_CAP:-}"'; }

a_big_file_in_the_project_holds_no_hook() {
  hooks=$(still_wired_hooks) || return 1
  own_setup
  bad=0; nrun=0; mb=150; held=3
  # 1. A ROLE FILE AND A SEEN FILE OF ANY SIZE, as many lines and as one line. The hook that reads them
  #    on every call is held for as long as the file is long, and a repository can ship one.
  for shape in role roleline seen gitfile backptr; do
    for k in $hooks; do
      p=$(newrepo)
      case $shape in
        gitfile)  big_file "$p/.git" $mb 'gitdir: ' one ;;
        backptr)  mkdir -p "$p/fake/.git/worktrees/x"; printf 'gitdir: %s/fake/.git/worktrees/x\n' "$p" > "$p/.git"
                  big_file "$p/fake/.git/worktrees/x/gitdir" $mb '' one ;;
        role)     big_file "$p/.claude/manager-kit.role" $mb '1 x
' ;;
        roleline) big_file "$p/.claude/manager-kit.role" $mb '1 x ' one ;;
        seen)     big_file "$p/.claude/manager-kit.seen" $mb '2020-01-01
' ;;
      esac
      payload=$(still_payload "$k" "$p") || { echo "no driver for the wired hook $k"; bad=1; continue; }
      case $k in role-guard.sh) payload=$(mkinput "$p" "" Bash '{"command":"git status"}') ;; esac
      out=$( cd "$p" && printf '%s' "$payload" |
        env HOME="$own_home" MANAGER_KIT_SOCKET_DIR="$still_socks" python3 -I "$OWN_BOUND" $held "$ROOT/hooks/$k" 2>/dev/null )
      rc=$?; nrun=$((nrun + 1))
      [ "$rc" != 124 ] || { echo "$k: a $mb MB $shape held the hook past $held s"; bad=1; }
      # The file is removed at once: shapes times hooks of them, 150 MB each, were all kept until the end of the run, and
      # a machine with a few hundred MB free [127 MB, measured 2026-11-07] could not run this check at all.
      rm -rf "${p:?}"
    done
  done
  # 2. THE VERDICT DOES NOT GO WITH THE SIZE. A role file that is too big to be one is no role file, so the
  #    refusal stands; a role file of the right size naming somebody alive still stands the guard down.
  p=$(newrepo); big_file "$p/.claude/manager-kit.role" 1 "$$ x
"
  own_run role-guard.sh "$p" "$(own_write "$p")"
  [ "$(own_answer)" = deny ] || { echo "a role file of 1 MB named a holder: the write was $(own_answer)"; bad=1; }
  case $own_out in *"manager-kit.role is longer than"*) ;; *) echo "the refusal does not say the role file is too long to be one"; bad=1 ;; esac
  p=$(newrepo); printf '%s x\n' "$$" > "$p/.claude/manager-kit.role"
  own_run role-guard.sh "$p" "$(own_write "$p")"
  [ "$(own_answer)" = silent ] || { echo "a role file of the right size naming somebody alive no longer stands the guard down: $(own_answer)"; bad=1; }
  # 3. THE LOG IS COUNTED UP TO A CAP AND NOT BEYOND IT, and a refusal that did not count says so. A count
  #    it printed from part of a log would be a number nobody can tell from the whole.
  cap=$(r2_cap)
  case $cap in ''|*[!0-9]*) echo "the code holds no cap for the log it reads: [$cap]"; bad=1; cap=16777216 ;; esac
  p=$(newrepo); line_len=$(printf '%s' '{"ts": "2026-11-06T00:00:00Z", "event": "stop", "tool": "Write", "subject": "x", "reason": "r"}' | wc -c)
  n=$(( (cap - 4000000) / (line_len + 1) )); log_lines "$p/.claude/manager-kit.log" "$n"
  own_run role-guard.sh "$p" "$(own_write "$p")"
  case $own_out in *"Stops $((n + 1)),"*) ;; *) echo "a log under the cap was not counted to the line: $(printf '%s' "$own_out" | cut -c1-160)"; bad=1 ;; esac
  p=$(newrepo); n=$(( (cap + 1000000) / (line_len + 1) )); log_lines "$p/.claude/manager-kit.log" "$n"
  own_run role-guard.sh "$p" "$(own_write "$p")"
  [ "$(own_answer)" = deny ] || { echo "a log over the cap took the refusal down: $(own_answer)"; bad=1; }
  case $own_out in *"not counted"*) ;; *) echo "a log over the cap was counted in silence: $(printf '%s' "$own_out" | cut -c1-200)"; bad=1 ;; esac
  case $own_out in *"Stops "[0-9]*) echo "a log over the cap printed a count it cannot stand behind"; bad=1 ;; esac
  [ "$bad" = 0 ] && echo "$nrun hook runs with a ${mb} MB file held none past $held s, a role file too big to be one is none, a log over $cap bytes is not counted and says so"
  return $bad
}

# route_log_lines <path> <n> -> n lines of a refused handout, the shape route-guard.sh writes.
route_log_lines() {
  python3 -I - "$1" "$2" <<'PY'
import sys
line = '{"ts": "2026-11-07T00:00:00Z", "event": "route-stop", "tool": "Agent", "subject": "' + __import__("os").environ["KITP"] + ':xhigh", "reason": "r"}\n'
with open(sys.argv[1], "w") as f:
    for _ in range(int(sys.argv[2])):
        f.write(line)
PY
}
# r2_settings_cap -> the number of bytes of a settings file the SessionStart hooks read, out of the code that holds it.
r2_settings_cap() { HOME=/nonexistent bash -c '. hooks/_sessions.sh; printf "%s" "${MK_SETTINGS_CAP:-}"'; }

# MK-R2, THE NEIGHBOURS OF THE BIG FILE. Measured 2026-11-07 at 0464e26 in a fresh project (m-route.py, 200 MB, load 3):
# the refusal of route-guard.sh read the whole log (4.3 s), a project hand definition in lines of two bytes held the same
# hook (7.0 s at 60 MB, 2.6 s at 20 MB), and a settings.json in such lines held both SessionStart hooks (5.2 s). The same
# files in lines of 1 KB or as one line cost 0.2 to 0.6 s, so the shape is part of the finding. THIS CHECK WRITES NO FILE
# OF THAT SIZE and asserts the bound where it can be seen: a word put past what the hook reads is not read. The disk of
# the machine this was built on had 127 MB free, and a check that needs gigabytes is one that stops being run.
a_big_log_definition_or_settings_file_holds_no_hook() {
  own_setup
  bad=0
  # 1. THE ROUTE LOG IS COUNTED UP TO THE CAP OF THE GUARD LOG AND NOT BEYOND IT, and a refusal that did not count says so.
  cap=$(r2_cap)
  case $cap in ''|*[!0-9]*) echo "the code holds no cap for the log it reads: [$cap]"; bad=1; cap=16777216 ;; esac
  line_len=$(printf '%s' '{"ts": "2026-11-07T00:00:00Z", "event": "route-stop", "tool": "Agent", "subject": "'"$KITP"':xhigh", "reason": "r"}' | wc -c)
  p=$(newrepo); n=2000; route_log_lines "$p/.claude/manager-kit.log" "$n"
  own_run route-guard.sh "$p" "$(mkagent "$p" Agent haiku ${KITP}:xhigh)"
  [ "$(own_answer)" = deny ] || { echo "a route log under the cap took the refusal down: $(own_answer)"; bad=1; }
  case $own_out in *"Handouts $((n + 1)), refused $((n + 1))."*) ;; *) echo "a route log under the cap was not counted to the line: $(printf '%s' "$own_out" | cut -c1-200)"; bad=1 ;; esac
  p=$(newrepo); n=$(( (cap + 1000000) / (line_len + 1) )); route_log_lines "$p/.claude/manager-kit.log" "$n"
  own_run route-guard.sh "$p" "$(mkagent "$p" Agent haiku ${KITP}:xhigh)"
  [ "$(own_answer)" = deny ] || { echo "a route log over the cap took the refusal down: $(own_answer)"; bad=1; }
  case $own_out in *"not counted"*) ;; *) echo "a route log over the cap was counted in silence: $(printf '%s' "$own_out" | cut -c1-200)"; bad=1 ;; esac
  case $own_out in *"Handouts "[0-9]*) echo "a route log over the cap printed a count it cannot stand behind"; bad=1 ;; esac
  # 2. A DEFINITION OF A HAND IS READ BY ITS HEAD. Its frontmatter is at its head, so for every definition that has one the
  #    read is the same: a long body behind a closed frontmatter still gives its effort and model, an effort key at the head
  #    of a frontmatter that never closes is found, and a key put 100 KB down that frontmatter is not read.
  for shape in body head far; do
    p=$(newrepo); mkdir -p "$p/.claude/agents"
    case $shape in
      body) { printf -- '---\nname: x\neffort: high\nmodel: sonnet\n---\n'; python3 -I -c 'print("body line\n" * 20000)'; } ;;
      head) { printf -- '---\nname: x\neffort: high\n'; python3 -I -c 'print("filler\n" * 20000)'; } ;;
      far)  { printf -- '---\nname: x\n'; python3 -I -c 'print("filler\n" * 20000)'; printf 'effort: high\n'; } ;;
    esac > "$p/.claude/agents/x.md"
    own_run route-guard.sh "$p" "$(mkagent "$p" Agent "" x)"
    line=$(tail -1 "$p/.claude/manager-kit.log" 2>/dev/null)
    case $shape in
      body) case $line in *'effort=high'*'model=sonnet'*|*'model=sonnet'*'effort=high'*) ;; *) echo "a definition with a long body no longer gives its effort and model: $(printf '%s' "$line" | cut -c1-200)"; bad=1 ;; esac ;;
      head) case $line in *'effort=high'*) ;; *) echo "an effort at the head of a frontmatter that never closes is not found: $(printf '%s' "$line" | cut -c1-200)"; bad=1 ;; esac ;;
      far)  case $line in *'effort=high'*) echo "a key 100 KB down a frontmatter was read, so the whole definition is read: $(printf '%s' "$line" | cut -c1-200)"; bad=1 ;; esac ;;
    esac
  done
  # 3. A SETTINGS FILE, as the SessionStart hooks read it. Past what they read they say they did not check and do not say the
  #    setting is missing; under it the setting is found wherever it stands, and a file that does not name it still reads so.
  scap=$(r2_settings_cap)
  case $scap in ''|*[!0-9]*) echo "the code holds no cap for the settings file it reads: [$scap]"; bad=1; scap=1048576 ;; esac
  for shape in past within small; do
    p=$(newrepo)
    case $shape in
      past)   { printf '{"a": "\n'; python3 -I -c 'import sys; sys.stdout.write("x" * int(sys.argv[1]) + "\n")' $((scap + 4096)); printf 'DISABLE_AUTO_COMPACT": 1}\n'; } ;;
      within) { printf '{"a": "\n'; python3 -I -c 'import sys; sys.stdout.write("x" * int(sys.argv[1]) + "\n")' $((scap - 4096)); printf 'DISABLE_AUTO_COMPACT": 1}\n'; } ;;
      small)  printf '{"env": {"OTHER": "1"}}\n' ;;
    esac > "$p/.claude/settings.json"
    for k in manager-prime.sh manager-reinject.sh; do
      own_run "$k" "$p" "$(still_payload "$k" "$p")"
      case $shape in
        past)   case $own_out in *"was not checked"*) ;; *) echo "$k: a settings.json past what the hook reads was passed in silence: $(printf '%s' "$own_out" | cut -c1-120)"; bad=1 ;; esac
                case $own_out in *"DISABLE_AUTO_COMPACT is not set"*) echo "$k: a settings.json past what the hook reads was reported as not setting the variable"; bad=1 ;; esac ;;
        within) case $own_out in *"DISABLE_AUTO_COMPACT is not set"*|*"was not checked"*) echo "$k: a settings.json that names the variable inside what the hook reads is not found: $(printf '%s' "$own_out" | cut -c1-120)"; bad=1 ;; esac ;;
        small)  case $own_out in *"DISABLE_AUTO_COMPACT is not set"*) ;; *) echo "$k: a small settings.json that does not name the variable is no longer reported: $(printf '%s' "$own_out" | cut -c1-120)"; bad=1 ;; esac ;;
      esac
    done
  done
  [ "$bad" = 0 ] && echo "a route log over $cap bytes is not counted and says so, a definition is read by its head, a settings file past $scap bytes is not searched and says so"
  return $bad
}

# r2_repo <dir> -> a real repository with one commit.
r2_repo() { git init -q "$1" && git -C "$1" -c user.name=t -c user.email=t@t commit -q --allow-empty -m x; }
# r2_logged <project> -> true when that project keeps a stop line of its own.
r2_logged() { grep -qs '"event": "stop"' "$1/.claude/manager-kit.log"; }

a_git_file_names_its_own_repository_or_nothing() {
  own_setup
  bad=0
  top=$(mktemp -d); top=$(CDPATH= cd -- "$top" && pwd -P)
  r2_repo "$top/foreign" || return 1
  git -C "$top/foreign" worktree add -q "$top/fwt" || return 1
  # 1. A .git FILE THAT POINTS INTO SOMEBODY ELSE'S REPOSITORY, absolute and relative, and the neighbours
  #    that are not a worktree of it: nothing out there may change, and the record stays in the project.
  before=$(own_digest "$top/foreign")
  for shape in absolute relative; do
    h=$top/hostile-$shape; mkdir -p "$h/src" "$h/.claude"
    case $shape in
      absolute) printf 'gitdir: %s\n' "$top/foreign/.git/worktrees/fwt" > "$h/.git" ;;
      relative) printf 'gitdir: %s\n' "../foreign/.git/worktrees/fwt" > "$h/.git" ;;
    esac
    own_run role-guard.sh "$h" "$(own_write "$h")"
    [ "$(own_digest "$top/foreign")" = "$before" ] || { echo "$shape: a .git file led the record into another repository: $(own_digest "$top/foreign" | diff - <(printf '%s\n' "$before") | head -3 | tr '\n' ' ')"; bad=1; before=$(own_digest "$top/foreign"); }
    r2_logged "$h" || { echo "$shape: the project lost its own record"; bad=1; }
    [ "$(own_answer)" = deny ] || { echo "$shape: the write was $(own_answer)"; bad=1; }
  done
  # 2. THE RIGHT ONE, a real worktree, still goes to its main repository, from its top and from below.
  mkdir -p "$top/fwt/sub/deep"
  for at in "$top/fwt" "$top/fwt/sub/deep"; do
    rm -f "$top/foreign/.claude/manager-kit.log"
    own_run role-guard.sh "$at" "$(own_write "$at")"
    r2_logged "$top/foreign" || { echo "a real worktree ($at) lost its record at the main repository"; bad=1; }
    [ ! -e "$top/fwt/.claude" ] || { echo "a real worktree ($at) grew a record of its own"; bad=1; }
  done
  # ... also when git writes the way back as a relative path, where this git can.
  if git -C "$top/foreign" worktree add -q --relative-paths "$top/rwt" 2>/dev/null; then
    rm -f "$top/foreign/.claude/manager-kit.log"
    own_run role-guard.sh "$top/rwt" "$(own_write "$top/rwt")"
    r2_logged "$top/foreign" || { echo "a worktree with relative paths lost its record at the main repository"; bad=1; }
  fi
  # ... and a worktree reached through a link to it, which is the same directory under another spelling.
  ln -s "$top/fwt" "$top/fwt-link"; rm -f "$top/foreign/.claude/manager-kit.log"
  own_run role-guard.sh "$top/fwt-link" "$(own_write "$top/fwt-link")"
  r2_logged "$top/foreign" || { echo "a worktree reached through a link lost its record at the main repository"; bad=1; }
  # 3. THE NEIGHBOURS: a submodule is a project of its own, a plain repository and a project with no git too.
  sm=$top/foreign/mod; mkdir -p "$sm/src" "$top/foreign/.git/modules/mod"; printf 'gitdir: ../.git/modules/mod\n' > "$sm/.git"
  own_run role-guard.sh "$sm" "$(own_write "$sm")"
  r2_logged "$sm" || { echo "a submodule lost its record of its own"; bad=1; }
  ng=$(newrepo); own_run role-guard.sh "$ng" "$(own_write "$ng")"
  r2_logged "$ng" || { echo "a project with no git lost its record"; bad=1; }
  # 4. A .git THAT GIT ITSELF DOES NOT TAKE FOR A REPOSITORY, an empty directory, starts no project: the
  #    answer is the one git gives, the repository around it.
  mkdir -p "$top/foreign/sub/src" "$top/foreign/sub/.git"
  want=$(cd "$top/foreign/sub" && git rev-parse --show-toplevel)
  rm -f "$top/foreign/.claude/manager-kit.log"
  own_run role-guard.sh "$top/foreign/sub" "$(own_write "$top/foreign/sub")"
  [ "$want" = "$top/foreign" ] || { echo "git itself no longer answers the repository around an empty .git: $want"; bad=1; }
  r2_logged "$top/foreign" || { echo "an empty .git directory started a project of its own at sub/"; bad=1; }
  [ ! -e "$top/foreign/sub/.claude" ] || { echo "an empty .git directory got a record of its own"; bad=1; }
  r2_repo "$top/foreign/nested" && mkdir -p "$top/foreign/nested/src"
  own_run role-guard.sh "$top/foreign/nested" "$(own_write "$top/foreign/nested")"
  r2_logged "$top/foreign/nested" || { echo "a real repository inside lost its record of its own"; bad=1; }
  [ "$bad" = 0 ] && echo 'a .git file keeps the record in the project unless the repository it names names it back, a real worktree and a submodule and a nested repository keep theirs, an empty .git is no project'
  return $bad
}

a_session_inside_the_home_claude_or_above_a_linked_home_keeps_no_record() {
  own_setup
  bad=0
  # 1. INSIDE THE HOME .claude: bookkeeping inside bookkeeping, and the person's own configuration above it.
  h=$(mktemp -d); h=$(CDPATH= cd -- "$h" && pwd -P); mkdir -p "$h/.claude/plugins/x" "$h/proj/.claude/agents" "$h/proj/src"
  before=$(own_digest "$h/.claude")
  for at in "$h/.claude" "$h/.claude/plugins/x"; do
    own_run role-guard.sh "$at" "$(own_write "$at")" "$h"
    [ "$(own_digest "$h/.claude")" = "$before" ] || { echo "a session in ${at#$h/} wrote there: $(find "$h/.claude" -name 'manager-kit*' | sed "s|$h/||" | tr '\n' ' ')"; bad=1; before=$(own_digest "$h/.claude"); }
    [ "$(own_answer)" = deny ] || { echo "a session in ${at#$h/} was $(own_answer)"; bad=1; }
  done
  # ... and the neighbour: a session in a project's own .claude/agents belongs to that project.
  own_run role-guard.sh "$h/proj/.claude/agents" "$(own_write "$h/proj")" "$h"
  r2_logged "$h/proj" || { echo "a session in the .claude/agents of a project lost the project's record"; bad=1; }
  # 2. A DIRECTORY ABOVE A HOME THAT RUNS THROUGH A LINK, physically above it and no string-ancestor of it.
  r=$(mktemp -d); r=$(CDPATH= cd -- "$r" && pwd -P)
  mkdir -p "$r/b/real/me/work/src" "$r/b/other/src" "$r/a" "$r/b/.claude"; ln -s "$r/b/real" "$r/a/link"
  for at in "$r/b" "$r/b/real"; do
    mkdir -p "$at/.claude"
    own_run role-guard.sh "$at" "$(own_write "$at")" "$r/a/link/me"
    [ -z "$(ls -A "$at/.claude")" ] || { echo "a directory above a linked home (${at#$r/}) was written: $(ls -A "$at/.claude" | tr '\n' ' ')"; bad=1; }
    [ "$(own_answer)" = deny ] || { echo "a directory above a linked home (${at#$r/}) was $(own_answer)"; bad=1; }
  done
  # ... and the neighbours: the project below the home, and the sibling that is not above it, keep theirs.
  for at in "$r/b/real/me/work" "$r/b/other"; do
    own_run role-guard.sh "$at" "$(own_write "$at")" "$r/a/link/me"
    r2_logged "$at" || { echo "${at#$r/} lost its record"; bad=1; }
  done
  [ "$bad" = 0 ] && echo 'a session inside the home .claude and one above a home behind a link write nothing, the project in .claude/agents and the ones below and beside the home keep their record'
  return $bad
}

a_hardlink_under_claude_is_not_written_through() {
  own_setup
  bad=0
  for n in manager-kit.seen manager-kit.log manager-kit.role; do
    p=$(newrepo); o=$(mktemp -d); printf 'PRECIOUS %s\n' "$n" > "$o/target"; ln "$o/target" "$p/.claude/$n"
    before=$(own_digest "$o")
    if [ "$n" = manager-kit.role ]; then
      own_claim "$p" "$own_home" || return 1
      [ "$STUB_RC" = 2 ] || { echo "$n: the take-over through a hard link exited $STUB_RC, not refused"; bad=1; }
    else
      own_run role-guard.sh "$p" "$(own_write "$p")"
      [ "$(own_answer)" = deny ] || { echo "$n: a hard link took the refusal down: $(own_answer)"; bad=1; }
      case $own_out in *".claude/$n"*"hard link"*) ;; *) echo "$n: the refusal does not say the file is a hard link"; bad=1 ;; esac
    fi
    [ "$(own_digest "$o")" = "$before" ] || { echo "$n: the file a hard link leads to was changed"; bad=1; }
  done
  # THE NEIGHBOUR: a file with one name is written as ever.
  p=$(newrepo); own_run role-guard.sh "$p" "$(own_write "$p")"
  [ "$(cat "$p/.claude/manager-kit.seen" 2>/dev/null)" = "$(date -u +%Y-%m-%d)" ] || { echo 'a plain seen file is no longer written'; bad=1; }
  r2_logged "$p" || { echo 'a plain log is no longer written'; bad=1; }
  [ "$bad" = 0 ] && echo 'a seen file, a log and a role file with a second name are left alone, the refusal says why, and a file with one name is written'
  return $bad
}

# r2_kit_names -> every name the kit writes under .claude, out of the code that writes it.
r2_kit_names() {
  python3 -I - hooks/*.sh tools/*.sh <<'PY'
import re, sys
names = set()
for path in sys.argv[1:]:
    for line in open(path, encoding="utf-8"):
        if line.lstrip().startswith("#"):
            continue
        names.update(re.findall(r"mk_kit_(?:write|spend)\s+\"[^\"]*\"\s+([A-Za-z][A-Za-z0-9._-]*)", line))
        names.update(re.findall(r"MK_LOG_NAME\s*=\s*\"([^\"]+)\"", line))
        names.update(re.findall(r"MK_NOTICE_NAME\s*=\s*\"([^\"]+)\"", line))
print("\n".join(sorted(names)))
PY
}

the_files_of_the_kit_are_all_in_the_exclusion() {
  names=$(r2_kit_names) || return 1
  for want in manager-kit.log manager-kit.seen manager-kit.role manager-exception; do
    case " $(echo $names) " in *" $want "*) ;; *) echo "the names derived from the code lack $want: $(echo $names)"; return 1 ;; esac
  done
  own_setup
  bad=0
  for first in guard claim; do
    p=$(mktemp -d); p=$(CDPATH= cd -- "$p" && pwd -P); git init -q "$p"; mkdir -p "$p/src"
    if [ "$first" = guard ]; then own_run role-guard.sh "$p" "$(own_write "$p")"; else own_claim "$p" "$own_home" || return 1; fi
    printf 'a reason\n' > "$p/.claude/manager-exception"
    for n in $names; do
      git -C "$p" check-ignore -q ".claude/$n" || { echo "$first first: .claude/$n is not excluded"; bad=1; }
    done
    printf 'mine\n' > "$p/.claude/notes.md"; printf '{}\n' > "$p/.claude/settings.json"; printf 'x\n' > "$p/.claude/manager-plan.md"
    git -C "$p" add -A
    staged=$(git -C "$p" diff --cached --name-only | tr '\n' ' ')
    case " $staged" in *manager-kit*|*manager-exception*) echo "$first first: git add -A staged $staged"; bad=1 ;; esac
    for keep in notes.md settings.json manager-plan.md; do
      case " $staged" in *".claude/$keep"*) ;; *) echo "$first first: the exclusion swallowed .claude/$keep"; bad=1 ;; esac
    done
  done
  [ "$bad" = 0 ] && echo "$(echo $names): excluded, however the first of them came to be, and a neighbour in .claude is not"
  return $bad
}

a_field_of_the_log_line_cannot_move_into_another() {
  own_setup
  bad=0
  us=$(printf '\037')
  for shape in tool subject path; do
    p=$(newrepo)
    case $shape in
      tool)    payload=$(python3 -I -c 'import json,sys; print(json.dumps({"cwd": sys.argv[1], "session_id": "S1", "tool_name": "Write\x1fganz/anders.py\x1fgrund", "tool_input": {"file_path": "src/a.py"}}))' "$p")
               want_tool="Write${us}ganz/anders.py${us}grund"; want_subject=src/a.py ;;
      subject) payload=$(python3 -I -c 'import json,sys; print(json.dumps({"cwd": sys.argv[1], "session_id": "S1", "tool_name": "Bash", "tool_input": {"command": "echo a\x1fb > src/a.py"}}))' "$p")
               want_tool=Bash; want_subject="echo a${us}b > src/a.py" ;;
      path)    payload=$(python3 -I -c 'import json,sys; print(json.dumps({"cwd": sys.argv[1], "session_id": "S1", "tool_name": "Write", "tool_input": {"file_path": "src/a\x1fb.py"}}))' "$p")
               want_tool=Write; want_subject="src/a${us}b.py" ;;
    esac
    own_run role-guard.sh "$p" "$payload"
    got=$(python3 -I - "$p/.claude/manager-kit.log" <<'PY'
import json, sys
rows = [json.loads(l) for l in open(sys.argv[1]) if l.strip()]
stops = [r for r in rows if r.get("event") == "stop"]
r = stops[-1] if stops else {}
print(json.dumps([r.get("tool"), r.get("subject")]))
PY
)
    want=$(python3 -I -c 'import json,sys; print(json.dumps([sys.argv[1], sys.argv[2]]))' "$want_tool" "$want_subject")
    [ "$got" = "$want" ] || { echo "$shape: a separator in a field moved the others: the line says $got, the call said $want"; bad=1; }
  done
  # THE PLACES THAT SEPARATE FIELDS WITH THAT CHARACTER, derived: the transport of a log line carries
  # none, and what is left is named. _classify.sh joins the words of one explanation line with it and
  # splits them again before they are printed, so a word with the character in it prints as a blank.
  # A range such as \000-\037 or [\x00-\x1f] strips or rejects control characters and separates nothing.
  left=$(python3 -I - hooks/*.sh tools/*.sh <<'PY2'
import re, sys
for path in sys.argv[1:]:
    if re.search(r"(?<![-\\])\\+(?:037|x1[fF])", open(path, encoding="utf-8").read()):
        print(path)
PY2
)
  left="$(echo $left) "
  [ "$left" = "hooks/_classify.sh " ] || { echo "files that spell the unit separator: $left, expected hooks/_classify.sh alone"; bad=1; }
  [ "$bad" = 0 ] && echo 'a unit separator in the tool, the command or the path stays in its own field of the line'
  return $bad
}

# ------------------------------------------------ MK-R4: the temp of a run, and the full mutation run
# The suite and the mutation run left their temp lying: 1306 of the 1388 paths one suite made were never
# removed and an interrupted run removed none of them [measured, see the root block above]. The assertions on
# the suite and the runner follow. Those on the temp, the named check, the stop and the long command were seen RED
# against 0b82b86 before a line of the repair stood; the others test what 0b82b86 could not do at all. The one on
# how the probe was started was seen RED against the probe as first written, which hung when a run was started with &.
# Every list in them is derived.

# tmp_probe <end|taken-off> -> prints what a suite left behind, and fails when it left anything.
# THE SUBJECT IS A REAL CHECK THAT MAKES TEMP, run by a real child of this file with MK_ONLY_CHECK, so
# what is measured is the root, the function and the traps as they stand and not a model of them. A
# mktemp on the PATH of the child records every path it hands out, WHEREVER it puts it: the macOS mktemp
# ignores TMPDIR, so a probe that only looked into the TMPDIR it gave the child would see an empty
# directory both before the repair and after it. The same probe lists that TMPDIR as well, for what
# Python makes. "taken-off" holds the child inside its first mktemp and sends TERM to its process group,
# which is what an interrupted terminal run and a runner that gives up on a suite both do. The hold starts
# at the SECOND call: the first is the root itself, made before the traps stand.
tmp_probe() {
  python3 -I - "$ROOT" "$1" <<'PY'
import os, shutil, signal, subprocess, sys, tempfile, time
root, mode = sys.argv[1], sys.argv[2]
SUBJECT = "a symlink is read by where it lands"
# "end" is one run to its end; "taken-off" is three, each ended by a different signal, each with the exit status
# a shell reports for it, which is what a caller reads to learn that the run was taken off.
RUNS = [(None, 0)] if mode == "end" else [(signal.SIGTERM, 143), (signal.SIGINT, 130), (signal.SIGHUP, 129)]
work = tempfile.mkdtemp(prefix="tmpprobe.")
try:
    bindir = os.path.join(work, "bin")
    os.mkdir(bindir)
    fake = os.path.join(bindir, "mktemp")
    with open(fake, "w") as fh:
        fh.write('#!/bin/sh\nr=$(/usr/bin/mktemp "$@") || exit $?\nprintf \'%s\\n\' "$r" >> "$MK_PROBE_LOG"\n'
                 '[ -z "${MK_PROBE_HOLD-}" ] || [ "$(wc -l < "$MK_PROBE_LOG")" -lt 2 ] || sleep "$MK_PROBE_HOLD"\nprintf \'%s\\n\' "$r"\n')
    os.chmod(fake, 0o755)
    drop = ("MK_RUN_ROOT", "MK_RUN", "MK_EXTRA", "MK_ONLY_CHECK", "MK_STOP_AT_RED")
    base = {k: v for k, v in os.environ.items() if k not in drop and not k.startswith("BASH_FUNC_")}
    bad = []
    made_all = 0
    for n, (sig, want_rc) in enumerate(RUNS):
        tmp = os.path.join(work, "tmp%d" % n)
        log = os.path.join(work, "made%d.log" % n)
        os.mkdir(tmp)
        env = dict(base, TMPDIR=tmp + "/", MK_PROBE_LOG=log, MK_ONLY_CHECK=SUBJECT, PATH=bindir + ":" + base["PATH"])
        if sig:
            env["MK_PROBE_HOLD"] = "60"
        # A signal that THIS process was started with ignored (INT after &, HUP under nohup) would stay ignored in the
        # child, and a shell cannot trap it again: the child would sit through its hold and the check would measure
        # the caller. The child gets all three at their default, whatever this process was given.
        p = subprocess.Popen(["bash", os.path.join(root, "tests", "run.sh")], cwd=root, env=env,
                             stdin=subprocess.DEVNULL, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                             text=True, errors="replace", start_new_session=True,
                             preexec_fn=lambda: [signal.signal(s, signal.SIG_DFL) for s in (signal.SIGTERM, signal.SIGINT, signal.SIGHUP)])
        label = signal.Signals(sig).name if sig else "its end"
        try:
            if sig:
                end = time.time() + 60
                while time.time() < end and not (os.path.exists(log) and len(open(log).read().splitlines()) >= 2):
                    time.sleep(0.05)
                os.killpg(p.pid, sig)
            out, _ = p.communicate(timeout=120)
        except subprocess.TimeoutExpired:
            os.killpg(p.pid, signal.SIGKILL)
            out, _ = p.communicate()
            bad.append("the child suite did not end after %s:\n%s" % (label, out[-300:]))
            continue
        made = [l.rstrip("\n") for l in open(log)] if os.path.exists(log) else []
        made_all += len(made)
        left = [m for m in made if os.path.lexists(m)] + [os.path.join(tmp, x) for x in os.listdir(tmp)]
        if not made:
            bad.append("%s: the probe saw no mktemp call, so what it measures is nothing:\n%s" % (label, out[-300:]))
        elif not sig and "ONE CHECK GREEN: " + SUBJECT not in out:
            bad.append("the subject check did not run to its end, so it measures nothing:\n" + out[-300:])
        elif sig and "ONE CHECK GREEN" in out:
            bad.append("%s: the child was not taken off, so it measures nothing" % label)
        else:
            if left:
                bad.append("%s: %d of the %d entries a suite made are still there: %s" % (label, len(left), len(made), ", ".join(left[:3])))
            if p.returncode != want_rc:
                bad.append("%s: the run ended with %s, a shell reports %d for it" % (label, p.returncode, want_rc))
    if bad:
        sys.exit("\n".join(bad))
    print("%d entries made by a suite %s, none left" % (made_all, "run to its end" if mode == "end" else "taken off by TERM, INT and HUP"))
finally:
    shutil.rmtree(work, ignore_errors=True)
PY
}

a_suite_run_to_its_end_leaves_nothing_in_its_temp() { tmp_probe end; }
a_suite_taken_off_leaves_nothing_in_its_temp() { tmp_probe taken-off; }

# THE PROBE DOES NOT DEPEND ON HOW IT WAS STARTED. A command started with & has INT ignored and one started under
# nohup has HUP ignored [measured 2026-11-07 under bash 3.2.57, python3 -I printing its dispositions: in the foreground
# INT, TERM and HUP default; with & INT ignored; under nohup HUP ignored]. A signal ignored on entry stays ignored in
# every child, and a shell cannot trap it again. The child suite of the probe then sat through its hold, every mktemp
# after the second held again, and the check was green in 2 s in the foreground and red after 120 s with &,
# "the child suite did not end after SIGINT", with no other run beside it. It was first taken for a fault under
# load, because it showed when copies ran side by side.
# The caller is put in that state here, with trap '' in a subshell, which hands the ignoring on to python3 exactly as & does,
# and with TERM too, so that each of the three signals the probe sends is one its caller could have ignored.
the_temp_probe_does_not_depend_on_how_its_caller_was_started() {
  (
    trap '' INT TERM HUP
    python3 -I -c 'import signal, sys; sys.exit(0 if all(signal.getsignal(s) == signal.SIG_IGN for s in (signal.SIGINT, signal.SIGTERM, signal.SIGHUP)) else 1)' \
      || { echo "the subshell did not hand an ignored INT, TERM and HUP on to python3, so this measures nothing"; exit 1; }
    tmp_probe taken-off
  )
}

# THE TWO KNOBS THE FAST MUTATION RUN USES, asked of the real file. A named check runs alone and the run
# ends with its own word, never ALL GREEN, so a partial run cannot be mistaken for the whole one; a name
# that no check carries is red and not an empty pass.
one_named_check_runs_alone_and_an_unknown_name_is_red() {
  bad=0
  one='both manifests carry one version'
  out=$(env -u MK_RUN_ROOT -u MK_STOP_AT_RED MK_ONLY_CHECK="$one" bash "$ROOT/tests/run.sh" 2>&1 < /dev/null); rc=$?
  [ "$rc" = 0 ] || { echo "the one named check was not green: exit $rc"; bad=1; }
  [ "$(printf '%s\n' "$out" | grep -c '^  OK ')" = 1 ] || { echo "more or fewer than one check ran: $(printf '%s\n' "$out" | grep -c '^  OK ')"; bad=1; }
  case $out in *"ONE CHECK GREEN: $one"*) ;; *) echo "the run does not end with its own word"; bad=1 ;; esac
  case $out in *"ALL GREEN"*) echo "a one check run said ALL GREEN"; bad=1 ;; esac
  out=$(env -u MK_RUN_ROOT -u MK_STOP_AT_RED MK_ONLY_CHECK='a name that no check carries' bash "$ROOT/tests/run.sh" 2>&1 < /dev/null); rc=$?
  [ "$rc" != 0 ] || { echo "a name no check carries was an exit 0"; bad=1; }
  case $out in *"RED: no check is named a name that no check carries"*) ;; *) echo "a name no check carries did not say so: $(printf '%s' "$out" | tail -2)"; bad=1 ;; esac
  [ "$bad" = 0 ] && echo 'one named check runs alone and ends with its own word, an unknown name is red'
  return $bad
}

# MK_STOP_AT_RED ends the run at the first red check. A copy of this file in a package of its own gets two
# red checks and a line that must not be reached, so one run shows both the stop and, without the knob, that
# the copy goes on past it.
the_first_red_check_ends_a_run_asked_to_stop_there() {
  bad=0
  d=$(mktemp -d); mkdir -p "$d/tests"
  python3 -I - "$ROOT/tests/run.sh" "$d/tests/run.sh" <<'PY'
import sys
t = open(sys.argv[1], encoding="utf-8").read()
mark = "\nharness_gate\n"
if t.count(mark) != 1:
    sys.exit("harness_gate stands %d times as a call" % t.count(mark))
t = t.replace(mark, mark + "check 'red one' false\ncheck 'red two' false\necho REACHED-PAST-THE-RED-ONES\nexit 5\n")
open(sys.argv[2], "w", encoding="utf-8").write(t)
PY
  free=$(env -u MK_RUN_ROOT -u MK_ONLY_CHECK -u MK_STOP_AT_RED bash "$d/tests/run.sh" 2>&1 < /dev/null); rc=$?
  { [ "$rc" = 5 ] && case $free in *'FAIL red one'*'FAIL red two'*REACHED-PAST*) true ;; *) false ;; esac; } ||
    { echo "without the knob the copy did not run past both red checks (exit $rc), so the stop below measures nothing"; bad=1; }
  stopped=$(env -u MK_RUN_ROOT -u MK_ONLY_CHECK MK_STOP_AT_RED=1 bash "$d/tests/run.sh" 2>&1 < /dev/null); rc=$?
  [ "$rc" = 1 ] || { echo "the run asked to stop at the first red ended with exit $rc, expected 1"; bad=1; }
  case $stopped in *'FAIL red one'*) ;; *) echo "the first red check is not reported"; bad=1 ;; esac
  case $stopped in *'FAIL red two'*|*REACHED-PAST*) echo "the run went on past the first red check"; bad=1 ;; esac
  [ "$bad" = 0 ] && echo 'a run asked to stop ends at the first red check, and the same copy goes on without the ask'
  return $bad
}

# mu_py <case> runs one of the cases below against tests/mutate.py as it stands in this package, with
# a fake repository of one file and a fake suite of four checks, so what is measured is the runner and
# not the 240 checks. The fake suite answers the two knobs the real one answers.
mu_py() {
  python3 -I - "$ROOT" "$1" <<'PY'
import importlib.util, os, shutil, signal, subprocess, sys, tempfile, time
sys.dont_write_bytecode = True
root, case = sys.argv[1], sys.argv[2]
spec = importlib.util.spec_from_file_location("mutate", os.path.join(root, "tests", "mutate.py"))
mu = importlib.util.module_from_spec(spec)
spec.loader.exec_module(mu)

work = tempfile.mkdtemp(prefix="mufake.")
pids = os.path.join(work, "pids")
log = os.path.join(work, "calls.log")
repo = os.path.join(work, "repo")
os.makedirs(os.path.join(repo, "pkg"))
with open(os.path.join(repo, "pkg", "x.txt"), "w") as fh:
    fh.write("AAA\n")
for knob in ("MK_ONLY_CHECK", "MK_STOP_AT_RED", "MK_RUN_ROOT"):
    os.environ.pop(knob, None)    # this check may itself be the one named, and the fake suite must not read that
os.environ["MU_PIDS"] = pids
os.environ["MU_LOG"] = log
SUITE = ["bash", "-c", r'''
v=$(cat pkg/x.txt)
printf 'only=%s stop=%s tmp=%s\n' "${MK_ONLY_CHECK-}" "${MK_STOP_AT_RED-}" "$TMPDIR" >> "$MU_LOG"
mkdir -p "$TMPDIR/made" "$TMPDIR/made2"
mkdir -p "$MU_OUTSIDE" 2>/dev/null; echo "$MU_OUTSIDE" >> "$MK_RUN_ROOT/.extra.$$"
for c in own-red own-lives-foreign-dies own-lives-nothing-dies hang; do
  if [ -n "${MK_ONLY_CHECK-}" ] && [ "$c" != "$MK_ONLY_CHECK" ]; then continue; fi
  case "$v:$c" in
    DIE-OWN:own-red|DIE-OWN:own-lives-nothing-dies|DIE-FOREIGN:own-lives-nothing-dies|DIE-FOREIGN:hang)
      echo "  FAIL $c"; [ -z "${MK_STOP_AT_RED-}" ] || exit 1 ;;
    HANG:*) sh -c 'echo $$ >> "$MU_PIDS"; trap "" TERM; exec sleep 20' & wait ;;   # a child that ignores TERM
    *) echo "  OK   $c" ;;
  esac
done
''']
ENTRIES = [
    ("own-red", "x.txt", "AAA", "DIE-OWN"),
    ("own-lives-foreign-dies", "x.txt", "AAA", "DIE-FOREIGN"),
    ("own-lives-nothing-dies", "x.txt", "AAA", "LIVE"),
    ("hang", "x.txt", "AAA", "HANG"),
    ("no-anchor", "x.txt", "NOT-THERE", "X"),
]
os.environ["MU_OUTSIDE"] = os.path.join(work, "outside")
kw = dict(suite=SUITE, repo=repo, pkg_name="pkg", base=work)


def seen(results):
    return [(r["name"], r["class"], list(r["dead"])) for r in results]


def alive(pid):
    try:
        os.kill(pid, 0)
        return True
    except ProcessLookupError:
        return False


def pids_left():
    try:
        return [int(l) for l in open(pids) if l.strip() and alive(int(l))]
    except OSError:
        return []


def roots_left():
    return [n for n in os.listdir(work) if n.startswith("mkm.")]


bad = []
try:
    if case == "leaves":
        # finished, with a path recorded outside the root, out of time, and taken off by a signal
        res = mu.run_one(ENTRIES[0], 0, **kw)
        if res["class"] != "RED":
            bad.append("the finished entry was %s" % res["class"])
        if roots_left() or os.path.exists(os.environ["MU_OUTSIDE"]):
            bad.append("a finished entry left its root or a path it recorded outside it: %s" % roots_left())
        res = mu.run_one(ENTRIES[3], 3, timeout=1.2, **kw)
        if roots_left():
            bad.append("an entry that ran out of time left its root: %s" % roots_left())
        if pids_left():
            bad.append("the process a late suite had started is still alive: %s" % pids_left())
        driver = os.path.join(work, "driver.py")
        with open(driver, "w") as fh:
            fh.write("import sys, os\nsys.dont_write_bytecode = True\nsys.path.insert(0, %r)\nimport mutate as mu\n"
                     "mu.install_signal_handlers()\nmu.run_one(%r, 3, suite=%r, repo=%r, pkg_name='pkg', base=%r)\n"
                     % (os.path.join(root, "tests"), ENTRIES[3], SUITE, repo, work))
        p = subprocess.Popen([sys.executable, "-I", driver], env=dict(os.environ), start_new_session=True,
                             stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        end = time.time() + 30
        while time.time() < end and not pids_left():
            time.sleep(0.05)
        if not pids_left():
            bad.append("the taken off entry never started its suite, so it measures nothing")
        os.kill(p.pid, signal.SIGTERM)
        try:
            rc = p.wait(timeout=30)
        except subprocess.TimeoutExpired:
            p.kill()
            rc = None
            bad.append("the runner did not end when it was told TERM")
        if rc is not None and rc != 128 + signal.SIGTERM:
            bad.append("the runner taken off ended with %s, expected %d" % (rc, 128 + signal.SIGTERM))
        time.sleep(0.3)
        if roots_left():
            bad.append("an entry taken off by TERM left its root: %s" % roots_left())
        if pids_left():
            bad.append("an entry taken off by TERM left its suite's process alive: %s" % pids_left())
        if not bad:
            print("a finished, a late and a taken off entry each leave no root, no recorded path and no process")
    elif case == "limit":
        res = mu.run_one(ENTRIES[3], 3, timeout=1.2, **kw)
        if res["class"] != "TIMEOUT":
            bad.append("an entry past its limit is %s, expected TIMEOUT" % res["class"])
        lines = mu.entry_lines(res)
        if not lines or not lines[0].lstrip().startswith("TIMEOUT") or any("RED" in l or "ALIVE" in l for l in lines):
            bad.append("the line of a late entry does not say TIMEOUT alone: %r" % lines)
        if res["dead"]:
            bad.append("a late entry is judged by what it printed before the limit: %r" % res["dead"])
        ok = mu.run_one(ENTRIES[0], 0, timeout=60, **kw)
        if ok["class"] != "RED":
            bad.append("a limit that is not reached changed the verdict to %s" % ok["class"])
        if not bad:
            print("an entry past its limit is TIMEOUT, not RED and not ALIVE, and a limit not reached changes nothing")
    elif case == "same":
        for fast in (False, True):
            entries = [e for e in ENTRIES if e[0] != "hang"] if fast else ENTRIES
            one = seen(mu.run_all(entries, jobs=1, fast=fast, timeout=1.2, **kw))
            many = seen(mu.run_all(entries, jobs=4, fast=fast, timeout=1.2, **kw))
            if one != many:
                bad.append("%s: one at a time %r, four at a time %r" % ("fast" if fast else "full", one, many))
            if [n for n, _, _ in many] != [e[0] for e in entries]:
                bad.append("the results are not in the order of the register: %r" % [n for n, _, _ in many])
        if not bad:
            print("one at a time and four at a time judge every entry alike, in the order of the register, in both modes")
    elif case == "fast":
        full = {r["name"]: r for r in mu.run_all([e for e in ENTRIES if e[0] != "hang"], **kw)}
        open(log, "w").close()
        fast = {r["name"]: r for r in mu.run_all([e for e in ENTRIES if e[0] != "hang"], fast=True, **kw)}
        for n in full:
            if full[n]["class"] != fast[n]["class"]:
                bad.append("%s: the whole suite says %s, fast says %s" % (n, full[n]["class"], fast[n]["class"]))
        if fast["own-red"]["dead"] != ["own-red"]:
            bad.append("an entry whose own check died is judged by more than that: %r" % fast["own-red"]["dead"])
        # The foreign check that is red beside an own check that lives is named, once, and the entry stays ALIVE.
        if fast["own-lives-foreign-dies"]["dead"] != ["own-lives-nothing-dies"] or fast["own-lives-foreign-dies"]["class"] != "ALIVE":
            bad.append("an entry killed only by a foreign check: %r" % fast["own-lives-foreign-dies"])
        calls = open(log).read().splitlines()
        asked = [c.split(" tmp=")[0] for c in calls]
        if asked.count("only=own-red stop=") != 1 or asked.count("only= stop=1") != 2:
            bad.append("the own check is not asked first and alone, then the stop at the first red, only for a living one: %r" % asked)
        if full["own-red"]["dead"] != ["own-red", "own-lives-nothing-dies"]:
            bad.append("the whole suite no longer lists what died beside the own check: %r" % full["own-red"]["dead"])
        if not bad:
            print("fast asks the own check alone first, looks further only when it lived, and gives the verdict the whole suite gives")
    elif case == "report":
        # Results made by hand, one of each class: what is asked here is the text, not the runs.
        def made(name, cls, dead, note=""):
            return {"name": name, "file": "x.txt", "anchor": "AAA" if name != "no-anchor" else "NOT-THERE",
                    "class": cls, "dead": dead, "note": note, "seconds": 1.0}
        res = [made("own-red", "RED", ["own-red"]), made("own-lives-foreign-dies", "ALIVE", ["own-lives-nothing-dies"]),
               made("own-lives-nothing-dies", "ALIVE", []), made("hang", "TIMEOUT", [], "no verdict within 1.2 s"),
               made("no-anchor", "ERROR", [], "anchor not found in x.txt: 'NOT-THERE'")]
        text = mu.report_text(res, 12.0, 1, False, 1.2)
        for want in ("RED       1", "ALIVE     2", "TIMEOUT   1", "ERROR     1",
                     "ALIVE  own-lives-foreign-dies", "file    x.txt", "anchor  'AAA'",
                     "TIMEOUT  hang", "ERROR  no-anchor", "anchor  'NOT-THERE'", "also dead  own-lives-nothing-dies"):
            if want not in text:
                bad.append("the report does not carry %r" % want)
        if "RED  own-red" in text:
            bad.append("the report lists an entry that is red")
        if not bad:
            print("the report counts each class and names file and anchor of each entry that is not red")
    elif case == "base":
        proj = os.path.join(work, "proj")
        os.makedirs(os.path.join(proj, ".git", "x"))
        os.makedirs(os.path.join(work, "home", ".claude", "tmp"))
        os.makedirs(os.path.join(work, "plain", "tmp"))
        keep = os.environ.get("TMPDIR")
        try:
            for label, d, plain in (("below a .git", os.path.join(proj, "x"), False),
                                    ("below a .claude", os.path.join(work, "home", ".claude", "tmp"), False),
                                    ("plain", os.path.join(work, "plain", "tmp"), True)):
                os.environ["TMPDIR"] = d
                got = mu.temp_base()
                if plain and got != d:
                    bad.append("a plain TMPDIR is not used: %s" % got)
                if not plain and got == d:
                    bad.append("a TMPDIR %s is used for the roots" % label)
        finally:
            if keep is None:
                os.environ.pop("TMPDIR", None)
            else:
                os.environ["TMPDIR"] = keep
        if not bad:
            print("the runner keeps its roots out of a project and a .claude as the suite does")
    elif case == "linear":
        # the entry whose replacement used to spin: asked for the text it makes of a long command
        entry = [e for e in mu.MUTATIONS if e[0] == "the verdict comes from the whole command"][0]
        expr = entry[3][len('say("CMD", '):-1]
        if not entry[3].startswith('say("CMD", ') or not entry[3].endswith(")"):
            bad.append("the replacement is not a say(\"CMD\", ...) call any more: %r" % entry[3][:60])
        else:
            # 20000 characters first: the quadratic form needs 8 s for them [measured 2026-11-07], so a
            # replacement that is quadratic again is red after that and not after the 13 minutes of 200000.
            for n, shape in ((20000, "x"), (200000, "x"), (200000, "key"), (200000, "a1_"), (200000, "KEY=v ")):
                cmd = "echo " + shape * (n // len(shape)) + " > src/a.py"
                t0 = time.time()
                eval(expr, {"ti": {"command": cmd}})
                took = time.time() - t0
                if took > 2:
                    bad.append("the replacement took %.0f s on %d characters of %r" % (took, len(cmd), shape))
                    break
            for cmd, want in (("API_KEY=src/a.py; echo x > $API_KEY", "API_KEY=[redacted]; echo x > $API_KEY"),
                              ("export TOKEN=src/a.py && cp /dev/null $TOKEN", "export TOKEN=[redacted] && cp /dev/null $TOKEN")):
                got = eval(expr, {"ti": {"command": cmd}})
                if got != want:
                    bad.append("the replacement no longer takes the value of a secret named variable: %r" % got)
        if not bad:
            print("the replacement reads 200000 characters in linear time and still blacks out a secret named variable")
finally:
    shutil.rmtree(work, ignore_errors=True)
if bad:
    sys.exit("\n".join(bad))
PY
}

# THE ROOT OF A RUN IS NEVER INSIDE A PROJECT OR A .claude, whatever TMPDIR says: in a directory below a
# .git and in one below a .claude the root must lie elsewhere, and in a plain one it must lie in it, or the
# first two measure nothing. The first path a mktemp on the PATH of the child hands out is the root itself.
the_root_of_a_run_is_never_inside_a_project_or_a_claude() {
  python3 -I - "$ROOT" <<'PY'
import os, shutil, subprocess, sys, tempfile
root = sys.argv[1]
work = tempfile.mkdtemp(prefix="rootprobe.")
try:
    bindir = os.path.join(work, "bin")
    log = os.path.join(work, "made.log")
    os.mkdir(bindir)
    fake = os.path.join(bindir, "mktemp")
    with open(fake, "w") as fh:
        fh.write('#!/bin/sh\nr=$(/usr/bin/mktemp "$@") || exit $?\nprintf \'%s\\n\' "$r" >> "$MK_PROBE_LOG"\nprintf \'%s\\n\' "$r"\n')
    os.chmod(fake, 0o755)
    os.makedirs(os.path.join(work, "proj", ".git"))
    places = [("a directory below a .git", os.path.join(work, "proj", "tmp"), False),
              ("a directory below a .claude", os.path.join(work, "home", ".claude", "tmp"), False),
              ("a plain directory", os.path.join(work, "plain", "tmp"), True)]
    for _, d, _ in places:
        os.makedirs(d)
    drop = ("MK_RUN_ROOT", "MK_RUN", "MK_EXTRA", "MK_ONLY_CHECK", "MK_STOP_AT_RED")
    base = {k: v for k, v in os.environ.items() if k not in drop and not k.startswith("BASH_FUNC_")}
    bad = []
    for label, tmp, plain in places:
        open(log, "w").close()
        env = dict(base, TMPDIR=tmp + "/", MK_PROBE_LOG=log, MK_ONLY_CHECK="both manifests carry one version",
                   PATH=bindir + ":" + base["PATH"])
        subprocess.run(["bash", os.path.join(root, "tests", "run.sh")], cwd=root, env=env, stdin=subprocess.DEVNULL,
                       capture_output=True, text=True, errors="replace")
        made = open(log).read().splitlines()
        if not made:
            bad.append("%s: the run made no root, so this measures nothing" % label)
            continue
        inside = os.path.realpath(made[0]).startswith(os.path.realpath(tmp) + os.sep)
        if plain and not inside:
            bad.append("%s: the root %s is not in the TMPDIR it was given" % (label, made[0]))
        if not plain and inside:
            bad.append("%s: the root lies inside it: %s" % (label, made[0]))
    if bad:
        sys.exit("\n".join(bad))
    print("a TMPDIR below a .git or a .claude is not used for the root, a plain one is")
finally:
    shutil.rmtree(work, ignore_errors=True)
PY
}

a_mutation_run_leaves_nothing_in_its_temp() { mu_py leaves; }
the_runner_keeps_its_roots_out_of_a_project_and_a_claude() { mu_py base; }
a_mutant_past_its_limit_is_a_class_of_its_own() { mu_py limit; }
runs_side_by_side_judge_every_entry_as_runs_one_after_the_other_do() { mu_py same; }
the_own_check_of_an_entry_is_asked_first_and_alone() { mu_py fast; }
the_report_of_a_run_names_every_entry_that_is_not_red() { mu_py report; }
the_whole_command_mutant_reads_a_long_command_in_linear_time() { mu_py linear; }

check 'a big file in the project holds no hook'                        a_big_file_in_the_project_holds_no_hook
check 'a big log, definition or settings file holds no hook'            a_big_log_definition_or_settings_file_holds_no_hook
check 'a .git file names its own repository or nothing'                a_git_file_names_its_own_repository_or_nothing
check 'a session inside the home .claude or above a linked home keeps no record' a_session_inside_the_home_claude_or_above_a_linked_home_keeps_no_record
check 'a hardlink under .claude is not written through'                a_hardlink_under_claude_is_not_written_through
check 'the files of the kit are all in the exclusion'                  the_files_of_the_kit_are_all_in_the_exclusion
check 'a field of the log line cannot move into another'               a_field_of_the_log_line_cannot_move_into_another
# ------------------------------------------------------------------ the cost meter (MK-B1)
# tools/mk-cost.sh reads Claude Code transcripts and prints list price dollars per role and model. Everything
# below runs it on FIXTURE transcripts only: CLAUDE_CONFIG_DIR points into a mktemp directory, and HOME does
# too, in every call, so that no mutant of the tool that loses CLAUDE_CONFIG_DIR can read a real transcript.
#
# THE EXPECTED NUMBERS ARE COMPUTED BY HAND from the fixture lines and the prices in tools/prices.tsv, and the
# reckoning stands beside each fixture line. Nothing here compares the tool with a second run of itself.
# Each trap of the transcript format has a row of its own (a role and model nobody else uses), so a mutant of
# one trap moves one row; the % column moves with every change of the total and is asserted only by the
# whole table, which is why cost_row leaves it out.
#
# The fixture, one line per transcript line: file | timestamp | message.id | requestId | model | input |
# cache_read | cache_creation | 5m | 1h | output | attributionAgent. A "-" leaves the field out of the line;
# 5m and 1h both "-" leave the cache_creation object out.
cost_put() {
  python3 -I -c '
import json, os, sys
root = sys.argv[1]
for line in sys.stdin:
    line = line.strip()
    if not line or line.startswith("#"):
        continue
    if line.startswith("USER|"):
        # USER | file | timestamp | kind: a user line of the transcript (MK-B2b), in the shape Claude Code 2.1.318 writes,
        # read out of its binary on 2026-11-08 and not out of any transcript. text: a typed input, content a string;
        # list: an input as a list of text blocks; tool: a tool result, a list with a tool_result block and toolUseResult;
        # meta: a line with isMeta; summary: the summary after a compaction, isCompactSummary.
        _, f, ts, kind = [x.strip() for x in line.split("|")]
        d = {"type": "user", "timestamp": ts, "message": {"role": "user", "content": "weiter"}}
        if kind == "list":
            d["message"]["content"] = [{"type": "text", "text": "weiter"}]
        elif kind == "tool":
            d["message"]["content"] = [{"tool_use_id": "toolu_1", "type": "tool_result", "content": "ok"}]
            d["toolUseResult"] = {"stdout": "ok"}
        elif kind == "meta":
            d["isMeta"] = True
        elif kind == "summary":
            d["isCompactSummary"] = True
            d["isVisibleInTranscriptOnly"] = True
        elif kind != "text":
            raise SystemExit("cost_put: no user line of the kind " + kind)
        p = os.path.join(root, f)
        os.makedirs(os.path.dirname(p), exist_ok=True)
        with open(p, "a", encoding="utf-8") as fh:
            fh.write(json.dumps(d) + "\n")
        continue
    if line.startswith("MARK|"):
        # MARK | file | timestamp | uuid | trigger | preTokens [| postTokens]: a compaction line (MK-B2a), "-" leaves a
        # field out. postTokens (MK-B2b) is set by Claude Code 2.1.318 after the line is made, read out of its binary.
        fields = [x.strip() for x in line.split("|")]
        _, f, ts, uuid, trig, pre = fields[:6]
        post = fields[6] if len(fields) > 6 else "-"
        md = {}
        if trig != "-":
            md["trigger"] = trig
        if pre != "-":
            md["preTokens"] = int(pre)
        if post != "-":
            md["postTokens"] = int(post)
        d = {"type": "system", "subtype": "compact_boundary", "content": "Conversation compacted", "isMeta": False,
             "timestamp": ts, "level": "info", "compactMetadata": md}
        if uuid != "-":
            d["uuid"] = uuid
        p = os.path.join(root, f)
        os.makedirs(os.path.dirname(p), exist_ok=True)
        with open(p, "a", encoding="utf-8") as fh:
            fh.write(json.dumps(d) + "\n")
        continue
    f, ts, mid, rid, model, inp, cr, cw, c5, c1, out, attr = [x.strip() for x in line.split("|")]
    u = {}
    for k, v in (("input_tokens", inp), ("cache_read_input_tokens", cr),
                 ("cache_creation_input_tokens", cw), ("output_tokens", out)):
        if v != "-":
            u[k] = int(v)
    if c5 != "-" or c1 != "-":
        u["cache_creation"] = {"ephemeral_5m_input_tokens": int(c5) if c5 != "-" else 0,
                               "ephemeral_1h_input_tokens": int(c1) if c1 != "-" else 0}
    d = {"type": "assistant", "timestamp": ts,
         "message": {"id": mid, "model": model, "role": "assistant", "usage": u}}
    if rid != "-":
        d["requestId"] = rid
    if attr != "-":
        d["attributionAgent"] = attr
    p = os.path.join(root, f)
    os.makedirs(os.path.dirname(p), exist_ok=True)
    with open(p, "a", encoding="utf-8") as fh:
        fh.write(json.dumps(d) + "\n")
' "$1"
}
# cost_world <dir>: the canonical fixture under <dir>/cfg, an empty <dir>/home. $/MTok as in tools/prices.tsv:
#   opus-5-5 4 / 5 / 8 / 0.2 / 20      opus-5 and opus-4-8 5 / 6.25 / 10 / 0.5 / 25
#   sonnet-5-5 2 / 2.5 / 4 / 0.1 / 10  sonnet-5 2 / 2.5 / 4 / 0.2 / 10   haiku-4-5 1 / 1.25 / 2 / 0.1 / 5
#   haiku-5-5 0.1 / 0.125 / 0.2 / 0.01 / 0.5, and above 100000 input tokens 0.5 / 0.625 / 1 / 0.05 / 2.5
#   (input, write 5m, write 1h, read, output). The canonical window is 2026-10-01..2026-10-15.
cost_world() {
  _p=$1/cfg/projects
  mkdir -p "$1/home" "$_p" || return 1
  cost_put "$_p" <<'EOS' || return 1
# m1, ONE ANSWER STREAMED OVER THREE LINES, output growing. The last line counts:
#   0.1M in * 4 = 0.40, 1M read * 0.2 = 0.20, 0.5M out * 20 = 10.00 -> 10.60 (the first line would be 1.60)
-tmp-proj-main/sess-1.jsonl|2026-10-10T12:00:01.000Z|m1|q1|claude-opus-5-5|100000|1000000|0|0|0|50000|-
-tmp-proj-main/sess-1.jsonl|2026-10-10T12:00:02.000Z|m1|q1|claude-opus-5-5|100000|1000000|0|0|0|200000|-
-tmp-proj-main/sess-1.jsonl|2026-10-10T12:00:03.000Z|m1|q1|claude-opus-5-5|100000|1000000|0|0|0|500000|-
# m2, 5m AGAINST 1h: 0.2M * 6.25 = 1.25, 0.4M * 10 = 4.00 -> 5.25 (all of it as 5m would be 3.75)
-tmp-proj-main/sess-1.jsonl|2026-10-10T12:01:00.000Z|m2|q2|claude-opus-5|0|0|600000|200000|400000|0|-
# m9, CREATION WITHOUT THE TTL FIELDS is 5m: 0.2M * 6.25 = 1.25 (as 1h it would be 2.00)
-tmp-proj-main/sess-1.jsonl|2026-10-10T12:02:00.000Z|m9|q9|claude-opus-4-8|0|0|200000|-|-|0|-
# m8, A MAIN SESSION LINE THAT CARRIES attributionAgent stays manager: 1M * 0.2 = 0.20, 0.1M * 10 = 1.00 -> 1.20
-tmp-proj-main/sess-1.jsonl|2026-10-10T12:03:00.000Z|m8|q8|claude-sonnet-5|0|1000000|0|0|0|100000|high
# m4, THE SAME ANSWER IN TWO FILES counts once: 2M * 0.1 = 0.20, 0.2M * 10 = 2.00 -> 2.20 (twice would be 4.40)
-tmp-proj-main/sess-1.jsonl|2026-10-10T12:04:00.000Z|m4|q4|claude-sonnet-5-5|0|2000000|0|0|0|200000|-
-tmp-proj-main/sess-2.jsonl|2026-10-10T12:04:00.000Z|m4|q4|claude-sonnet-5-5|0|2000000|0|0|0|200000|-
# m5, <synthetic>: a round, no price
-tmp-proj-main/sess-2.jsonl|2026-10-10T12:05:00.000Z|m5|q5|<synthetic>|0|0|0|0|0|0|-
# m6, HAIKU AT EXACTLY 100000 input tokens keeps the first tier: 0.1M * 0.1 = 0.01, 1M * 0.5 = 0.50 -> 0.51
#   (the second tier would be 0.05 + 2.50 = 2.55)
-tmp-proj-main/sess-2.jsonl|2026-10-10T12:06:00.000Z|m6|q6|claude-haiku-5-5|100000|0|0|0|0|1000000|-
# h1, A HAND TYPED BY attributionAgent although its meta.json says max: 1M * 0.1 = 0.10, 0.1M * 10 = 1.00 -> 1.10
-tmp-proj-main/sess-1/subagents/agent-a1.jsonl|2026-10-10T12:07:00.000Z|h1|r1|claude-sonnet-5-5|0|1000000|0|0|0|100000|high
# h2, A HAND TYPED BY meta.json (medium), no attributionAgent: 0.16M out * 10 = 1.60
-tmp-proj-main/agent-b2.jsonl|2026-10-10T12:08:00.000Z|h2|r2|claude-sonnet-5-5|0|0|0|0|0|160000|-
# h3, A FILE UNDER subagents/ that is not called agent-*, with no type anywhere: 0.2M * 5 = 1.00
-tmp-proj-main/sess-2/subagents/worker-c3.jsonl|2026-10-10T12:09:00.000Z|h3|r3|claude-haiku-4-5-20251001|0|0|0|0|0|200000|-
# h7, HAIKU ABOVE 100000: 0 in + 0.2M read = 200000 input tokens, second tier: 0.2M * 0.05 = 0.01,
#   1M * 2.5 = 2.50 -> 2.51 (the first tier would be 0.002 + 0.50 = 0.50)
-tmp-proj-main/agent-d4.jsonl|2026-10-10T12:10:00.000Z|h7|r7|claude-haiku-5-5|0|200000|0|0|0|1000000|low
# h8, AN ANSWER WITHOUT requestId, streamed over two lines: counted once, by its last line:
#   0.1M * 1 = 0.10, 0.1M * 5 = 0.50 -> 0.60
-tmp-proj-main/agent-d4.jsonl|2026-10-10T12:11:00.000Z|h8|-|claude-haiku-4-5-20251001|100000|0|0|0|0|40000|low
-tmp-proj-main/agent-d4.jsonl|2026-10-10T12:11:01.000Z|h8|-|claude-haiku-4-5-20251001|100000|0|0|0|0|100000|low
# h6, A FILE WHOSE NAME carries the text of an --exclude, in a folder that does not: kept, 0.1M * 20 = 2.00
-tmp-proj-main/agent-zeta-f6.jsonl|2026-10-10T12:12:00.000Z|h6|r6|claude-opus-5-5|0|0|0|0|0|100000|nichtweg
# t1..t4, THE EDGES OF THE WINDOW, one second either side of each bound:
#   anfang keeps t2 only, 0.05M * 20 = 1.00; ende keeps t3 only, 0.1M * 20 = 2.00 (t1 and t4 are 20.00 each)
-tmp-proj-main/agent-t5.jsonl|2026-09-30T23:59:59.999Z|t1|u1|claude-opus-5-5|0|0|0|0|0|1000000|anfang
-tmp-proj-main/agent-t5.jsonl|2026-10-01T00:00:00.000Z|t2|u2|claude-opus-5-5|0|0|0|0|0|50000|anfang
-tmp-proj-main/agent-t5.jsonl|2026-10-15T23:59:59.999Z|t3|u3|claude-opus-5-5|0|0|0|0|0|100000|ende
-tmp-proj-main/agent-t5.jsonl|2026-10-16T00:00:00.000Z|t4|u4|claude-opus-5-5|0|0|0|0|0|1000000|ende
# z1, o1, TWO FOLDERS FOR --exclude, 20.00 each, never in the canonical table
-tmp-Zeta-side/agent-z.jsonl|2026-10-10T12:13:00.000Z|z1|v1|claude-opus-5-5|0|0|0|0|0|1000000|wegZ
-tmp-omega-two/agent-o.jsonl|2026-10-10T12:14:00.000Z|o1|w1|claude-opus-5-5|0|0|0|0|0|1000000|wegO
EOS
  # A line that carries "usage" and is no JSON: not a round, and counted as unreadable.
  printf '{"type": "assistant", "message": {"usage": {"input_tokens": 1\n' >> "$_p/-tmp-proj-main/sess-1.jsonl"
  printf '{"agentType": "max"}\n' > "$_p/-tmp-proj-main/sess-1/subagents/agent-a1.meta.json"
  printf '{"agentType": "medium"}\n' > "$_p/-tmp-proj-main/agent-b2.meta.json"
}
# cost_tool <world> <args>: the tool on a fixture, never with the real HOME or a real CLAUDE_CONFIG_DIR.
cost_tool() {
  _cw=$1; shift
  HOME=$_cw/home CLAUDE_CONFIG_DIR=$_cw/cfg bash "$ROOT/tools/mk-cost.sh" "$@"
}
# cost_canon: the canonical fixture and the canonical call, into $w and $out of the calling check.
cost_canon() {
  w=$(mktemp -d); cost_world "$w" || return 1
  out=$(cost_tool "$w" --since 2026-10-01 --until 2026-10-15 --exclude zETA --exclude OMEGA 2>&1); _rc=$?
  [ "$_rc" = 0 ] || { echo "the canonical call ended $_rc:"; printf '%s\n' "$out" | head -5; return 1; }
}
# cost_row <output> <label> -> the row, one space between fields, without its % column
cost_row() {
  printf '%s\n' "$1" | awk -v l="$2" '$1 == l { $4 = ""; $0 = $0; $1 = $1; print; exit }'
}
# cost_expect <output> "<label> <rounds> <$> <read> <write 5m> <write 1h> <output>"
cost_expect() {
  _want=$2; _lab=${_want%% *}
  _got=$(cost_row "$1" "$_lab")
  [ "$_got" = "$_want" ] && return 0
  echo "the row $_lab is not the one computed by hand"; echo "  want: $_want"; echo "  got:  ${_got:-(no such row)}"
  return 1
}
cost_absent() {
  _got=$(cost_row "$1" "$2")
  [ -z "$_got" ] && return 0
  echo "the row $2 must not be there: $_got"; return 1
}
# cost_refused <exit> <output> <word>: the format guard spoke, in one line, and printed no number of cost.
cost_refused() {
  [ "$1" = 3 ] || { echo "expected exit 3, got $1:"; printf '%s\n' "$2" | head -4; return 1; }
  [ "$(printf '%s\n' "$2" | grep -c .)" = 1 ] || { echo "the refusal is not one line:"; printf '%s\n' "$2" | head -4; return 1; }
  case $2 in *"LOWER BOUND"*|*Role/Model*|*Total*) echo "the refusal printed a table: $2"; return 1 ;; esac
  case $2 in *"$3"*) ;; *) echo "the refusal does not name its reason ($3): $2"; return 1 ;; esac
}

cost_prints_the_table_computed_by_hand() {
  cost_canon || return 1
  got=$(printf '%s\n' "$out" | sed -n '4,$p' | awk '{ $1 = $1; print }')
  # % of the priced total 32.82 = 10.60 + 5.25 + 2.51 + 2.20 + 2.00 + 2.00 + 1.60 + 1.25 + 1.20 + 1.10 + 1.00
  # + 1.00 + 0.60 + 0.51, rounded to one place: 10.60 / 32.82 = 32.30 %, 5.25 -> 16.00, 2.51 -> 7.65, 2.20 -> 6.70,
  # 2.00 -> 6.09, 1.60 -> 4.88, 1.25 -> 3.81, 1.20 -> 3.66, 1.10 -> 3.35, 1.00 -> 3.05, 0.60 -> 1.83, 0.51 -> 1.55.
  # Rows by dollars, a tie by label, the rows without a price last. Sums: rounds 15; read 1M + 2M + 0.2M + 1M + 1M;
  # write 5m 0.2M + 0.2M (m2, m9); write 1h 0.4M (m2); output 3.61M = m1 0.5M + h7 1M + m4 0.2M + h6, ende, m8,
  # h1, h8 0.1M each + h2 0.16M + anfang 0.05M + h3 0.2M + m6 1M.
  want=$(cat <<'EOT'
Role/Model Rounds $-eq % Read Wr5m Wr1h Out
manager/claude-opus-5-5 1 10.60 32.3 1000000 0 0 500000
manager/claude-opus-5 1 5.25 16.0 0 200000 400000 0
hand:low/claude-haiku-5-5 1 2.51 7.6 200000 0 0 1000000
manager/claude-sonnet-5-5 1 2.20 6.7 2000000 0 0 200000
hand:ende/claude-opus-5-5 1 2.00 6.1 0 0 0 100000
hand:nichtweg/claude-opus-5-5 1 2.00 6.1 0 0 0 100000
hand:medium/claude-sonnet-5-5 1 1.60 4.9 0 0 0 160000
manager/claude-opus-4-8 1 1.25 3.8 0 200000 0 0
manager/claude-sonnet-5 1 1.20 3.7 1000000 0 0 100000
hand:high/claude-sonnet-5-5 1 1.10 3.4 1000000 0 0 100000
hand:anfang/claude-opus-5-5 1 1.00 3.0 0 0 0 50000
hand:unknown/claude-haiku-4-5-20251001 1 1.00 3.0 0 0 0 200000
hand:low/claude-haiku-4-5-20251001 1 0.60 1.8 0 0 0 100000
manager/claude-haiku-5-5 1 0.51 1.6 0 0 0 1000000
manager/<synthetic> 1 - - 0 0 0 0
Total 15 32.82 100.0 5200000 400000 400000 3610000
EOT
)
  [ "$got" = "$want" ] && return 0
  echo "the table is not the one computed by hand:"
  diff <(printf '%s\n' "$want") <(printf '%s\n' "$got") | sed 's/^/  /'
  return 1
}
cost_counts_the_last_line_of_a_streamed_answer() {
  cost_canon || return 1
  cost_expect "$out" 'manager/claude-opus-5-5 1 10.60 1000000 0 0 500000'
}
cost_counts_an_answer_in_two_files_once() {
  cost_canon || return 1
  cost_expect "$out" 'manager/claude-sonnet-5-5 1 2.20 2000000 0 0 200000'
}
cost_counts_a_line_without_requestid_and_names_it() {
  cost_canon || return 1
  cost_expect "$out" 'hand:low/claude-haiku-4-5-20251001 1 0.60 0 0 0 100000' || return 1
  printf '%s\n' "$out" | sed -n 2p | grep -q 'Rounds without requestId 1,' ||
    { echo "the head does not name the round without requestId: $(printf '%s\n' "$out" | sed -n 2p)"; return 1; }
}
cost_counts_synthetic_as_a_row_without_a_price() {
  cost_canon || return 1
  cost_expect "$out" 'manager/<synthetic> 1 - 0 0 0 0'
}
cost_keeps_haiku_at_100000_tokens_on_its_first_tier() {
  cost_canon || return 1
  cost_expect "$out" 'manager/claude-haiku-5-5 1 0.51 0 0 0 1000000'
}
cost_prices_haiku_above_100000_tokens_on_its_second_tier() {
  cost_canon || return 1
  cost_expect "$out" 'hand:low/claude-haiku-5-5 1 2.51 200000 0 0 1000000'
}
cost_prices_creation_by_its_5m_and_1h_fields() {
  cost_canon || return 1
  cost_expect "$out" 'manager/claude-opus-5 1 5.25 0 200000 400000 0'
}
cost_prices_creation_without_ttl_fields_as_5m() {
