cost_counts_a_file_under_subagents_as_a_hand() {
  cost_canon || return 1
  cost_expect "$out" 'hand:unknown/claude-haiku-4-5-20251001 1 1.00 0 0 0 200000' || return 1
  cost_absent "$out" 'manager/claude-haiku-4-5-20251001' || return 1
  printf '%s\n' "$out" | sed -n 2p | grep -q 'hands without a type 1\.' ||
    { echo "the head does not name the hand without a type: $(printf '%s\n' "$out" | sed -n 2p)"; return 1; }
}
cost_keeps_a_main_session_line_manager() {
  cost_canon || return 1
  cost_expect "$out" 'manager/claude-sonnet-5 1 1.20 1000000 0 0 100000' || return 1
  cost_absent "$out" 'hand:high/claude-sonnet-5'
}
cost_excludes_a_project_folder_in_any_case() {
  w=$(mktemp -d); cost_world "$w" || return 1
  # the folder is -tmp-Zeta-side, the word is zETA; -tmp-omega-two is not named and stays
  out=$(cost_tool "$w" --since 2026-10-01 --until 2026-10-15 --exclude zETA 2>&1) || { echo "exit $?: $out"; return 1; }
  cost_absent "$out" 'hand:wegZ/claude-opus-5-5' || return 1
  cost_expect "$out" 'hand:wegO/claude-opus-5-5 1 20.00 0 0 0 1000000'
}
cost_excludes_by_the_folder_name_not_the_file() {
  # agent-zeta-f6.jsonl lies in -tmp-proj-main, which no --exclude names
  cost_canon || return 1
  cost_expect "$out" 'hand:nichtweg/claude-opus-5-5 1 2.00 0 0 0 100000'
}
cost_takes_exclude_more_than_once() {
  w=$(mktemp -d); cost_world "$w" || return 1
  # both words in the case of their folders, so this asks about the second word and not about case
  out=$(cost_tool "$w" --since 2026-10-01 --until 2026-10-15 --exclude Zeta --exclude omega 2>&1) || { echo "exit $?: $out"; return 1; }
  cost_absent "$out" 'hand:wegZ/claude-opus-5-5' || return 1
  cost_absent "$out" 'hand:wegO/claude-opus-5-5' || return 1
  printf '%s\n' "$out" | sed -n 2p | grep -q 'Excluded folders 2\.' ||
    { echo "the head does not count two excluded folders: $(printf '%s\n' "$out" | sed -n 2p)"; return 1; }
}
cost_keeps_the_day_since_names() {
  cost_canon || return 1
  cost_expect "$out" 'hand:anfang/claude-opus-5-5 1 1.00 0 0 0 50000'
}
cost_keeps_the_day_until_names() {
  cost_canon || return 1
  cost_expect "$out" 'hand:ende/claude-opus-5-5 1 2.00 0 0 0 100000'
}
# cost_many <projects dir> <known> <unknown> <missing...>: <known> rounds of opus-5-5 and <unknown> of a model
# no price row names; the first rounds lose one mandatory field each, in the order given.
cost_many() {
  _p=$1; _k=$2; _u=$3; shift 3
  _i=0
  while [ "$_i" -lt "$((_k + _u))" ]; do
    _i=$((_i + 1))
    _m=claude-opus-5-5; [ "$_i" -le "$_k" ] || _m=claude-zzz-9
    _in=0; _cr=0; _cw=0; _o=1000
    if [ $# -gt 0 ]; then
      case $1 in inp) _in=- ;; cr) _cr=- ;; cw) _cw=- ;; out) _o=- ;; esac
      shift
    fi
    printf -- '-tmp-many/s.jsonl|2026-10-10T12:00:00.000Z|n%s|k%s|%s|%s|%s|%s|0|0|%s|-\n' "$_i" "$_i" "$_m" "$_in" "$_cr" "$_cw" "$_o"
  done | cost_put "$_p"
}
cost_prints_no_number_under_95_percent_coverage() {
  bad=0
  # 95 of 100 rounds carry all four fields: 95.0 %, which is not under 95, so the table is printed
  w=$(mktemp -d); mkdir -p "$w/home" "$w/cfg/projects"
  cost_many "$w/cfg/projects" 100 0 inp out cr cw inp || return 1
  out=$(cost_tool "$w" 2>&1); rc=$?
  [ "$rc" = 0 ] || { echo "95 of 100 ended $rc: $out"; bad=1; }
  printf '%s\n' "$out" | head -1 | grep -q ' Coverage 95.0% ' || { echo "95 of 100 does not head with Coverage 95.0%: $(printf '%s\n' "$out" | head -1)"; bad=1; }
  # 94 of 100, and the one field missing exactly once is cache_read: exit 3 and no number
  w=$(mktemp -d); mkdir -p "$w/home" "$w/cfg/projects"
  cost_many "$w/cfg/projects" 100 0 inp inp out out cr cw || return 1
  out=$(cost_tool "$w" 2>&1); rc=$?
  cost_refused "$rc" "$out" 'Coverage' || bad=1
  return $bad
}
cost_prints_no_number_with_an_unknown_model_above_1_percent() {
  bad=0
  # 1 of 100 rounds with a model no price row names: 1.00 %, not above 1, so the table is printed with it
  w=$(mktemp -d); mkdir -p "$w/home" "$w/cfg/projects"
  cost_many "$w/cfg/projects" 99 1 || return 1
  out=$(cost_tool "$w" 2>&1); rc=$?
  [ "$rc" = 0 ] || { echo "1 of 100 unknown ended $rc: $out"; bad=1; }
  cost_expect "$out" 'manager/claude-zzz-9 1 - 0 0 0 1000' || bad=1
  # 1 of 99: 1.01 %, exit 3 and no number
  w=$(mktemp -d); mkdir -p "$w/home" "$w/cfg/projects"
  cost_many "$w/cfg/projects" 98 1 || return 1
  out=$(cost_tool "$w" 2>&1); rc=$?
  cost_refused "$rc" "$out" 'claude-zzz-9' || bad=1
  return $bad
}
cost_reads_the_transcripts_under_claude_config_dir() {
  w=$(mktemp -d); cost_world "$w" || return 1
  printf -- '-tmp-decoy/agent-x.jsonl|2026-10-10T12:00:00.000Z|d1|e1|claude-opus-5-5|0|0|0|0|0|100000|heim\n' |
    cost_put "$w/home/.claude/projects" || return 1
  bad=0
  out=$(cost_tool "$w" 2>&1) || { echo "set: exit $?: $out"; return 1; }
  cost_absent "$out" 'hand:heim/claude-opus-5-5' || bad=1
  [ -n "$(cost_row "$out" 'manager/claude-opus-5-5')" ] || { echo 'set: the fixture under CLAUDE_CONFIG_DIR was not read'; bad=1; }
  # unset and empty both fall back to HOME/.claude, here the decoy
  for how in unset empty; do
    if [ "$how" = unset ]; then
      out=$(env -u CLAUDE_CONFIG_DIR HOME="$w/home" bash "$ROOT/tools/mk-cost.sh" 2>&1) || { echo "$how: exit $?: $out"; return 1; }
    else
      out=$(HOME="$w/home" CLAUDE_CONFIG_DIR= bash "$ROOT/tools/mk-cost.sh" 2>&1) || { echo "$how: exit $?: $out"; return 1; }
    fi
    cost_expect "$out" 'hand:heim/claude-opus-5-5 1 2.00 0 0 0 100000' || bad=1
    cost_absent "$out" 'manager/claude-opus-5-5' || bad=1
  done
  return $bad
}
cost_heads_its_table() {
  cost_canon || return 1
  bad=0
  head=$(printf '%s\n' "$out" | sed -n '1,2p' | awk '{ $1 = $1; print }')
  # 8 files read in -tmp-proj-main (sess-1, sess-2, agent-a1, agent-b2, worker-c3, agent-d4, agent-zeta-f6,
  # agent-t5), 15 of 15 rounds with all four fields, the date of the prices, two folders excluded unread.
  want='mk-cost 2026-10-01..2026-10-15 Files 8 Coverage 100.0% Prices as of 2026-11-06 LOWER BOUND
Rounds without requestId 1, with an unknown model 0, hands without a type 1. Unreadable lines 1. Excluded folders 2.'
  [ "$head" = "$want" ] || { echo "the head is not the one expected:"; echo "  want: $want"; echo "  got:  $head"; bad=1; }
  printf '%s\n' "$out" | sed -n 3p | grep -q 'compaction call' ||
    { echo "the third line does not say what the meter cannot see: $(printf '%s\n' "$out" | sed -n 3p)"; bad=1; }
  return $bad
}
cost_prices_every_row_of_the_price_file() {
  # One round per model, 1M input, 2M write 5m, 3M write 1h, 4M read, 5M output, so every price of a row is
  # weighed differently: $ = in + 2 * w5 + 3 * w1 + 4 * read + 5 * out.
  #   opus-5-5   4 + 10 + 24 + 0.8 + 100 = 138.80     opus-5, opus-4-8  5 + 12.5 + 30 + 2 + 125 = 174.50
  #   sonnet-5-5 2 + 5 + 12 + 0.4 + 50 = 69.40         sonnet-5          2 + 5 + 12 + 0.8 + 50 = 69.80
  #   haiku-4-5  1 + 2.5 + 6 + 0.4 + 25 = 34.90
  #   haiku-5-5  10M input tokens, second tier: 0.5 + 1.25 + 3 + 0.2 + 12.5 = 17.45
  want='claude-opus-5-5 138.80
claude-opus-5 174.50
claude-opus-4-8 174.50
claude-sonnet-5-5 69.40
claude-sonnet-5 69.80
claude-haiku-4-5-20251001 34.90
claude-haiku-5-5 17.45'
  # THE MODELS OF THE PRICE FILE, derived from it: a row added there without a hand reckoning here is red.
  have=$(awk -F'\t' '!/^#/ && NF && $1 != "model" && $1 !~ />/ { print $1 }' "$ROOT/tools/prices.tsv" | sort)
  [ -n "$have" ] || { echo 'no model was read out of tools/prices.tsv'; return 1; }
  typed=$(printf '%s\n' "$want" | awk '{ print $1 }' | sort)
  [ "$have" = "$typed" ] || { echo "tools/prices.tsv names $(echo $have), the reckoning here $(echo $typed)"; return 1; }
  w=$(mktemp -d); mkdir -p "$w/home" "$w/cfg/projects"
  printf '%s\n' "$want" | while read -r m _; do
    printf -- '-tmp-prices/s.jsonl|2026-10-10T12:00:00.000Z|p-%s|p-%s|%s|1000000|4000000|5000000|2000000|3000000|5000000|-\n' "$m" "$m" "$m"
  done | cost_put "$w/cfg/projects" || return 1
  out=$(cost_tool "$w" 2>&1) || { echo "exit $?: $out"; return 1; }
  bad=0
  while read -r m d; do
    cost_expect "$out" "manager/$m 1 $d 4000000 2000000 3000000 5000000" || bad=1
  done <<EOT
$want
EOT
  return $bad
}
# cost_block: the bash block of commands/cost.md, with what the person typed after the command in place of
# $ARGUMENTS, as Claude Code puts it there.
cost_block() {
  python3 -I -c '
import re, sys
text = open(sys.argv[1], encoding="utf-8").read()
blocks = re.findall(r"```bash\n(.*?)```", text, re.S)
if len(blocks) != 1:
    sys.exit("expected exactly one bash block in %s, found %d" % (sys.argv[1], len(blocks)))
sys.stdout.write(blocks[0].replace("$ARGUMENTS", sys.argv[2]))' "$ROOT/commands/cost.md" "$1"
}
the_cost_command_runs_mk_cost() {
  [ -f "$ROOT/commands/cost.md" ] || { echo 'there is no commands/cost.md'; return 1; }
  cost_canon || return 1
  b=$(mktemp -d)
  cost_block '--since 2026-10-01 --until 2026-10-15 --exclude zETA --exclude OMEGA' > "$b/block.sh" || return 1
  # No installed copy may answer for the one under test: the PATH loses every plugin bin, CLAUDE_PLUGIN_ROOT
  # goes, and the configuration directory is the fixture, which holds no installed_plugins.json.
  path=$(printf '%s\n' "$PATH" | tr ':' '\n' | grep -v '/plugins/' | paste -sd: -)
  got=$(cd "$ROOT" && env -u CLAUDE_PLUGIN_ROOT PATH="$path" HOME="$w/home" CLAUDE_CONFIG_DIR="$w/cfg" bash "$b/block.sh" 2>&1)
  bad=0
  [ "$got" = "$out" ] || { echo "the command did not print what the tool prints:"; printf '%s\n' "$got" | head -3 | sed 's/^/  /'; bad=1; }
  # What the number is, said in the words the person reads: list price, no limit points, a lower bound.
  for word in "list price" "not limit points" "lower bound"; do
    grep -q "$word" "$ROOT/commands/cost.md" || { echo "commands/cost.md does not say $word"; bad=1; }
  done
  return $bad
}
the_cost_command_finds_the_kit_the_way_the_take_over_does() {
  python3 -I - "$ROOT" <<'PY'
import os, re, sys
root = sys.argv[1]
def part(rel):
    try:
        text = open(os.path.join(root, rel), encoding="utf-8").read()
    except OSError as exc:
        sys.exit("%s cannot be read: %s" % (rel, exc))
    blocks = re.findall(r"```bash\n(.*?)```", text, re.S)
    if len(blocks) != 1:
        sys.exit("expected exactly one bash block in %s, found %d" % (rel, len(blocks)))
    m = re.search(r"^MK=\$\(python3 -I - <<'PY'\n.*?^PY\n", blocks[0], re.S | re.M)
    if not m:
        sys.exit("no resolution of the kit in %s" % rel)
    return m.group(0)
take, cost = part("commands/take-over.md"), part("commands/cost.md")
if "mk-cost.sh" not in cost:
    sys.exit("the resolution in commands/cost.md does not look for tools/mk-cost.sh")
if cost.replace("mk-cost.sh", "manager-claim.sh") != take:
    a, b = take.split("\n"), cost.replace("mk-cost.sh", "manager-claim.sh").split("\n")
    first = next((i for i in range(min(len(a), len(b))) if a[i] != b[i]), min(len(a), len(b)))
    sys.exit("the resolution in commands/cost.md left the one in commands/take-over.md at its line %d:\n  take-over: %s\n  cost:      %s"
             % (first + 1, a[first] if first < len(a) else "(end)", b[first] if first < len(b) else "(end)"))
PY
}
# MK-R8, THE COMMANDS TAKE THE COPY THE REGISTER NAMES, WHATEVER THE PLUGIN IS CALLED. Both blocks skipped every entry of
# installed_plugins.json whose name was not typed in them, so a fork under another name had its own entry skipped and was
# left with CLAUDE_PLUGIN_ROOT, PATH and the working directory (README, "Limits measured and left open", until MK-R8). The
# blocks cannot ask the manifest for the name: they are looking for the copy that holds it. What names a copy of this kit
# is the script the block is sent for, and the loop below the register already asks for that, so the name is not asked.
# Same cut and same PATH as the check above, for both commands; the stubs say WHICH COPY RAN.
#   proj-K  the entry of this kit under its own name ($KITP), the shape that worked before
#   proj-R  an entry under another name; proj-O/sub  an entry of a plugin with no script, nearer to the cwd than the entry
#   for proj-O, which has one (the nearer one must not shadow it); proj-C  no entry at all
the_commands_find_the_installation_whatever_the_plugin_is_called() {
  w=$(mktemp -d); w=$(CDPATH= cd -- "$w" && pwd -P)
  bad=0
  command_block commands/take-over.md > "$w/take.sh" || return 1
  cost_block '' > "$w/cost.sh" || return 1
  for n in K R R2; do
    mkdir -p "$w/inst-$n/tools"
    for s in manager-claim.sh mk-cost.sh; do
      printf '#!/usr/bin/env bash\nprintf "ran %s\\n"\n' "$n" > "$w/inst-$n/tools/$s"
    done
  done
  mkdir -p "$w/inst-O/tools" "$w/proj-K" "$w/proj-R" "$w/proj-O/sub" "$w/proj-C" "$w/cfg/plugins"
  python3 -I - "$w" "$KITP" <<'PY' || return 1
import json, os, sys
w, kit = sys.argv[1], sys.argv[2]
def entry(proj, inst):
    return {"scope": "local", "projectPath": os.path.join(w, proj), "installPath": os.path.join(w, inst), "version": "1"}
reg = {"version": 2, "plugins": {
    "other-plugin@elsewhere": [entry("proj-O/sub", "inst-O")],
    "renamed-kit@elsewhere": [entry("proj-R", "inst-R"), entry("proj-O", "inst-R2")],
    kit + "@" + kit: [entry("proj-K", "inst-K")],
}}
with open(os.path.join(w, "cfg", "plugins", "installed_plugins.json"), "w") as fh:
    json.dump(reg, fh)
PY
  _py=$(command -v python3) || { echo 'no python3 on PATH'; return 1; }
  _pybin=$(dirname -- "$_py")
  for blk in take cost; do
    for pair in "proj-K|ran K" "proj-R|ran R" "proj-O/sub|ran R2" "proj-O|ran R2"; do
      got=$(cd "$w/${pair%%|*}" && env -u CLAUDE_PLUGIN_ROOT CLAUDE_CONFIG_DIR="$w/cfg" PATH="$_pybin:/usr/bin:/bin" bash "$w/$blk.sh" 2>&1)
      [ "$got" = "${pair#*|}" ] || { echo "$blk, standing in ${pair%%|*}: [$got], wanted [${pair#*|}]"; bad=1; }
    done
    got=$(cd "$w/proj-C" && env -u CLAUDE_PLUGIN_ROOT CLAUDE_CONFIG_DIR="$w/cfg" PATH="$_pybin:/usr/bin:/bin" bash "$w/$blk.sh" 2>&1)
    case $got in *'not reachable from this session'*) ;; *) echo "$blk, standing in a project of no entry: [$got]"; bad=1 ;; esac
  done
  return $bad
}
# MK-R8, THE COMMAND NAMES THE WORDS THE TOOL TAKES. --hands was added to tools/mk-cost.sh (MK-B3) and commands/cost.md
# went on listing three words, so a person who asks the command what it takes never hears of the fourth. The words are
# read out of the tool, from the line it prints for a word it does not know, and not typed here. The command says, in
# a sentence of its own, what --hands shows and where the plan comes from: the route line with the same tool_use_id.
the_cost_command_names_the_words_the_tool_takes() {
  w=$(mktemp -d); mkdir -p "$w/home" "$w/cfg" || return 1
  msg=$(cost_tool "$w" --nonesuch 2>&1); rc=$?
  [ "$rc" = 2 ] || { echo "the tool did not refuse a word it does not know, it ended $rc: $msg"; return 1; }
  words=$(printf '%s\n' "$msg" | sed -n 's/.*command (\(.*\)).*/\1/p' | tr ',' '\n' | awk 'NF { print $1 }')
  [ "$(printf '%s\n' "$words" | grep -c .)" -ge 4 ] || { echo "fewer than 4 words read out of the tool's own line: [$msg]"; return 1; }
  hint=$(grep '^argument-hint:' "$ROOT/commands/cost.md")
  body=$(awk '/^---$/ { n++; next } n >= 2' "$ROOT/commands/cost.md")
  bad=0
  for word in $words; do
    case $hint in *"[$word"*) ;; *) echo "the argument-hint of commands/cost.md does not name $word: $hint"; bad=1 ;; esac
  done
  case $body in *'`--hands`'*) ;; *) echo 'commands/cost.md says nothing of `--hands`'; bad=1 ;; esac
  case $body in *'`tool_use_id`'*) ;; *) echo 'commands/cost.md does not say that the plan comes from the route line with the same `tool_use_id`'; bad=1 ;; esac
  return $bad
}
cost_refuses_what_it_cannot_read() {
  w=$(mktemp -d); cost_world "$w" || return 1
  bad=0
  for args in '--sinc 2026-10-01' 'stray' '--since 2026-13-01' '--since 2026-10-1' '--until' '--exclude ' \
              '--since 2026-10-02 --until 2026-10-01'; do
    # shellcheck disable=SC2086
    if [ "$args" = '--exclude ' ]; then out=$(cost_tool "$w" --exclude '' 2>&1); rc=$?
    else out=$(cost_tool "$w" $args 2>&1); rc=$?; fi
    [ "$rc" = 2 ] || { echo "[$args] ended $rc, expected 2: $(printf '%s\n' "$out" | head -1)"; bad=1; continue; }
    [ "$(printf '%s\n' "$out" | grep -c .)" = 1 ] || { echo "[$args] said more than one line"; bad=1; }
    case $out in *"LOWER BOUND"*) echo "[$args] printed a table"; bad=1 ;; esac
  done
  return $bad
}
cost_prints_no_number_for_an_empty_window() {
  w=$(mktemp -d); cost_world "$w" || return 1
  out=$(cost_tool "$w" --since 2026-11-01 2>&1); rc=$?
  cost_refused "$rc" "$out" 'no round'
}

# MK-B3, PLANNED AGAINST RAN. tools/mk-cost.sh --hands puts each hand's route line (what the manager chose, matched by
# the tool_use_id the route hook writes) beside its transcript (what ran). The fixtures write transcripts, meta.json
# files and route lines by hand, in the shapes the runtime and the hook write them, under a mktemp directory, with HOME
# and CLAUDE_CONFIG_DIR pointing there in every call. The effort of a round is read from the top level key "effort" of
# its transcript line: Claude Code 2.1.318 scans its own transcripts for the bytes "effort":"max" beside
# "isSidechain":true and "attributionAgent":", which are top level keys [read from the program, not from a transcript].
#
# hands_put <projects dir>: one hand per line, "stem | agentType | toolUseId | cwd | model/effort ...". A toolUseId of
# "-" leaves it out of meta.json, an effort of "-" leaves it out of the round. Each model/effort is one answer of its own.
hands_put() {
  python3 -I -c '
import json, os, sys
root = sys.argv[1]
n = 0
for line in sys.stdin:
    line = line.strip()
    if not line or line.startswith("#"):
        continue
    stem, kind, tu, cwd, runs = [x.strip() for x in line.split("|")]
    d = os.path.join(root, "-p-proj", "sess-1", "subagents")
    os.makedirs(d, exist_ok=True)
    meta = {"agentType": kind, "finished": True}
    if tu != "-":
        meta["toolUseId"] = tu
    with open(os.path.join(d, stem + ".meta.json"), "w", encoding="utf-8") as fh:
        json.dump(meta, fh)
    with open(os.path.join(d, stem + ".jsonl"), "a", encoding="utf-8") as fh:
        for r in runs.split():
            n += 1
            model, effort = r.split("/")
            row = {"type": "assistant", "isSidechain": True, "timestamp": "2026-11-08T05:%02d:%02d.000Z" % (n // 60, n % 60),
                   "cwd": cwd, "requestId": "q%d" % n,
                   "message": {"id": "m%d" % n, "model": model, "role": "assistant",
                               "usage": {"input_tokens": 1, "output_tokens": 1, "cache_read_input_tokens": 0,
                                         "cache_creation_input_tokens": 0}}}
            if effort != "-":
                row["effort"] = effort
            fh.write(json.dumps(row) + "\n")
' "$1"
}
# hands_route <project root>: one route line per input line "subject | reason", in the record shape of mk_log_event.
hands_route() {
  mkdir -p "$1/.claude" || return 1
  python3 -I -c '
import json, sys
with open(sys.argv[1], "a", encoding="utf-8") as fh:
    for line in sys.stdin:
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        subject, reason = [x.strip() for x in line.split("|")]
        fh.write(json.dumps({"ts": "2026-11-08T05:43:40Z", "event": "route", "tool": "Agent",
                             "subject": subject, "reason": reason}) + "\n")
' "$1/.claude/manager-kit.log"
}
# hands_world <dir>: twelve hands of one session, a project under <dir>/proj with its log and a subdirectory, and a
# folder <dir>/kahl without a kit. Every route line carries the same timestamp and t1 and t2 the same subject, so only
# the tool_use_id tells them apart. The last route line is an older one, without the word, of a subject in use.
hands_world() {
  _hw=$(CDPATH= cd -- "$1" && pwd -P) || return 1
  P=$_hw/proj
  mkdir -p "$_hw/home" "$_hw/cfg/projects" "$P/sub/deep" "$_hw/kahl/src" || return 1
  _t=' from=call effort_from=call hand=own order=len:500,cmd:0,accept:0'
  hands_route "$P" <<EOS || return 1
${KITP}:medium | model=opus effort=high$_t tool_use_id=toolu_s1
${KITP}:medium | model=opus effort=high$_t tool_use_id=toolu_m1
${KITP}:low | model=sonnet effort=low$_t tool_use_id=toolu_g1
${KITP}:low | model=sonnet effort=low$_t tool_use_id=toolu_u1
${KITP}:low | model=opus effort=low$_t tool_use_id=toolu_t1
${KITP}:low | model=sonnet effort=low$_t tool_use_id=toolu_t2
${KITP}:high | model=sonnet effort=high$_t tool_use_id=toolu_e1
${KITP}:low | model=haiku effort=low$_t tool_use_id=toolu_h1
${KITP}:low | model=claude-haiku-4-5 effort=low$_t tool_use_id=toolu_v1
${KITP}:medium | model=(inherit) effort=medium from=none effort_from=call hand=own order=len:500,cmd:0,accept:0 tool_use_id=toolu_i1
${KITP}:low | model=haiku effort=max$_t
EOS
  hands_put "$_hw/cfg/projects" <<EOS
# s1, ROUTE opus, RAN sonnet: the criterion of the pyramid
agent-s1 | ${KITP}:medium | toolu_s1 | $P | claude-sonnet-5-5/high claude-sonnet-5-5/high
# m1, ROUTE opus, RAN opus 5.5 and then 4.8: a deviation of one round in three
agent-m1 | ${KITP}:medium | toolu_m1 | $P | claude-opus-5-5/high claude-opus-5-5/high claude-opus-4-8/high
# g1, ROUTE AND TRANSCRIPT AGREE
agent-g1 | ${KITP}:low | toolu_g1 | $P | claude-sonnet-5-5/low
# u1, THE SAME, from a subdirectory of the project
agent-u1 | ${KITP}:low | toolu_u1 | $P/sub/deep | claude-sonnet-5-5/low
# t1, t2, TWO CALLS OF ONE HAND at one second, each on the model its own line names
agent-t1 | ${KITP}:low | toolu_t1 | $P | claude-opus-5-5/low
agent-t2 | ${KITP}:low | toolu_t2 | $P | claude-sonnet-5-5/low
# e1, THE MODEL AGREES, THE EFFORT DOES NOT
agent-e1 | ${KITP}:high | toolu_e1 | $P | claude-sonnet-5-5/max
# h1, haiku IS THE NEWEST haiku of prices.tsv, 5-5, and not the dated 4-5: a deviation
agent-h1 | ${KITP}:low | toolu_h1 | $P | claude-haiku-4-5-20251001/low
# v1, A FULL ID IN THE ROUTE that ran as named, under the build date the runtime puts behind it
agent-v1 | ${KITP}:low | toolu_v1 | $P | claude-haiku-4-5-20251001/low
# i1, A ROUTE WITHOUT A MODEL: nothing to compare the model with, the effort agrees
agent-i1 | ${KITP}:medium | toolu_i1 | $P | claude-opus-5-5/medium
# n1, NO ROUTE LINE carries this id; k1, A FOLDER WITHOUT A KIT. Neither round names an effort.
agent-n1 | ${KITP}:medium | toolu_n1 | $P | claude-opus-5-5/-
agent-k1 | general-purpose | toolu_k1 | $_hw/kahl/src | claude-opus-5-5/-
EOS
}
# hands_canon: the hands world and the call, into $w and $out of the calling check, $w physical.
hands_canon() {
  w=$(mktemp -d); w=$(CDPATH= cd -- "$w" && pwd -P); hands_world "$w" || return 1
  out=$(cost_tool "$w" --hands 2>&1); _rc=$?
  [ "$_rc" = 0 ] || { echo "the call with --hands ended $_rc:"; printf '%s\n' "$out" | head -5; return 1; }
}
# hands_line <output> <first words>: the one line that starts with them, blanks squeezed, or empty.
hands_line() {
  printf '%s\n' "$1" | awk '{ $1 = $1; print }' | awk -v p="$2" 'index($0, p) == 1 { print; exit }'
}
hands_expect() {  # <output> <whole line, blanks squeezed>
  _hw_want=$2
  _hw_got=$(printf '%s\n' "$1" | awk '{ $1 = $1; print }' | grep -Fx -- "$_hw_want")
  [ -n "$_hw_got" ] && return 0
  echo "no line of the report is the one computed by hand:"; echo "  want: $_hw_want"
  _hw_near=$(hands_line "$1" "$(printf '%s' "$_hw_want" | cut -d' ' -f1-2)")
  echo "  near: ${_hw_near:-(no line starts like it)}"
  return 1
}
hands_absent() {  # <output> <first words>
  _hw_got=$(hands_line "$1" "$2")
  [ -z "$_hw_got" ] && return 0
  echo "this line must not be there: $_hw_got"; return 1
}

cost_hands_reports_a_hand_on_another_model() {
  hands_canon || return 1
  hands_expect "$out" "Deviation agent-s1 (${KITP}:medium): model planned opus = claude-opus-5-5, ran claude-sonnet-5-5 100%"
}
cost_hands_names_the_share_of_a_second_model() {
  hands_canon || return 1
  bad=0
  hands_expect "$out" "agent-m1 (${KITP}:medium) opus/high claude-opus-5-5 67%, claude-opus-4-8 33% / high 3" || bad=1
  hands_expect "$out" "Deviation agent-m1 (${KITP}:medium): model planned opus = claude-opus-5-5, ran claude-opus-4-8 33%" || bad=1
  return $bad
}
cost_hands_reports_no_deviation_where_route_and_transcript_agree() {
  hands_canon || return 1
  bad=0
  hands_expect "$out" "agent-g1 (${KITP}:low) sonnet/low claude-sonnet-5-5 / low 1" || bad=1
  hands_absent "$out" "Deviation agent-g1 " || bad=1
  return $bad
}
cost_hands_resolves_an_alias_to_the_newest_of_its_family() {
  hands_canon || return 1
  bad=0
  hands_expect "$out" "Deviation agent-h1 (${KITP}:low): model planned haiku = claude-haiku-5-5, ran claude-haiku-4-5-20251001 100%" || bad=1
  hands_expect "$out" "agent-v1 (${KITP}:low) claude-haiku-4-5/low claude-haiku-4-5-20251001 / low 1" || bad=1
  hands_absent "$out" "Deviation agent-v1 " || bad=1
  return $bad
}
cost_hands_counts_a_hand_without_a_route_openly() {
  hands_canon || return 1
  bad=0
  o=$(printf '%s\n' "$out" | sed "s#$w#W#g")
  hands_expect "$o" "without route agent-n1 (${KITP}:medium): no route line with tool_use_id toolu_n1 in the log over W/proj" || bad=1
  hands_expect "$o" "without route agent-k1 (general-purpose): no route line with tool_use_id toolu_k1 in the log over W/kahl/src" || bad=1
  case $(hands_line "$o" "mk-cost --hands") in *" without route 2 "*) ;; *) echo "the head does not count 2 hands without a route: $(hands_line "$o" "mk-cost --hands")"; bad=1 ;; esac
  return $bad
}
cost_hands_tells_two_calls_apart_by_tool_use_id() {
  hands_canon || return 1
  bad=0
  hands_expect "$out" "agent-t1 (${KITP}:low) opus/low claude-opus-5-5 / low 1" || bad=1
  hands_expect "$out" "agent-t2 (${KITP}:low) sonnet/low claude-sonnet-5-5 / low 1" || bad=1
  return $bad
}
cost_hands_finds_the_project_from_a_subdirectory() {
  hands_canon || return 1
  bad=0
  hands_expect "$out" "agent-u1 (${KITP}:low) sonnet/low claude-sonnet-5-5 / low 1" || bad=1
  hands_absent "$out" "without route agent-u1 " || bad=1
  return $bad
}
cost_hands_reports_an_effort_other_than_the_route() {
  hands_canon || return 1
  bad=0
  hands_expect "$out" "Deviation agent-e1 (${KITP}:high): effort planned high, ran max 100%" || bad=1
  hands_absent "$out" "Deviation agent-e1 (${KITP}:high): Modell" || bad=1
  return $bad
}
cost_hands_compares_no_model_for_a_route_without_one() {
  hands_canon || return 1
  bad=0
  hands_expect "$out" "not comparable agent-i1 (${KITP}:medium): the route names no model, model=(inherit)" || bad=1
  hands_absent "$out" "Deviation agent-i1 " || bad=1
  return $bad
}
cost_hands_prints_the_report_computed_by_hand() {
  hands_canon || return 1
  got=$(printf '%s\n' "$out" | sed "s#$w#W#g" | awk '{ $1 = $1; print }')
  # 12 hands, 10 with a route line, n1 and k1 without; i1 names no model; s1, m1, e1, h1 deviate. Rounds: m1 3,
  # s1 2, the other ten 1 each = 15; n1 and k1 carry no effort, so 13 with one. Rows by file name, then the
  # findings in the same order.
  want=$(sed "s/@K@/$KITP/g" <<'EOT'
mk-cost --hands *..* Hands 12 with route 10 without route 2 model not comparable 1 deviation 4
Rounds 15, of them with effort 13. Planned by the route line with the same tool_use_id, ran by the transcript, <synthetic> not counted.
Hand planned ran model / effort Rounds
agent-e1 (@K@:high) sonnet/high claude-sonnet-5-5 / max 1
agent-g1 (@K@:low) sonnet/low claude-sonnet-5-5 / low 1
agent-h1 (@K@:low) haiku/low claude-haiku-4-5-20251001 / low 1
agent-i1 (@K@:medium) (inherit)/medium claude-opus-5-5 / medium 1
agent-k1 (general-purpose) - claude-opus-5-5 / ? 1
agent-m1 (@K@:medium) opus/high claude-opus-5-5 67%, claude-opus-4-8 33% / high 3
agent-n1 (@K@:medium) - claude-opus-5-5 / ? 1
agent-s1 (@K@:medium) opus/high claude-sonnet-5-5 / high 2
agent-t1 (@K@:low) opus/low claude-opus-5-5 / low 1
agent-t2 (@K@:low) sonnet/low claude-sonnet-5-5 / low 1
agent-u1 (@K@:low) sonnet/low claude-sonnet-5-5 / low 1
agent-v1 (@K@:low) claude-haiku-4-5/low claude-haiku-4-5-20251001 / low 1
Deviation agent-e1 (@K@:high): effort planned high, ran max 100%
Deviation agent-h1 (@K@:low): model planned haiku = claude-haiku-5-5, ran claude-haiku-4-5-20251001 100%
not comparable agent-i1 (@K@:medium): the route names no model, model=(inherit)
without route agent-k1 (general-purpose): no route line with tool_use_id toolu_k1 in the log over W/kahl/src
Deviation agent-m1 (@K@:medium): model planned opus = claude-opus-5-5, ran claude-opus-4-8 33%
without route agent-n1 (@K@:medium): no route line with tool_use_id toolu_n1 in the log over W/proj
Deviation agent-s1 (@K@:medium): model planned opus = claude-opus-5-5, ran claude-sonnet-5-5 100%
EOT
)
  [ "$got" = "$want" ] && return 0
  echo "the report is not the one computed by hand:"
  diff <(printf '%s\n' "$want") <(printf '%s\n' "$got") | head -20
  return 1
}
# hands_ids <dir> <hands> <without id>: a world of <hands> hands that agree with their routes, the last <without id>
# of them with no toolUseId in meta.json.
hands_ids() {
  _hw=$(CDPATH= cd -- "$1" && pwd -P) || return 1
  mkdir -p "$_hw/home" "$_hw/cfg/projects" "$_hw/proj" || return 1
  _i=1
  while [ "$_i" -le "$2" ]; do
    printf '%s | model=sonnet effort=low from=call effort_from=call hand=own order=len:500,cmd:0,accept:0 tool_use_id=toolu_x%s\n' "${KITP}:low" "$_i"
    _i=$((_i + 1))
  done | hands_route "$_hw/proj" || return 1
  _i=1
  while [ "$_i" -le "$2" ]; do
    _tu=toolu_x$_i; [ "$_i" -le $(($2 - $3)) ] || _tu=-
    printf 'agent-x%02d | %s | %s | %s | claude-sonnet-5-5/low\n' "$_i" "${KITP}:low" "$_tu" "$_hw/proj"
    _i=$((_i + 1))
  done | hands_put "$_hw/cfg/projects"
}
cost_hands_prints_no_number_when_toolUseId_is_missing_above_5_percent() {
  w=$(mktemp -d); hands_ids "$w" 20 2 || return 1
  out=$(cost_tool "$w" --hands 2>&1); rc=$?
  cost_refused "$rc" "$out" 'toolUseId is missing in 10.0% of the meta.json files'
}
cost_hands_lists_a_hand_without_toolUseId_at_5_percent() {
  w=$(mktemp -d); hands_ids "$w" 20 1 || return 1
  out=$(cost_tool "$w" --hands 2>&1); rc=$?
  [ "$rc" = 0 ] || { echo "1 of 20 without toolUseId ended $rc, expected the report: $out"; return 1; }
  hands_expect "$out" "without route agent-x20 (${KITP}:low): meta.json names no toolUseId"
}
# route_tu_payload <cwd> <subagent_type> <tool_use_id as JSON, or absent> [model] -> a PreToolUse payload of the shape
# mkagent builds, with the tool_use_id under the control of the check.
route_tu_payload() {
  python3 -I -c '
import json, sys
ti = {"description": "one endpoint", "prompt": "finish it", "subagent_type": sys.argv[2]}
if len(sys.argv) > 4 and sys.argv[4]:
    ti["model"] = sys.argv[4]
d = {"cwd": sys.argv[1], "session_id": "S1", "agent_id": "", "hook_event_name": "PreToolUse",
     "tool_name": "Agent", "tool_input": ti}
if sys.argv[3] != "absent":
    d["tool_use_id"] = json.loads(sys.argv[3])
print(json.dumps(d))' "$@"
}
route_line_carries_the_tool_use_id() {
  d=$(newrepo)
  bad=0
  for pair in '"toolu_01PykMQC8fUj9qrfNVm4onH1"|tool_use_id=toolu_01PykMQC8fUj9qrfNVm4onH1' \
              '"a b=c model=opus"|tool_use_id=?' '7|tool_use_id=?' '{"x": 1}|tool_use_id=?'; do
    route_tu_payload "$d" "${KITP}:low" "${pair%%|*}" | ./hooks/route-guard.sh >/dev/null
    got=$(route_reason_logged "$d" "${KITP}:low")
    [ "${got##* }" = "${pair#*|}" ] || { echo "[${pair%%|*}]: the line ends [${got##* }], expected [${pair#*|}]: $got"; bad=1; }
  done
  return $bad
}
route_line_without_tool_use_id_is_written_as_before() {
  d=$(newrepo)
  bad=0
  route_tu_payload "$d" "${KITP}:low" '"toolu_a1"' | ./hooks/route-guard.sh >/dev/null
  with=$(route_reason_logged "$d" "${KITP}:low")
  [ "${with##* }" = tool_use_id=toolu_a1 ] || { echo "the call with an id does not end in its word: $with"; bad=1; }
  for v in absent null '""'; do
    route_tu_payload "$d" "${KITP}:low" "$v" | ./hooks/route-guard.sh >/dev/null
    got=$(route_reason_logged "$d" "${KITP}:low")
    [ "$got" = "${with% tool_use_id=toolu_a1}" ] || { echo "[$v]: the line is [$got], expected the line without its last word [${with% tool_use_id=toolu_a1}]"; bad=1; }
  done
  return $bad
}
cost_hands_reads_the_route_line_the_hook_writes() {
  w=$(mktemp -d); w=$(CDPATH= cd -- "$w" && pwd -P)
  d=$(newrepo)
  mkdir -p "$w/home" "$w/cfg/projects" || return 1
  route_tu_payload "$d" "${KITP}:low" '"toolu_01HookWrote"' sonnet | ./hooks/route-guard.sh >/dev/null
  printf 'agent-w1 | %s | toolu_01HookWrote | %s | claude-sonnet-5-5/-\n' "${KITP}:low" "$d/src" | hands_put "$w/cfg/projects"
  out=$(cost_tool "$w" --hands 2>&1); rc=$?
  [ "$rc" = 0 ] || { echo "ended $rc: $out"; return 1; }
  row=$(hands_line "$out" "agent-w1 ")
  case $row in "agent-w1 (${KITP}:low) sonnet/"*" claude-sonnet-5-5 / ? 1") ;; *)
    echo "the hand does not carry the route the hook wrote: [$row]"; echo "the line: $(tail -n 1 "$d/.claude/manager-kit.log")"; return 1 ;; esac
  hands_absent "$out" "without route agent-w1 "
}
# MK-R8, THE TYPE OF A HAND IN --hands IS THE TYPE THE TABLE GIVES IT. The hand of an SSH session has a meta.json with
# nothing in it but toolUseId, and its lines carry attributionAgent: the table typed it from the line, --hands from
# meta.json alone, so one hand was (unknown) in the report and ${KITP}:xhigh in the table [measured on real data by the
# coordinator, 2026-11-08]. The rule is the head of tools/mk-cost.sh: attributionAgent of the counted line, else agentType
# in meta.json, else unknown. The world is four hands in a folder called ssh-..., each on a model of its own, so that
# the table's row (hand:<type>/<model>) and the report's row (<hand> (<type>), the model in the column of what ran) can
# be set side by side without a name in common.
#   ssh1  meta.json: toolUseId only          lines: attributionAgent <kit>:xhigh     -> <kit>:xhigh
#   win2  meta.json: agentType max           lines: attributionAgent <kit>:high      -> <kit>:high  (the line first)
#   meta3 meta.json: agentType medium        lines: none                             -> medium      (meta.json still types)
#   none4 meta.json: toolUseId only          lines: none                             -> unknown
# With "mix" the world is one hand instead, whose two rounds carry two types: mix5 has agentType medium in meta.json, its
# first line none and its second attributionAgent <kit>:high. The table splits it by round, in two rows; the report names
# both types with their share, the way it names two models.
hands_typed_world() {
  python3 -I -c '
import json, os, sys
root, kit = sys.argv[1], sys.argv[2]
d = os.path.join(root, "cfg", "projects", "ssh-box-proj", "sess-1", "subagents")
os.makedirs(d, exist_ok=True)
os.makedirs(os.path.join(root, "home"), exist_ok=True)
n = 0
hands = (("agent-ssh1", {}, [kit + ":xhigh"] * 2, "claude-sonnet-5-5"),
         ("agent-win2", {"agentType": "max"}, [kit + ":high"], "claude-opus-5-5"),
         ("agent-meta3", {"agentType": "medium"}, [None], "claude-opus-4-8"),
         ("agent-none4", {}, [None], "claude-haiku-4-5-20251001"))
if sys.argv[3:] == ["mix"]:
    hands = (("agent-mix5", {"agentType": "medium"}, [None, kit + ":high"], "claude-opus-5"),)
for stem, meta, attrs, model in hands:
    meta = dict(meta, toolUseId="toolu_" + stem[6:], finished=True)
    with open(os.path.join(d, stem + ".meta.json"), "w", encoding="utf-8") as fh:
        json.dump(meta, fh)
    with open(os.path.join(d, stem + ".jsonl"), "w", encoding="utf-8") as fh:
        for attr in attrs:
            n += 1
            row = {"type": "assistant", "isSidechain": True, "timestamp": "2026-11-08T06:%02d:00.000Z" % n,
                   "cwd": "/srv/box/proj", "requestId": "q%d" % n,
                   "message": {"id": "m%d" % n, "model": model, "role": "assistant",
                               "usage": {"input_tokens": 1, "output_tokens": 1, "cache_read_input_tokens": 0,
                                         "cache_creation_input_tokens": 0}}}
            if attr:
                row["attributionAgent"] = attr
            fh.write(json.dumps(row) + "\n")
' "$1" "$KITP" ${2-}
}
cost_hands_types_a_hand_by_the_rule_of_the_table() {
  w=$(mktemp -d); w=$(CDPATH= cd -- "$w" && pwd -P)
  hands_typed_world "$w" || return 1
  rep=$(cost_tool "$w" --hands 2>&1) || { echo "--hands ended $?:"; printf '%s\n' "$rep" | head -5; return 1; }
  tab=$(cost_tool "$w" 2>&1) || { echo "the table ended $?:"; printf '%s\n' "$tab" | head -5; return 1; }
  bad=0
  # The four types, computed by hand from the fixture above.
  for want in "ssh1|${KITP}:xhigh" "win2|${KITP}:high" "meta3|medium" "none4|unknown"; do
    row=$(hands_line "$rep" "agent-${want%%|*} ")
    case $row in "agent-${want%%|*} (${want#*|}) "*) ;; *)
      echo "agent-${want%%|*} is not typed ${want#*|} in the report: [$row]"; bad=1 ;; esac
  done
  # And the one rule: the type the table gives the hand that ran on a model is the type the report gives it.
  from_table=$(printf '%s\n' "$tab" | awk '$1 ~ /^hand:/ { n = split($1, a, "/"); print a[n] "\t" substr($1, 6, length($1) - 6 - length(a[n])) }' | sort)
  from_report=$(printf '%s\n' "$rep" | awk '$1 ~ /^agent-/ { t = $2; gsub(/[()]/, "", t); print $4 "\t" t }' | sort)
  [ -n "$from_table" ] && [ "$from_table" = "$from_report" ] || {
    echo "the table and the report do not type the hands alike (model, type):"
    diff <(printf '%s\n' "$from_table") <(printf '%s\n' "$from_report") | head -10; bad=1; }
  # A hand with two types in its rounds: two rows in the table, both types and their share in the report.
  w2=$(mktemp -d); w2=$(CDPATH= cd -- "$w2" && pwd -P)
  hands_typed_world "$w2" mix || return 1
  rep=$(cost_tool "$w2" --hands 2>&1) || { echo "--hands ended $? on the hand with two types:"; printf '%s\n' "$rep" | head -5; return 1; }
  tab=$(cost_tool "$w2" 2>&1) || { echo "the table ended $? on the hand with two types:"; printf '%s\n' "$tab" | head -5; return 1; }
  row=$(hands_line "$rep" "agent-mix5 ")
  case $row in "agent-mix5 (${KITP}:high 50%, medium 50%) "*) ;; *)
    echo "the hand with two types is not named with both and their share: [$row]"; bad=1 ;; esac
  for lab in "hand:medium/claude-opus-5" "hand:${KITP}:high/claude-opus-5"; do
    [ -n "$(hands_line "$tab" "$lab ")" ] || { echo "the table has no row $lab for the hand with two types"; bad=1; }
  done
  return $bad
}

# MK-B4, THE COUNTER-RECKONING AND THE WINDOW COMPARISON. tools/mk-cost.sh --what-if prices every hand round of the
# table's rounds at the newest Opus of prices.tsv, with the same tokens, and sets that beside what ran. --compare A B
# sets the dollars per active day of two windows side by side and judges the difference only against an A/A band
# from the transcripts of the same machine. The pyramid of the council (2026-11-06) asks for them in this order,
# because only the first is free of noise. Fixtures only, HOME and CLAUDE_CONFIG_DIR in a mktemp directory in every
# call, the expected numbers computed by hand beside each fixture line, as for the table.
#
# whatif_world <dir>: one hand type per rule, so that a mutant of one rule moves one row. $/MTok as in cost_world.
whatif_world() {
  _p=$1/cfg/projects
  mkdir -p "$1/home" "$_p" || return 1
  cost_put "$_p" <<'EOS'
# THE MANAGER keeps its price: opus-5-5 0.1M out * 20 = 2.00, sonnet-5-5 0.1M out * 10 = 1.00 -> 3.00 on both sides
-w-proj/sess-1.jsonl|2026-10-10T10:00:00.000Z|wm1|wq1|claude-opus-5-5|0|0|0|0|0|100000|-
-w-proj/sess-1.jsonl|2026-10-10T10:01:00.000Z|wm2|wq2|claude-sonnet-5-5|0|0|0|0|0|100000|-
# sonett, SONNET 5.5 ONLY, every column once: 0.1M in * 2 = 0.20, 0.1M 5m * 2.5 = 0.25, 0.1M 1h * 4 = 0.40,
#   1M read * 0.1 = 0.10, 0.1M out * 10 = 1.00 -> 1.95; on opus-5-5 0.40 + 0.50 + 0.80 + 0.20 + 2.00 = 3.90
-w-proj/sess-1/subagents/agent-s1.jsonl|2026-10-10T10:02:00.000Z|ws1|wr1|claude-sonnet-5-5|100000|1000000|200000|100000|100000|100000|sonett
# a streamed answer counts by its last line: 0.1M out * 10 = 1.00, on opus 2.00 (by its first line 0.50 and 1.00)
-w-proj/sess-1/subagents/agent-s1.jsonl|2026-10-10T10:03:00.000Z|ws2|wr2|claude-sonnet-5-5|0|0|0|0|0|50000|sonett
-w-proj/sess-1/subagents/agent-s1.jsonl|2026-10-10T10:03:01.000Z|ws2|wr2|claude-sonnet-5-5|0|0|0|0|0|100000|sonett
# the same answer in two files counts once: 1.00, on opus 2.00. sonett: 3 rounds, 3.95, on opus 7.90, saved 3.95, 50.0%
-w-proj/sess-1/subagents/agent-s1.jsonl|2026-10-10T10:04:00.000Z|ws3|wr3|claude-sonnet-5-5|0|0|0|0|0|100000|sonett
-w-proj/sess-2/subagents/agent-s1.jsonl|2026-10-10T10:04:00.000Z|ws3|wr3|claude-sonnet-5-5|0|0|0|0|0|100000|sonett
# opus55, A HAND ON THE NEWEST OPUS: 0.1M out * 20 = 2.00 on both sides
-w-proj/sess-1/subagents/agent-o1.jsonl|2026-10-10T10:05:00.000Z|wo1|wr4|claude-opus-5-5|0|0|0|0|0|100000|opus55
# alt, A HAND ON AN OLDER OPUS keeps its price: opus-4-8 0.1M out * 25 = 2.50 on both sides (on opus-5-5 2.00)
-w-proj/sess-1/subagents/agent-a1.jsonl|2026-10-10T10:06:00.000Z|wa1|wr5|claude-opus-4-8|0|0|0|0|0|100000|alt
# haikuklein, HAIKU AT 100000 input tokens, its first tier: 0.1M in * 0.1 = 0.01, 1M out * 0.5 = 0.50 -> 0.51;
#   on opus 0.1M * 4 = 0.40, 1M * 20 = 20.00 -> 20.40, saved 19.89, 97.5%
-w-proj/sess-1/subagents/agent-k1.jsonl|2026-10-10T10:07:00.000Z|wk1|wr6|claude-haiku-5-5|100000|0|0|0|0|1000000|haikuklein
# haikugross, HAIKU ABOVE 100000, its second tier: 1M read * 0.05 = 0.05, 1M out * 2.5 = 2.50 -> 2.55; on opus by the
#   tier rule of opus, which has none: 1M * 0.2 = 0.20, 1M * 20 = 20.00 -> 20.20, saved 17.65, 87.4%
#   (scaled by the first tier of haiku, 40 times, it would be 102.00)
-w-proj/sess-1/subagents/agent-g1.jsonl|2026-10-10T10:08:00.000Z|wg1|wr7|claude-haiku-5-5|0|1000000|0|0|0|1000000|haikugross
# synth, <synthetic> WITH TOKENS stays out on both sides (on opus 0.1M in * 4 + 0.1M out * 20 = 2.40)
-w-proj/sess-1/subagents/agent-y1.jsonl|2026-10-10T10:09:00.000Z|wy1|wr8|<synthetic>|100000|0|0|0|0|100000|synth
# AFTER THE WINDOW: the checks ask --until 2026-10-10, so this round is in no row (1M out * 10 = 10.00, on opus 20.00)
-w-proj/sess-1/subagents/agent-s1.jsonl|2026-10-11T00:00:00.000Z|ws9|wr9|claude-sonnet-5-5|0|0|0|0|0|1000000|sonett
EOS
}
# whatif_canon: the world and --what-if on it within --until 2026-10-10 (a word that goes with it), into $w and $out.
whatif_canon() {
  w=$(mktemp -d); whatif_world "$w" || return 1
  out=$(cost_tool "$w" --what-if --until 2026-10-10 2>&1); _rc=$?
  [ "$_rc" = 0 ] || { echo "--what-if ended $_rc:"; printf '%s\n' "$out" | head -5; return 1; }
}
# wi_row <output> <label> -> the row of --what-if, one space between fields
wi_row() {
  printf '%s\n' "$1" | awk -v l="$2" '$1 == l { $1 = $1; print; exit }'
}
# wi_expect <output> "<label> <rounds> <ran> <all on opus> <saved> <saved %>"
wi_expect() {
  _want=$2; _lab=${_want%% *}
  _got=$(wi_row "$1" "$_lab")
  [ "$_got" = "$_want" ] && return 0
  echo "the row $_lab of --what-if is not the one computed by hand"; echo "  want: $_want"; echo "  got:  ${_got:-(no such row)}"
  return 1
}
# THE PREMISE OF THE ORDER, read out of prices.tsv and not typed: opus-5-5 costs one and the same multiple of
# sonnet-5-5 in every price column (2 on 2026-11-06), so a sonnet-5-5 hand round costs exactly that multiple on Opus.
# The expected row is reckoned here from the two rows of the file and the tokens of the sonett rounds above; if the
# columns stop being one multiple, this says so instead of testing something else.
cost_whatif_prices_sonnet_hand_rounds_at_the_opus_multiple() {
  whatif_canon || return 1
  want=$(python3 -I - "$ROOT/tools/prices.tsv" <<'PY'
import sys
rows = {}
for line in open(sys.argv[1], encoding="utf-8"):
    f = line.rstrip("\n").split("\t")
    if not line.startswith("#") and len(f) == 8:
        rows[f[0]] = [float(x) for x in f[1:6]] if f[0] != "model" else None
o, s = rows["claude-opus-5-5"], rows["claude-sonnet-5-5"]
k = set(a / b for a, b in zip(o, s))
if len(k) != 1:
    sys.exit("prices.tsv: claude-opus-5-5 is not one multiple of claude-sonnet-5-5 in every column: %s against %s" % (o, s))
k = k.pop()
# input, write 5m, write 1h, read, output of the three sonett rounds
toks = [(100000, 100000, 100000, 1000000, 100000), (0, 0, 0, 0, 100000), (0, 0, 0, 0, 100000)]
ran = sum(sum(t * p for t, p in zip(r, s)) for r in toks) / 1e6
alt = sum(sum(t * p for t, p in zip(r, o)) for r in toks) / 1e6
if "%.2f" % alt != "%.2f" % (k * ran):
    sys.exit("the reckoning itself is not %s times: %.2f against %.2f" % (k, alt, ran))
print("hand:sonett 3 %.2f %.2f %.2f %.1f" % (ran, alt, alt - ran, 100 * (alt - ran) / alt))
PY
) || { echo "$want"; return 1; }
  wi_expect "$out" "$want"
}
cost_whatif_keeps_opus_and_manager_rounds() {
  whatif_canon || return 1
  bad=0
  wi_expect "$out" 'hand:opus55 1 2.00 2.00 0.00 0.0' || bad=1
  wi_expect "$out" 'manager 2 3.00 3.00 0.00 0.0' || bad=1
  return $bad
}
cost_whatif_keeps_an_older_opus_at_its_own_price() {
  whatif_canon || return 1
  wi_expect "$out" 'hand:alt 1 2.50 2.50 0.00 0.0'
}
cost_whatif_prices_haiku_at_opus_on_the_same_tokens() {
  whatif_canon || return 1
  bad=0
  wi_expect "$out" 'hand:haikuklein 1 0.51 20.40 19.89 97.5' || bad=1
  wi_expect "$out" 'hand:haikugross 1 2.55 20.20 17.65 87.4' || bad=1
  return $bad
}
cost_whatif_leaves_synthetic_out() {
  whatif_canon || return 1
  bad=0
  [ -z "$(wi_row "$out" 'hand:synth')" ] || { echo "the synthetic round has a row: $(wi_row "$out" 'hand:synth')"; bad=1; }
  case $(printf '%s\n' "$out" | sed -n 2p) in *'Not counted: <synthetic> 1, no price 0.') ;; *)
    echo "line 2 does not count the synthetic round out: $(printf '%s\n' "$out" | sed -n 2p)"; bad=1 ;; esac
  wi_expect "$out" 'Total 9 14.51 56.00 41.49 74.1' || bad=1
  return $bad
}
# THE WHOLE REPORT, and the sum of what ran read against the table's sum on the same world: the same rounds by the same
# counting rule, the one number taken from the tool's own table and not typed.
cost_whatif_prints_the_report_computed_by_hand() {
  whatif_canon || return 1
  got=$(printf '%s\n' "$out" | awk '{ $1 = $1; print }')
  want='mk-cost --what-if *..2026-10-10 Files 8 Excluded folders 0 Coverage 100.0% Prices as of 2026-11-06 LOWER BOUND
What-if: every hand round on claude-opus-5-5, with the same tokens. A round on an Opus and every manager round keep their price. Not counted: <synthetic> 1, no price 0.
Assumption: the same tokens. Sonnet thinks longer, so the saving is an upper bound. List price in dollars, not limit points.
Role Rounds ran all-Opus saving %
hand:alt 1 2.50 2.50 0.00 0.0
hand:haikugross 1 2.55 20.20 17.65 87.4
hand:haikuklein 1 0.51 20.40 19.89 97.5
hand:opus55 1 2.00 2.00 0.00 0.0
hand:sonett 3 3.95 7.90 3.95 50.0
Hands 7 11.51 53.00 41.49 78.3
manager 2 3.00 3.00 0.00 0.0
Total 9 14.51 56.00 41.49 74.1'
  [ "$got" = "$want" ] || { echo "the report is not the one computed by hand:"; diff <(printf '%s\n' "$want") <(printf '%s\n' "$got") | head -24; return 1; }
  tab=$(cost_tool "$w" --until 2026-10-10 2>&1) || { echo "the table ended $? on the same world"; return 1; }
  ts=$(printf '%s\n' "$tab" | awk '$1 == "Total" { print $3 }')
  ws=$(printf '%s\n' "$out" | awk '$1 == "Total" { print $3 }')
  [ -n "$ts" ] && [ "$ts" = "$ws" ] || { echo "what ran in --what-if ($ws) is not the sum of the table ($ts)"; return 1; }
}
# compare_world <dir> <variant>: one manager round a day on opus-5-5, 0.05M output tokens to a dollar (0.05M * 20).
# A is 2026-09-17..2026-09-19, B is 2026-09-21..2026-09-22, and the pairs are 2+0+2 active days, so the band stands on
# the 4 * 4 = 16 active days right before A, in 13 pairs.
#   2026-08-31  40   a wild day, the 17th active day before A: outside the band (in it, the band is -88.4% .. +760.0%)
#   2026-09-01  3, 09-02 3, 09-03..09-16 2 each: the 16 days of the band. The largest change among its pairs is
#               3,3 -> 2,2, a factor of 1.5 either way, so the band is -33.3% .. +50.0%
#   2026-09-17  3, 09-18 3, 09-19 a round of 0 dollars: A, 2 active days, 3.00 a day
#   B: base 3,3 (3.00 a day, no change); edge 2,2 (2.00, exactly the factor of the band's largest pair); double 6,6
#      (6.00, factor 2 against base); with A and B in the band, double would stand on its own pair and be inside
#   2026-09-25  40   after B: --compare reads up to the end of B and no further
# A DECOY FOLDER, -c-weg, puts 100 dollars on each day of B; compare_canon excludes it with --exclude WEG (a word that
# goes with --compare), so it is in no number, and the head counts 1 folder excluded.
# short leaves out 08-31 and 09-01, 15 active days before A. gap puts 2 dollars on 2026-09-20, an active day between A
# and B, so the pairs are 2+1+2 days and the band needs 20.
compare_world() {
  _p=$1/cfg/projects; _v=$2
  mkdir -p "$1/home" "$_p" || return 1
  {
    [ "$_v" = short ] || printf '2026-08-31 40\n2026-09-01 3\n'
    printf '2026-09-02 3\n'
    for _d in 03 04 05 06 07 08 09 10 11 12 13 14 15 16; do printf '2026-09-%s 2\n' "$_d"; done
    printf '2026-09-17 3\n2026-09-18 3\n2026-09-19 0\n'
    if [ "$_v" = gap ]; then printf '2026-09-20 2\n'; fi
    case $_v in
      edge) printf '2026-09-21 2\n2026-09-22 2\n' ;;
      double) printf '2026-09-21 6\n2026-09-22 6\n' ;;
      *) printf '2026-09-21 3\n2026-09-22 3\n' ;;
    esac
    printf '2026-09-25 40\n'
  } | awk '{ printf "-c-proj/sess-1.jsonl|%sT12:00:00.000Z|c%d|d%d|claude-opus-5-5|0|0|0|0|0|%d|-\n", $1, NR, NR, $2 * 50000 }' |
    cost_put "$_p" || return 1
  printf -- '-c-weg/sess-9.jsonl|2026-09-2%sT13:00:00.000Z|x%s|y%s|claude-opus-5-5|0|0|0|0|0|5000000|-\n' 1 1 1 2 2 2 |
    cost_put "$_p"
}
CMP_A=2026-09-17..2026-09-19
CMP_B=2026-09-21..2026-09-22
# compare_canon <variant>: the world and the comparison of A and B, into $w, $out and $_rc of the calling check.
compare_canon() {
  w=$(mktemp -d); compare_world "$w" "$1" || return 1
  out=$(cost_tool "$w" --compare "$CMP_A" "$CMP_B" --exclude WEG 2>&1); _rc=$?
}
# THE CRITERION OF THE PYRAMID, ITS FIRST HALF: no intervention, no verdict of a change. And ON THE EDGE, inclusive: a
# change as large as the largest pair of the band is a change that happened without an intervention. Inside the band
# the report prints no percentage but the band's own: the change is not offered as a saving.
cost_compare_prints_not_distinguishable_without_an_intervention() {
  compare_canon base || return 1
  [ "$_rc" = 0 ] || { echo "--compare ended $_rc:"; printf '%s\n' "$out" | head -5; return 1; }
  got=$(printf '%s\n' "$out" | awk '{ $1 = $1; print }')
  want='mk-cost --compare A 2026-09-17..2026-09-19 B 2026-09-21..2026-09-22 Files 1 Excluded folders 1 Dollars per active day Prices as of 2026-11-06 LOWER BOUND
A 2 active days, 3.00 $ per day. B 2 active days, 3.00 $ per day. Between them 0 active days. A UTC day is active with more than 0 dollars.
Band without intervention -33.3% to +50.0%: the largest change among 13 pairs of 2+0+2 active days, on the 16 active days before A, 2026-09-01..2026-09-16.
Verdict: not distinguishable.'
  [ "$got" = "$want" ] || { echo "the report is not the one computed by hand:"; diff <(printf '%s\n' "$want") <(printf '%s\n' "$got") | head -12; return 1; }
  compare_canon edge || return 1
  [ "$_rc" = 0 ] || { echo "--compare on the edge ended $_rc:"; printf '%s\n' "$out" | head -5; return 1; }
  last=$(printf '%s\n' "$out" | tail -n 1)
  [ "$last" = 'Verdict: not distinguishable.' ] || { echo "a change as large as the band's largest pair is judged outside it: $last"; return 1; }
  [ "$(printf '%s\n' "$out" | grep -c '%')" = 1 ] || { echo "inside the band a line other than the band carries a percentage:"; printf '%s\n' "$out" | grep '%'; return 1; }
}
# ITS SECOND HALF: factor 2 in B, against a band of -33.3% .. +50.0% from the 16 days before A. The wild day before
# them and the days of A and B stay out of the band, or the band would swallow the change.
cost_compare_prints_the_change_beside_the_band_for_factor_2() {
  compare_canon double || return 1
  [ "$_rc" = 0 ] || { echo "--compare ended $_rc:"; printf '%s\n' "$out" | head -5; return 1; }
  got=$(printf '%s\n' "$out" | awk '{ $1 = $1; print }')
  want='mk-cost --compare A 2026-09-17..2026-09-19 B 2026-09-21..2026-09-22 Files 1 Excluded folders 1 Dollars per active day Prices as of 2026-11-06 LOWER BOUND
A 2 active days, 3.00 $ per day. B 2 active days, 6.00 $ per day. Between them 0 active days. A UTC day is active with more than 0 dollars.
Band without intervention -33.3% to +50.0%: the largest change among 13 pairs of 2+0+2 active days, on the 16 active days before A, 2026-09-01..2026-09-16.
Verdict: change +100.0% from A to B, outside the band -33.3% to +50.0%.'
  [ "$got" = "$want" ] || { echo "the report is not the one computed by hand:"; diff <(printf '%s\n' "$want") <(printf '%s\n' "$got") | head -12; return 1; }
}
# NO BAND, NO VERDICT: 15 active days where 16 are needed; an active day between A and B that makes the pairs 2+1+2
# and the need 20; a window without an active day. One line of reason each, exit 3, as the format guard.
cost_compare_gives_no_verdict_on_a_short_history() {
  bad=0
  compare_canon short || return 1
  cost_refused "$_rc" "$out" 'of 2+0+2 active days, so 16 active days before A; there are 15, 2026-09-02..2026-09-16.' || bad=1
  compare_canon gap || return 1
  cost_refused "$_rc" "$out" 'of 2+1+2 active days, so 20 active days before A; there are 17, 2026-08-31..2026-09-16.' || bad=1
  out=$(cost_tool "$w" --compare "$CMP_A" 2026-09-23..2026-09-24 2>&1); _rc=$?
  cost_refused "$_rc" "$out" 'B 2026-09-23..2026-09-24 has no active day.' || bad=1
  return $bad
}
cost_compare_counts_a_day_active_only_when_it_costs_more_than_nothing() {
  compare_canon base || return 1
  line=$(printf '%s\n' "$out" | sed -n 2p)
  case $line in 'A 2 active days, 3.00 $ per day. '*) ;; *) echo "the day of 0 dollars in A is counted as active: $line"; return 1 ;; esac
}
# EACH REFUSAL FOR ITS OWN REASON, the fragment after the bar: exit 2 and one line alone is also what a tool says that
# does not know the word at all (3812c8e said it for every line here, and this check was green against it).
cost_refuses_a_window_or_a_mix_it_does_not_support() {
  w=$(mktemp -d); compare_world "$w" base || return 1
  bad=0
  while IFS='|' read -r args why; do
    [ -n "$args" ] || continue
    # shellcheck disable=SC2086
    out=$(cost_tool "$w" $args 2>&1); rc=$?
    [ "$rc" = 2 ] || { echo "[$args] ended $rc, expected 2: $(printf '%s\n' "$out" | head -1)"; bad=1; continue; }
    [ "$(printf '%s\n' "$out" | grep -c .)" = 1 ] || { echo "[$args] said more than one line"; bad=1; }
    case $out in *"LOWER BOUND"*|*Verdict*) echo "[$args] printed a report"; bad=1 ;; esac
    case $out in *"$why"*) ;; *) echo "[$args] is not refused for its reason ($why): $out"; bad=1 ;; esac
  done <<EOS
--compare|--compare needs two windows
--compare $CMP_A|--compare needs two windows
--compare 2026-09-17 $CMP_B|--compare 2026-09-17 is no window of the form
--compare 2026-09-19..2026-09-17 $CMP_B|closes before it opens
--compare 2026-09-17..2026-09-31 $CMP_B|--compare 2026-09-31 is no day of the form
--compare $CMP_B $CMP_A|does not end before B
--compare 2026-09-17..2026-09-21 $CMP_B|does not end before B
--compare $CMP_A $CMP_B --since 2026-09-01|--since and --until do not go with it
--compare $CMP_A $CMP_B --until 2026-09-30|--since and --until do not go with it
--compare $CMP_A $CMP_B --hands|--hands and --compare do not go together
--compare $CMP_A $CMP_B --what-if|--what-if and --compare do not go together
--what-if --hands|--hands and --what-if do not go together
EOS
  return $bad
}
# THE SAME INPUT, THE SAME BYTES: five runs of each report on one world, each a report and not a refusal.
cost_whatif_and_compare_print_the_same_bytes_twice() {
  w=$(mktemp -d); whatif_world "$w" || return 1
  v=$(mktemp -d); compare_world "$v" double || return 1
  bad=0
  for run in 1 2 3 4 5; do
    cost_tool "$w" --what-if > "$w/out.$run" 2>&1
    cost_tool "$v" --compare "$CMP_A" "$CMP_B" > "$v/out.$run" 2>&1
  done
  case $(head -n 1 "$w/out.1") in 'mk-cost --what-if '*) ;; *) echo "--what-if printed no report: $(head -n 1 "$w/out.1")"; return 1 ;; esac
  case $(head -n 1 "$v/out.1") in 'mk-cost --compare '*) ;; *) echo "--compare printed no report: $(head -n 1 "$v/out.1")"; return 1 ;; esac
  for run in 2 3 4 5; do
    cmp -s "$w/out.1" "$w/out.$run" || { echo "--what-if run $run differs from run 1:"; diff "$w/out.1" "$w/out.$run" | head -6; bad=1; }
    cmp -s "$v/out.1" "$v/out.$run" || { echo "--compare run $run differs from run 1:"; diff "$v/out.1" "$v/out.$run" | head -6; bad=1; }
  done
  return $bad
}
# THE DOCUMENTS NAME THE WORDS THE TOOL TAKES, read out of the tool's own line for a word it does not know, as the check
# of the command does (MK-R8): README and GUIDE each name every word. The command's own text is asked by name for the two
# words that print a report of their own here, because it tells the reader how to pass each one on.
cost_docs_name_every_word_the_tool_takes() {
  w=$(mktemp -d); mkdir -p "$w/home" "$w/cfg" || return 1
  msg=$(cost_tool "$w" --nonesuch 2>&1)
  words=$(printf '%s\n' "$msg" | sed -n 's/.*command (\(.*\)).*/\1/p' | tr ',' '\n' | awk 'NF { print $1 }')
  [ "$(printf '%s\n' "$words" | grep -c .)" -ge 4 ] || { echo "fewer than 4 words read out of the tool's own line: [$msg]"; return 1; }
  bad=0
  for f in README.md GUIDE.md; do
    for word in $words; do
      grep -qF -e "\`$word" "$ROOT/$f" || { echo "$f does not name $word"; bad=1; }
    done
  done
  body=$(awk '/^---$/ { n++; next } n >= 2' "$ROOT/commands/cost.md")
  for word in --what-if --compare --causes; do
    case $body in *"\`$word"*) ;; *) echo "commands/cost.md says nothing of \`$word\`"; bad=1 ;; esac
  done
  case $body in *'not distinguishable'*) ;; *) echo 'commands/cost.md does not say what "not distinguishable" means'; bad=1 ;; esac
  return $bad
}

# ------------------------------------------------------------------ the causes of cache writing (MK-B2a)
# mk-cost --causes gives every counted round that writes cache exactly one cause. THE EXPECTED NUMBERS ARE COMPUTED BY
# HAND from the fixture lines and tools/prices.tsv: main session files run claude-opus-5-5, which writes 5m at 5 and 1h
# at 8 $/MTok, hand files claude-sonnet-5-5, 2.5 and 4. A write costs tokens * price / 1e6. A row is asserted as
# "<role>/<cause> rounds tokens dollars tokens-per-event dollars-per-event", without its % column, which moves with the
# total of every other round; the % is asserted by the whole report. The compaction line, MARK in cost_put, is the
# shape Claude Code 2.1.318 writes, read out of its binary on 2026-11-08 and not out of any transcript.
causes_world() {
  _p=$1/cfg/projects
  mkdir -p "$1/home" "$_p" || return 1
  case $2 in
    start) cost_put "$_p" <<'EOS' ;;
# s1, THE FIRST ROUND OF A HAND FILE: 28000 * 2.5 = 0.07. s2 a minute later is no start: Growth, 4000 * 2.5 = 0.01.
# s3, THE FIRST ROUND OF A MAIN FILE, 1h: 10000 * 8 = 0.08.
-tmp-p/agent-s.jsonl|2026-10-10T10:00:00.000Z|s1|q1|claude-sonnet-5-5|0|0|28000|28000|0|0|low
-tmp-p/agent-s.jsonl|2026-10-10T10:01:00.000Z|s2|q2|claude-sonnet-5-5|0|28000|4000|4000|0|0|low
-tmp-p/sess.jsonl|2026-10-10T10:00:00.000Z|s3|q3|claude-opus-5-5|0|0|10000|0|10000|0|-
EOS
    growth) cost_put "$_p" <<'EOS' ;;
# z2, 4 MINUTES AFTER A 5m WRITE: 4000 * 2.5 = 0.01. z4, 30 MINUTES AFTER A 1h WRITE, still within its TTL, where a
# fixed bound of 5m would call it expired: 2500 * 8 = 0.02.
-tmp-p/agent-z.jsonl|2026-10-10T10:00:00.000Z|z1|q1|claude-sonnet-5-5|0|0|28000|28000|0|0|low
-tmp-p/agent-z.jsonl|2026-10-10T10:04:00.000Z|z2|q2|claude-sonnet-5-5|0|28000|4000|4000|0|0|low
-tmp-p/sess.jsonl|2026-10-10T10:00:00.000Z|z3|q3|claude-opus-5-5|0|0|10000|0|10000|0|-
-tmp-p/sess.jsonl|2026-10-10T10:30:00.000Z|z4|q4|claude-opus-5-5|0|10000|2500|0|2500|0|-
EOS
    expired) cost_put "$_p" <<'EOS' ;;
# a2, 10 MINUTES AFTER A 5m WRITE: 176000 * 2.5 = 0.44. a4, 10 minutes after a 1h write, is no expiry.
-tmp-p/agent-a.jsonl|2026-10-10T10:00:00.000Z|a1|q1|claude-sonnet-5-5|0|0|28000|28000|0|0|low
-tmp-p/agent-a.jsonl|2026-10-10T10:10:00.000Z|a2|q2|claude-sonnet-5-5|0|0|176000|176000|0|0|low
-tmp-p/sess.jsonl|2026-10-10T10:00:00.000Z|a3|q3|claude-opus-5-5|0|0|10000|0|10000|0|-
-tmp-p/sess.jsonl|2026-10-10T10:10:00.000Z|a4|q4|claude-opus-5-5|0|10000|2500|0|2500|0|-
EOS
    idle) cost_put "$_p" <<'EOS' ;;
# l2, 2 HOURS AFTER A 1h WRITE: 318000 * 8 = 2.544. l3, 30 minutes after l2, is Growth. l5, 2 hours after a 5m
# write, is an expired 5m cache and no idle: 28000 * 2.5 = 0.07.
-tmp-p/sess.jsonl|2026-10-10T10:00:00.000Z|l1|q1|claude-opus-5-5|0|0|10000|0|10000|0|-
-tmp-p/sess.jsonl|2026-10-10T12:00:00.000Z|l2|q2|claude-opus-5-5|0|0|318000|0|318000|0|-
-tmp-p/sess.jsonl|2026-10-10T12:30:00.000Z|l3|q3|claude-opus-5-5|0|318000|2500|0|2500|0|-
-tmp-p/agent-l.jsonl|2026-10-10T10:00:00.000Z|l4|q4|claude-sonnet-5-5|0|0|28000|28000|0|0|low
-tmp-p/agent-l.jsonl|2026-10-10T12:00:00.000Z|l5|q5|claude-sonnet-5-5|0|0|28000|28000|0|0|low
EOS
    compaction) cost_put "$_p" <<'EOS' ;;
# k2, THE FIRST ROUND AFTER A COMPACTION LINE, a minute after it: 74000 * 8 = 0.592. k3 after k2 is Growth, 0.008.
# k9 between them is <synthetic>, no call, and does not take the compaction from k2.
-tmp-p/sess.jsonl|2026-10-10T10:00:00.000Z|k1|q1|claude-opus-5-5|0|0|10000|0|10000|0|-
MARK|-tmp-p/sess.jsonl|2026-10-10T10:30:00.000Z|u-k|auto|150000
-tmp-p/sess.jsonl|2026-10-10T10:30:30.000Z|k9|q9|<synthetic>|0|0|0|0|0|0|-
-tmp-p/sess.jsonl|2026-10-10T10:31:00.000Z|k2|q2|claude-opus-5-5|0|0|74000|0|74000|0|-
-tmp-p/sess.jsonl|2026-10-10T10:32:00.000Z|k3|q3|claude-opus-5-5|0|74000|1000|0|1000|0|-
EOS
    rest) cost_put "$_p" <<'EOS' ;;
# r2 WRITES AFTER A ROUND THAT WROTE NOTHING, and nothing in the file wrote before: no TTL, Other, 8000 * 5 = 0.04.
# r4 writes 10 minutes after r3, which wrote nothing either, but r2 before it wrote 5m: the TTL of the last write
# holds, so r4 is expired and no Other, 4000 * 5 = 0.02.
-tmp-p/sess.jsonl|2026-10-10T10:00:00.000Z|r1|q1|claude-opus-5-5|0|1000000|0|0|0|0|-
-tmp-p/sess.jsonl|2026-10-10T10:01:00.000Z|r2|q2|claude-opus-5-5|0|1000000|8000|8000|0|0|-
-tmp-p/sess.jsonl|2026-10-10T10:02:00.000Z|r3|q3|claude-opus-5-5|0|1008000|0|0|0|0|-
-tmp-p/sess.jsonl|2026-10-10T10:12:00.000Z|r4|q4|claude-opus-5-5|0|1000000|4000|4000|0|0|-
EOS
    grenze5m) cost_put "$_p" <<'EOS' ;;
# THE 5m BOUND: g2 exactly 300.000 s after g1 and g3 299.999 s after g2 are within, g4 300.001 s after g3 is past it.
# 4000 * 2.5 = 0.01 each.
-tmp-p/agent-g.jsonl|2026-10-10T10:00:00.000Z|g1|q1|claude-sonnet-5-5|0|0|1000|1000|0|0|low
-tmp-p/agent-g.jsonl|2026-10-10T10:05:00.000Z|g2|q2|claude-sonnet-5-5|0|1000|4000|4000|0|0|low
-tmp-p/agent-g.jsonl|2026-10-10T10:09:59.999Z|g3|q3|claude-sonnet-5-5|0|5000|4000|4000|0|0|low
-tmp-p/agent-g.jsonl|2026-10-10T10:15:00.000Z|g4|q4|claude-sonnet-5-5|0|0|4000|4000|0|0|low
EOS
    grenze1h) cost_put "$_p" <<'EOS' ;;
# THE 1h BOUND: h2 exactly 3600.000 s after h1 and h3 3599.999 s after h2 are within, h4 3600.001 s after h3 is past
# it. 2500 * 8 = 0.02 each.
-tmp-p/sess.jsonl|2026-10-10T10:00:00.000Z|h1|q1|claude-opus-5-5|0|0|1000|0|1000|0|-
-tmp-p/sess.jsonl|2026-10-10T11:00:00.000Z|h2|q2|claude-opus-5-5|0|1000|2500|0|2500|0|-
-tmp-p/sess.jsonl|2026-10-10T11:59:59.999Z|h3|q3|claude-opus-5-5|0|3500|2500|0|2500|0|-
-tmp-p/sess.jsonl|2026-10-10T13:00:00.000Z|h4|q4|claude-opus-5-5|0|0|2500|0|2500|0|-
EOS
    zugleich) cost_put "$_p" <<'EOS' ;;
# x1, y1, z1 EACH WRITE 5m AND 1h IN ONE ROUND: one cause, Start, 10000 * 5 + 10000 * 8 = 0.13 each. After such a
# round the 5m part expires first and the 1h part last: x2 a minute later is Growth, 2000 * 5 = 0.01; y2 ten minutes
# later is expired, 6000 * 5 = 0.03; z2 two hours later is idle, 10000 * 8 = 0.08.
-tmp-p/sess-a.jsonl|2026-10-10T10:00:00.000Z|x1|q1|claude-opus-5-5|0|0|20000|10000|10000|0|-
-tmp-p/sess-a.jsonl|2026-10-10T10:01:00.000Z|x2|q2|claude-opus-5-5|0|20000|2000|2000|0|0|-
-tmp-p/sess-b.jsonl|2026-10-10T10:00:00.000Z|y1|q3|claude-opus-5-5|0|0|20000|10000|10000|0|-
-tmp-p/sess-b.jsonl|2026-10-10T10:10:00.000Z|y2|q4|claude-opus-5-5|0|10000|6000|6000|0|0|-
-tmp-p/sess-c.jsonl|2026-10-10T10:00:00.000Z|z1|q5|claude-opus-5-5|0|0|20000|10000|10000|0|-
-tmp-p/sess-c.jsonl|2026-10-10T12:00:00.000Z|z2|q6|claude-opus-5-5|0|0|10000|0|10000|0|-
EOS
    zweidateien) cost_put "$_p" <<'EOS' ;;
# A RESUMED SESSION COPIES the compaction line u-1 and the round k2 after it into sess-b: one compaction and one round.
# u-2 in sess-b is a second compaction. k2 74000 * 8 = 0.592, k3 20000 * 8 = 0.16, together 0.752, 0.376 each.
# Context before, preTokens: 150000 and 100000, median 125000. After, input + read + write of the first round after:
# k2 74000, k3 6000 + 20000 = 26000, median 50000.
