# causes_run <world> [args]: the world into $w and its report with --causes into $out of the calling check.
causes_run() {
  _k=$1; shift
  w=$(mktemp -d); causes_world "$w" "$_k" || return 1
  out=$(cost_tool "$w" --causes "$@" 2>&1); _rc=$?
  [ "$_rc" = 0 ] || { echo "--causes on $_k ended $_rc:"; printf '%s\n' "$out" | head -5; return 1; }
}
# causes_expect <output> "<role>/<cause> <rounds> <tokens> <$> <tokens per event> <$ per event>", the % column left out
causes_expect() {
  _want=$2; _lab=${_want%% *}
  _got=$(printf '%s\n' "$1" | awk -v l="$_lab" '$1 == l { $5 = ""; $0 = $0; $1 = $1; print; exit }')
  [ "$_got" = "$_want" ] && return 0
  echo "the row $_lab is not the one computed by hand"; echo "  want: $_want"; echo "  got:  ${_got:-(no such row)}"
  return 1
}
