}
# context_run <world> <exit> [args]: the world into $w, its report with --context into $out of the calling check, which
# ends with <exit>.
context_run() {
  _k=$1; _want=$2; shift 2
  w=$(mktemp -d); context_world "$w" "$_k" || return 1
  out=$(cost_tool "$w" --context "$@" 2>&1); _rc=$?
  [ "$_rc" = "$_want" ] || { echo "--context on $_k ended $_rc, expected $_want:"; printf '%s\n' "$out" | head -5; return 1; }
}
# context_expect <output> "<first field> <rest>": the line that starts with that field, blanks squeezed.
context_expect() {
  _want=$2; _lab=${_want%% *}
  _got=$(printf '%s\n' "$1" | awk -v l="$_lab" '$1 == l { $1 = $1; print; exit }')
  [ "$_got" = "$_want" ] && return 0
  echo "the line $_lab is not the one computed by hand"; echo "  want: $_want"; echo "  got:  ${_got:-(no such line)}"
  return 1
}
cost_context_counts_the_loops_of_every_class() {
  context_run loops 3 || return 1
  bad=0
  while IFS= read -r row; do
    [ -n "$row" ] && { context_expect "$out" "$row" || bad=1; }
  done <<'EOS'
1 1 1 0.01 0.6
2-3 2 5 0.05 3.1
4-7 2 11 0.11 6.9
8-15 2 23 0.23 14.5
16-31 2 47 0.47 29.6
32+ 1 32 0.32 20.1
Total 10 119 1.19 74.8
From 8 rounds: 5 loops, 102 rounds, 1.02 $, 64.2%, 0.204 $ per loop. Context of the main session, median 0, from 119 rounds.
EOS
  case $out in *'All costs of the window 1.59 $'*) ;; *) echo "the costs of the window are not 1.59 $, hands included"; bad=1 ;; esac
  return $bad
}
cost_context_counts_no_loop_in_a_hand_file() {
  context_run hand 3 || return 1
  bad=0
  context_expect "$out" 'Total 1 2 0.02 2.7' || bad=1
  context_expect "$out" '32+ 0 0 0.00 0.0' || bad=1
  return $bad
}
cost_context_ends_a_loop_at_an_input_and_not_at_a_tool_result() {
  context_run eingaben 3 || return 1
  bad=0
  context_expect "$out" '1 1 1 0.01 12.5' || bad=1
  context_expect "$out" '2-3 1 3 0.03 37.5' || bad=1
  context_expect "$out" '4-7 1 4 0.04 50.0' || bad=1
  return $bad
}
cost_context_keeps_a_meta_line_and_a_summary_inside_the_loop() {
  context_run meta 3 || return 1
  bad=0
  context_expect "$out" '4-7 1 4 0.04 100.0' || bad=1
  context_expect "$out" 'Total 1 4 0.04 100.0' || bad=1
  return $bad
}
# THE CAP: S, g, K and r computed by hand beside the fixture, T* and C* computed here from the formula on them.
cost_context_computes_the_cap_from_its_inputs() {
  context_run deckel 0 || return 1
  bad=0
  context_expect "$out" 'S 60000 tokens: context of the first round after a compaction in a main file, median of 2.' || bad=1
  context_expect "$out" 'g 4000 tokens per round: mean of the differences of consecutive rounds of a main file with no compaction between them, from 5 pairs.' || bad=1
  context_expect "$out" 'K 0.800 $ = 0.480 measured + 0.320 estimated. Measured: cache write of the first round after a compaction, mean of 2, as --causes. Estimated, not in the transcript: the compaction call, preTokens median 100000 * r + postTokens median 15000 * output price 20 $/M, from 2 and 2 lines.' || bad=1
  context_expect "$out" 'r 0.2 $/M: read price of claude-opus-5-5 in prices.tsv, the model of 8 of the 9 rounds of the main session with a price.' || bad=1
  want=$(python3 -I -c '
import math
S, g, K, r = 60000, 4000, 0.80, 0.2 / 1e6
t = math.sqrt(2 * K / (r * g))
print("T* %.1f rounds" % t)
print("C* %d tokens" % round(S + g * t))')
  context_expect "$out" "$(printf '%s\n' "$want" | sed -n 1p)" || bad=1
  context_expect "$out" "$(printf '%s\n' "$want" | sed -n 2p)" || bad=1
  case $out in *'Context of the main session, median 70000, from 9 rounds.'*) ;; *) echo "the median context of the main session is not 70000 from 9 rounds"; bad=1 ;; esac
  return $bad
}
# NO NUMBER WITHOUT ITS INPUTS: a window without a compaction has no S and no K, one with a compaction between its only
# two rounds no g. Each prints the loops, every input it has, one line of reason and no C*, exit 3 as the format guard.
cost_context_gives_no_cap_without_a_compaction() {
  context_run none 3 || return 1
  bad=0
  context_expect "$out" 'Total 2 5 0.05 100.0' || bad=1
  last=$(printf '%s\n' "$out" | tail -n 1)
  case $last in 'no C*: S is missing, no first round after a compaction in a main file; '*'K is missing'*) ;; *) echo "the last line is not the reason without S and K: $last"; bad=1 ;; esac
  printf '%s\n' "$out" | awk '$1 == "C*" || $1 == "T*" { f = 1 } END { exit !f }' && { echo "a C* or T* is printed without a compaction"; bad=1; }
  return $bad
}
cost_context_gives_no_cap_without_a_pair_of_rounds() {
  context_run wenig 3 || return 1
  bad=0
  last=$(printf '%s\n' "$out" | tail -n 1)
  [ "$last" = 'no C*: g is missing, no pair of consecutive rounds with no compaction between them.' ] || { echo "the last line is not the reason without g: $last"; bad=1; }
  context_expect "$out" 'S 50000 tokens: context of the first round after a compaction in a main file, median of 1.' || bad=1
  return $bad
}
cost_context_goes_with_the_window_and_no_other_report() {
  w=$(mktemp -d); context_world "$w" deckel || return 1
  bad=0
  out=$(cost_tool "$w" --context --since 2026-10-10 --until 2026-10-10 --exclude nichtda 2>&1); rc=$?
  case $rc:$out in '0:mk-cost --context  2026-10-10..2026-10-10  '*) ;; *) echo "--context with a window ended $rc: $(printf '%s\n' "$out" | head -1)"; bad=1 ;; esac
  while IFS='|' read -r args why; do
    [ -n "$args" ] || continue
    # shellcheck disable=SC2086
    out=$(cost_tool "$w" $args 2>&1); rc=$?
    [ "$rc" = 2 ] || { echo "[$args] ended $rc, expected 2: $(printf '%s\n' "$out" | head -1)"; bad=1; continue; }
    [ "$(printf '%s\n' "$out" | grep -c .)" = 1 ] || { echo "[$args] said more than one line"; bad=1; }
    case $out in *"$why"*) ;; *) echo "[$args] is not refused for its reason ($why): $out"; bad=1 ;; esac
  done <<EOS
--context --hands|--hands and --context do not go together
--what-if --context|--what-if and --context do not go together
--context --causes|--causes and --context do not go together
--context --compare $CMP_A $CMP_B|--compare and --context do not go together
EOS
  return $bad
}
# THE COMMAND SAYS WHAT --context PRINTS: the word, the cap and that its compaction call is estimated.
cost_context_is_named_by_the_command() {
  body=$(awk '/^---$/ { n++; next } n >= 2' "$ROOT/commands/cost.md")
  bad=0
  case $body in *'`--context`'*) ;; *) echo 'commands/cost.md says nothing of `--context`'; bad=1 ;; esac
  case $body in *'`C*`'*) ;; *) echo 'commands/cost.md does not name the cap `C*`'; bad=1 ;; esac
  case $body in *'**estimated**'*) ;; *) echo 'commands/cost.md does not say that a part of K is **estimated**'; bad=1 ;; esac
  return $bad
}
# WITHOUT --context THE FIVE REPORTS PRINT THE BYTES THEY PRINTED AT be9243b, the commit before the word: the table,
# --hands, --what-if, --compare and --causes on their canonical worlds, the fixture directory and the day of the prices
# left out, hashed. The hashes were taken from the tool of be9243b on these worlds (MK-B2b); the four that the check
# above holds at 92b9152 are the same, and a change of a report's bytes on purpose takes new hashes, and says so.
# RETAKEN AT MK-ENGLISCH (2026-11-09): the reports are printed in English now, which changes every byte on purpose, so the five
# hashes here and the four of the check below are the ones of the English tool on the same worlds. What they hold from here on
# is that the reports stay what the by-hand checks above and below them read, not what the German tool of be9243b printed.
cost_reports_print_their_bytes_without_context() {
  _sha() { sed 's/Prices as of [0-9-]*/Prices as of S/' | python3 -I -c 'import hashlib, sys; print(hashlib.sha256(sys.stdin.buffer.read()).hexdigest()[:16])'; }
  bad=0
  cost_canon || return 1
  got_t=$(printf '%s\n' "$out" | _sha)
  hands_canon || return 1
  got_h=$(printf '%s\n' "$out" | sed "s#$w#W#g" | _sha)
  whatif_canon || return 1
  got_w=$(printf '%s\n' "$out" | _sha)
  compare_canon base
  [ "$_rc" = 0 ] || { echo "--compare ended $_rc"; return 1; }
  got_c=$(printf '%s\n' "$out" | _sha)
  causes_run alle --since 2026-10-01 --until 2026-10-15 --exclude zeta || return 1
  got_k=$(printf '%s\n' "$out" | _sha)
  while read -r name want got; do
    [ "$want" = "$got" ] || { echo "$name prints other bytes than at be9243b: $got, there $want"; bad=1; }
  done <<EOS
table 4ede9014e39e26f8 $got_t
--hands aebbca0e1687fd52 $got_h
--what-if 62ba397e1659ecf1 $got_w
--compare 281966bd49ee3355 $got_c
--causes 18adbc9bee364b3b $got_k
EOS
  return $bad
}

