check 'mk-cost --what-if and --compare print the same bytes twice'                          cost_whatif_and_compare_print_the_same_bytes_twice
check 'README and GUIDE name every word mk-cost takes'                                       cost_docs_name_every_word_the_tool_takes
check 'mk-cost --causes names the first round of a file Start'                               cost_causes_names_the_first_round_of_a_file_start
check 'mk-cost --causes names a write within the ttl of the round before Growth'            cost_causes_names_a_write_within_the_ttl_growth
check 'mk-cost --causes names a gap over a 5m ttl expired'                                cost_causes_names_a_gap_over_a_5m_ttl_expired
check 'mk-cost --causes names a gap over a 1h ttl idle'                                  cost_causes_names_a_gap_over_a_1h_ttl_idle
check 'mk-cost --causes names the first round after a compaction after-compaction'         cost_causes_names_the_first_round_after_a_compaction
check 'mk-cost --causes counts a write that follows no rule as Other'                         cost_causes_counts_a_write_that_follows_no_rule_as_rest
check 'mk-cost --causes keeps a gap of exactly 5m within the ttl and one past it out'        cost_causes_holds_the_5m_bound
check 'mk-cost --causes keeps a gap of exactly 1h within the ttl and one past it out'        cost_causes_holds_the_1h_bound
check 'mk-cost --causes gives a round that writes 5m and 1h one cause and both ttls'         cost_causes_gives_a_5m_and_1h_write_one_cause_and_both_ttls
check 'mk-cost --causes counts a compaction in two files once, with trigger and context'     cost_causes_counts_a_compaction_in_two_files_once
check 'mk-cost --causes judges the first round of a window by the round before it'           cost_causes_judges_the_first_round_of_a_window_by_the_round_before
check 'mk-cost --causes sums to the write share of the table in the same window'             cost_causes_sums_to_the_write_share_of_the_table
check 'mk-cost --causes goes with the window and with no other report'                       cost_causes_goes_with_the_window_and_no_other_report
